document.addEventListener('keydown', e => {
    keys[e.code] = true;
    // Prevent page scroll on game keys
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(e.code)) {
        e.preventDefault();
    }
});
document.addEventListener('keyup', e => { keys[e.code] = false; });
canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    mouse.x = e.clientX - rect.left + camera.x;
    mouse.y = e.clientY - rect.top + camera.y;
});
canvas.addEventListener('mousedown', e => {
    mouse.down = true;
    mouse.justPressed = true;
});
canvas.addEventListener('mouseup', e => { mouse.down = false; });
canvas.addEventListener('contextmenu', e => e.preventDefault());

// Collision detection
function rectCollide(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function pointInRect(px, py, r) {
    return px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;
}

// Particle system
// Particle system. Global cap keeps the screen readable — when the game
// gets busy (big bosses, multi-explosion screens) we'd otherwise drown in
// floating dust. Excess spawn requests beyond MAX_PARTICLES are dropped
// instead of clobbering the array; this is the single biggest "professional
// game polish" cleanup.
const MAX_PARTICLES = 280;
function spawnParticles(x, y, color, count, speed) {
    // Soft cap — if we're already at limit, refuse new spawns so big hits
    // don't crush framerate and so the screen stays readable.
    const slack = Math.max(0, MAX_PARTICLES - particles.length);
    if (slack === 0) return;
    const actualCount = Math.min(count, slack);
    for (let i = 0; i < actualCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * speed + 1;
        particles.push({
            x, y, vx: Math.cos(angle) * spd, vy: Math.sin(angle) * spd,
            life: 1, decay: 0.02 + Math.random() * 0.03,
            size: 2 + Math.random() * 4, color
        });
    }
}

function spawnExplosion(x, y) {
    spawnParticles(x, y, '#ff4400', 15, 5);
    spawnParticles(x, y, '#ffaa00', 10, 3);
    spawnParticles(x, y, '#ffffff', 5, 2);
    screenShake = 8;
    // Shockwave ring for visual impact
    shockwaves.push({ x, y, r: 6, maxR: 80, color: '#ffaa44', alpha: 1 });
    audio.play('explosion');
}

// Spawn a brief expanding ring (used for big hits, crits, evolution etc.).
// Capped so screen stays readable in busy fights.
const MAX_SHOCKWAVES = 24;
function spawnShockwave(x, y, maxR, color) {
    if (shockwaves.length >= MAX_SHOCKWAVES) return;
    shockwaves.push({ x, y, r: 4, maxR: maxR || 100, color: color || '#ffffff', alpha: 1 });
}

// Spawn a floating damage number above an enemy when it gets hit.
// `kind` can be 'normal', 'crit', 'burn', 'aoe' — tints the text accordingly.
function spawnDamageNumber(x, y, dmg, kind) {
    const colors = {
        normal: '#ffffff',
        crit:   '#ffdd44',
        burn:   '#ff6622',
        aoe:    '#ff44aa',
        heal:   '#66ff88'
    };
    damageNumbers.push({
        x: x + (Math.random() - 0.5) * 12,
        y: y - 4,
        vx: (Math.random() - 0.5) * 1.4,
        vy: -2.2 - Math.random() * 0.6,
        text: (kind === 'crit' ? 'CRIT ' : '') + Math.round(dmg),
        color: colors[kind] || '#ffffff',
        life: kind === 'crit' ? 60 : 45,
        maxLife: kind === 'crit' ? 60 : 45,
        size: kind === 'crit' ? 18 : 13
    });
}

// Trigger short hitstop (gameplay freeze for impact). dur in frames.
function applyHitStop(dur) {
    if (dur > hitStop) hitStop = dur;
}

function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.1;
        p.life -= p.decay;
        if (p.life <= 0) particles.splice(i, 1);
    }
    // Float texts
    for (let i = floatTexts.length - 1; i >= 0; i--) {
        const t = floatTexts[i];
        t.y -= 1.5;
        t.life--;
        if (t.life <= 0) floatTexts.splice(i, 1);
    }

    // Damage numbers - drift up and fade
    for (let i = damageNumbers.length - 1; i >= 0; i--) {
        const d = damageNumbers[i];
        d.x += d.vx;
        d.y += d.vy;
        d.vy += 0.06;        // tiny gravity so they arc
        d.life--;
        if (d.life <= 0) damageNumbers.splice(i, 1);
    }

    // Shockwave rings expand and fade
    for (let i = shockwaves.length - 1; i >= 0; i--) {
        const s = shockwaves[i];
        s.r += 4;
        s.alpha -= 0.04;
        if (s.alpha <= 0 || s.r >= s.maxR) shockwaves.splice(i, 1);
    }

    // Tick screen-flash overlays
    if (hitFlash > 0) hitFlash = Math.max(0, hitFlash - 0.06);
    if (critFlash > 0) critFlash = Math.max(0, critFlash - 0.05);
}

// Coins - bounce around, get pulled to player when close, collected on contact
function updateCoins() {
    // Combo timer decay
    if (comboTimer > 0) {
        comboTimer--;
        if (comboTimer <= 0) comboCount = 0;
    }

    for (let i = coinPickups.length - 1; i >= 0; i--) {
        const c = coinPickups[i];
        c.life--;
        if (c.life <= 0) { coinPickups.splice(i, 1); continue; }

        // Magnet effect - pull toward player when nearby
        const dx = (player.x + player.w / 2) - c.x;
        const dy = (player.y + player.h / 2) - c.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 120) {
            c.vx += (dx / dist) * 0.6;
            c.vy += (dy / dist) * 0.6;
        }

        // Gravity & drag
        c.vy += 0.25;
        c.vx *= 0.96;
        c.vy *= 0.96;
        c.x += c.vx;
        c.y += c.vy;

        // Bounce on platforms
        for (const plat of platforms) {
            if (c.x > plat.x && c.x < plat.x + plat.w && c.y > plat.y && c.y < plat.y + 8 && c.vy > 0) {
                c.y = plat.y;
                c.vy *= -0.5;
            }
        }

        // Pickup
        if (dist < 18) {
            if (c.robotCoin) {
                player.robotCoins += c.value;
                spawnParticles(c.x, c.y, '#ff00ff', 8, 4);
                floatTexts.push({ text: '+1 RC', x: c.x, y: c.y, life: 50, color: '#ff44ff' });
                audio.play('keyPickup');
                if (typeof save !== 'undefined') save.bumpStat('totalRC', c.value);
            } else if (c.scrap) {
                player.scrap += c.value;
                spawnParticles(c.x, c.y, '#ff8844', 4, 2);
                audio.play('coin', { throttle: 60 });
                if (typeof save !== 'undefined') save.bumpStat('totalScrap', c.value);
            } else {
                player.coins += c.value;
                spawnParticles(c.x, c.y, '#ffdd44', 4, 2);
                audio.play('coin', { throttle: 60 });
                if (typeof save !== 'undefined') save.bumpStat('totalCoins', c.value);
            }
            coinPickups.splice(i, 1);
        }
    }
}

// Health drops
function updateHealthDrops() {
    for (let i = healthDrops.length - 1; i >= 0; i--) {
        const h = healthDrops[i];
        h.life--;
        if (h.life <= 0) { healthDrops.splice(i, 1); continue; }

        // Magnet
        const dx = (player.x + player.w / 2) - h.x;
        const dy = (player.y + player.h / 2) - h.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 100) {
            h.vx += (dx / dist) * 0.5;
            h.vy += (dy / dist) * 0.5;
        }

        h.vy += 0.25;
        h.vx *= 0.95;
        h.vy *= 0.97;
        h.x += h.vx;
        h.y += h.vy;

        // Bounce on platforms
        for (const plat of platforms) {
            if (h.x > plat.x && h.x < plat.x + plat.w && h.y > plat.y && h.y < plat.y + 8 && h.vy > 0) {
                h.y = plat.y;
                h.vy *= -0.4;
            }
        }

        // Pickup
        if (dist < 22) {
            player.hp = Math.min(player.maxHp, player.hp + h.heal);
            healthDrops.splice(i, 1);
            spawnParticles(h.x, h.y, '#ff66aa', 8, 3);
            audio.play('heal');
        }
    }
}

// ============================================================================
// CRATE SYSTEM (rarity-based loot drops)
// ============================================================================
// 5 tiers. Each crate stores its rarity + pre-rolled reward so opening is
// instant and feedback-rich. Bosses ALWAYS drop a crate (rarity scales with
// stage). Mini-bosses + mech/heavy enemies have a chance based on stage.
//
// Rarities:
//   common    — small coin/scrap bonus
//   rare      — bigger coin payout + chance of a weapon unlock
//   epic      — big coin haul + small RC + sometimes a free upgrade level
//   legendary — huge payout + RC + +1 free weapon upgrade level
//   mythic    — jackpot: full heal, max-HP boost, big RC, +1 weapon upgrade,
//               and a guaranteed weapon unlock if any are still locked
const CRATE_DEFS = {
    common:    { name: 'COMMON CRATE',    color: '#bbbbbb', glow: '#ffffff', size: 18, weight: 100 },
    rare:      { name: 'RARE CRATE',      color: '#44aaff', glow: '#88ddff', size: 20, weight: 50 },
    epic:      { name: 'EPIC CRATE',      color: '#aa44ff', glow: '#dd88ff', size: 22, weight: 22 },
    legendary: { name: 'LEGENDARY CRATE', color: '#ffaa00', glow: '#ffdd44', size: 26, weight: 9 },
    mythic:    { name: 'MYTHIC CRATE',    color: '#ff44ee', glow: '#ff88ff', size: 30, weight: 2 }
};
const CRATE_ORDER = ['common', 'rare', 'epic', 'legendary', 'mythic'];

// Pick a crate rarity, biased by stage progression and an optional luck bonus
// (boss kills get +luck so they feel rewarding).
//   bossDrop: when true, the roll is BIASED HEAVILY toward epic/leg/mythic
//             so dropping a boss never feels like a fizzle.
function rollCrateRarity(luckBonus, bossDrop) {
    luckBonus = luckBonus || 0;
    // Late-game stages get a flat boost to higher rarities.
    const stageBoost = currentStage * 0.10;
    const totalLuck = luckBonus + stageBoost;
    if (bossDrop) {
        // Boss-drop table — guaranteed at least EPIC. Mythic chance climbs
        // with luck/stage. Roll uniform random, then map to thresholds.
        // Base table: legendary 35%, mythic 18%, epic 47%.
        // Luck shifts mythic up by up to +25% and legendary up by +15%.
        const myth = Math.min(0.65, 0.18 + totalLuck * 0.30);
        const leg  = Math.min(0.55, 0.35 + totalLuck * 0.20);
        const r = Math.random();
        if (r < myth) return 'mythic';
        if (r < myth + leg) return 'legendary';
        return 'epic';
    }
    // Build cumulative weights, biased by luck (mythic/legendary get boosted).
    const weights = {
        common:    Math.max(8, CRATE_DEFS.common.weight    * (1 - totalLuck * 0.5)),
        rare:      CRATE_DEFS.rare.weight                  * (1 + totalLuck * 0.2),
        epic:      CRATE_DEFS.epic.weight                  * (1 + totalLuck * 0.6),
        legendary: CRATE_DEFS.legendary.weight             * (1 + totalLuck * 1.4),
        mythic:    CRATE_DEFS.mythic.weight                * (1 + totalLuck * 2.5)
    };
    const total = weights.common + weights.rare + weights.epic + weights.legendary + weights.mythic;
    let r = Math.random() * total;
    for (const k of CRATE_ORDER) {
        if (r < weights[k]) return k;
        r -= weights[k];
    }
    return 'common';
}

// Pop a crate into the world. spawnX/Y is where the enemy died.
// opts: { bossDrop: bool } — boss drops trigger a cinematic on legendary/mythic
function dropCrate(spawnX, spawnY, rarity, opts) {
    if (!rarity) rarity = rollCrateRarity(0);
    const def = CRATE_DEFS[rarity];
    crates.push({
        x: spawnX, y: spawnY,
        vx: (Math.random() - 0.5) * 4,
        vy: -6 - Math.random() * 3,
        rarity, def,
        life: 1500,           // 25 seconds before despawn
        bobPhase: Math.random() * Math.PI * 2,
        landed: false,
        opening: false,
        openTimer: 0,
        bossDrop: !!(opts && opts.bossDrop)
    });
}

function openCrate(c) {
    const r = c.rarity;
    const def = c.def;
    const rewards = [];
    // Coin payout — scales with rarity
    let coins = 0, scrap = 0, rc = 0, hpBoost = 0, healAmt = 0;
    let unlockWeapon = -1, freeUpgrade = false;
    if (r === 'common')         { coins = 50 + Math.floor(Math.random() * 30);  scrap = 8; }
    else if (r === 'rare')      { coins = 180 + Math.floor(Math.random() * 70); scrap = 18; rc = 2; }
    else if (r === 'epic')      { coins = 500 + Math.floor(Math.random() * 200); scrap = 38; rc = 6; healAmt = 60; }
    else if (r === 'legendary') { coins = 1200 + Math.floor(Math.random() * 400); scrap = 80; rc = 14; hpBoost = 25; freeUpgrade = true; }
    else if (r === 'mythic')    { coins = 3000 + Math.floor(Math.random() * 800); scrap = 160; rc = 32; hpBoost = 75; freeUpgrade = true; healAmt = player.maxHp; }
    // Try to unlock a still-locked weapon for rare+. Legendary and mythic
    // strongly prefer CRATES-ONLY mythic weapons (PHOENIX, STORMCALLER, etc.)
    // — these are weapons the kid will never see in the shop.
    if (r === 'rare' || r === 'epic' || r === 'legendary' || r === 'mythic') {
        // Bucket A: shop weapons not yet owned (rare/epic mostly draw from here)
        const shopCandidates = [];
        // Bucket B: crates-only mythic weapons not yet owned (legendary/mythic prefer)
        const cratesOnlyCandidates = [];
        for (let i = 0; i < WEAPONS.length; i++) {
            const w = WEAPONS[i];
            if (!w || w.dev) continue;
            if (player.weaponsUnlocked[i]) continue;
            if (w.name && w.name.includes('placeholder')) continue;
            if (w.cratesOnly) cratesOnlyCandidates.push(i);
            else shopCandidates.push(i);
        }
        let unlockChance = 0;
        if (r === 'rare') unlockChance = 0.20;
        else if (r === 'epic') unlockChance = 0.45;
        else if (r === 'legendary') unlockChance = 1.0;
        else if (r === 'mythic') unlockChance = 1.0;
        if (Math.random() < unlockChance) {
            // For mythic, ALWAYS try to give a crates-only mythic weapon first.
            // For legendary, prefer mythic weapons but fall back to shop.
            // For epic/rare, draw from shop pool.
            let pool = shopCandidates;
            if (r === 'mythic' && cratesOnlyCandidates.length > 0) pool = cratesOnlyCandidates;
            else if (r === 'legendary' && cratesOnlyCandidates.length > 0 && Math.random() < 0.7) pool = cratesOnlyCandidates;
            if (pool.length === 0) pool = shopCandidates;
            if (pool.length > 0) {
                unlockWeapon = pool[Math.floor(Math.random() * pool.length)];
            }
        }
    }
    // Apply rewards
    if (coins > 0)  { player.coins += coins; rewards.push(`+${coins}¢`); }
    if (scrap > 0)  { player.scrap += scrap; rewards.push(`+${scrap}🔩`); }
    if (rc > 0)     { player.robotCoins += rc; rewards.push(`+${rc}RC`); }
    if (healAmt > 0){ player.hp = Math.min(player.maxHp, player.hp + healAmt); rewards.push(`+${healAmt}HP`); }
    if (hpBoost > 0){ player.maxHp += hpBoost; player.hp += hpBoost; rewards.push(`+${hpBoost} MAX HP`); }
    if (unlockWeapon >= 0) {
        player.weaponsUnlocked[unlockWeapon] = true;
        // Auto-equip new mythic weapon for the cinematic feel
        if (WEAPONS[unlockWeapon] && WEAPONS[unlockWeapon].cratesOnly) {
            player.weaponTier = unlockWeapon;
        }
        rewards.push(`UNLOCKED: ${WEAPONS[unlockWeapon].name}`);
    }
    if (freeUpgrade) {
        if (!player.weaponLevels) player.weaponLevels = {};
        const t = player.weaponTier;
        const cur = player.weaponLevels[t] || 0;
        if (cur < WEAPON_UPGRADE_MAX) {
            player.weaponLevels[t] = cur + 1;
            rewards.push(`★ ${WEAPONS[t].name} → LV${cur + 1}`);
        }
    }
    // Big screen feedback
    spawnParticles(c.x, c.y, def.glow, 40, 12);
    spawnShockwave(c.x, c.y, 80, def.glow);
    if (r === 'legendary' || r === 'mythic') {
        spawnShockwave(c.x, c.y, 220, def.color);
        screenShake = Math.max(screenShake, r === 'mythic' ? 26 : 16);
    }

    // ===== BOSS-DROP CUTSCENE FOR LEGENDARY / MYTHIC =====
    // For boss drops at legendary or mythic rarity, trigger a full-screen
    // reveal cinematic so the kid feels the drop. Common/rare/epic remain
    // instant pickup with floating-text feedback.
    if (c.bossDrop && (r === 'legendary' || r === 'mythic')) {
        startCrateCutscene(c, r, def, {
            coins, scrap, rc, hpBoost, healAmt,
            unlockWeapon, freeUpgrade
        });
        return;   // skip floating text — cutscene handles all UI
    }

    // Floating rewards (stacked vertically)
    for (let i = 0; i < rewards.length; i++) {
        floatTexts.push({
            text: rewards[i],
            x: c.x, y: c.y - 30 - i * 22,
            life: 100 + i * 10,
            color: def.glow
        });
    }
    // Banner message
    if (typeof shopMessage !== 'undefined') {
        shopMessage = {
            text: `★ ${def.name} OPENED ★`,
            timer: r === 'mythic' ? 220 : 140,
            color: def.glow
        };
    }
    if (typeof audio !== 'undefined') {
        try { audio.play(r === 'mythic' || r === 'legendary' ? 'bossKill' : 'keyPickup'); } catch (e) {}
    }
}

// ============================================================================
// CRATE OPENING CUTSCENE (legendary / mythic boss drops)
// ============================================================================
// Full-screen cinematic that pauses normal gameplay updates and reveals the
// new weapon + reward payout in stages:
//   Act 0 (0..50)    crate hovers center, glows + spins
//   Act 1 (50..120)  crate explodes open, particle burst
//   Act 2 (120..260) weapon name + flavor flies in
//   Act 3 (260..420) coin/scrap/RC/HP rewards stack on
//   Act 4 (420..480) "TAP ANY KEY TO CONTINUE" — wait
let crateCutscene = null;

function startCrateCutscene(c, rarity, def, payload) {
    crateCutscene = {
        rarity, def,
        timer: 0,
        weaponIdx: payload.unlockWeapon,
        coins: payload.coins,
        scrap: payload.scrap,
        rc: payload.rc,
        hpBoost: payload.hpBoost,
        healAmt: payload.healAmt,
        freeUpgrade: payload.freeUpgrade,
        // Random sparkle anchors so the burst doesn't look identical each time
        sparkles: Array.from({ length: 60 }, () => ({
            ang: Math.random() * Math.PI * 2,
            spd: 2 + Math.random() * 6,
            life: 90 + Math.random() * 120
        }))
    };
    // Pause-in sound
    if (typeof audio !== 'undefined') {
        try { audio.play('bossKill'); } catch (e) {}
    }
    screenShake = Math.max(screenShake, 18);
}

function updateCrateCutscene() {
    if (!crateCutscene) return false;
    crateCutscene.timer++;
    // Allow skip after Act 2 reveal completes (~t >= 240)
    if (crateCutscene.timer > 240) {
        const skipKey = (typeof keys !== 'undefined') &&
            (keys['Enter'] || keys['Space'] || keys['KeyE'] || keys['NumpadEnter']);
        if (skipKey) crateCutscene.timer = 999;
    }
    if (crateCutscene.timer > 480) {
        crateCutscene = null;
    }
    return true;
}

function drawCrateCutscene() {
    if (!crateCutscene) return;
    const cc = crateCutscene;
    const t = cc.timer;
    const cx = canvas.width / 2;
    const cy = canvas.height / 2;
    const def = cc.def;
    // Backdrop dim
    ctx.save();
    const dimAlpha = Math.min(0.85, t / 30);
    ctx.fillStyle = `rgba(0, 0, 10, ${dimAlpha})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Concentric rarity rings
    for (let r = 0; r < 4; r++) {
        const baseR = 80 + r * 80 + Math.sin((t + r * 8) * 0.06) * 18;
        ctx.strokeStyle = def.glow;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 22;
        ctx.lineWidth = 2 - r * 0.3;
        ctx.globalAlpha = (cc.rarity === 'mythic' ? 0.7 : 0.45) * (1 - r * 0.18);
        ctx.beginPath();
        ctx.arc(cx, cy, baseR, 0, Math.PI * 2);
        ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;

    // ACT 0: crate appears, spins
    if (t < 60) {
        const k = t / 60;
        const scale = 1 + k * 1.8;
        const rot = t * 0.12;
        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate(rot);
        ctx.scale(scale, scale);
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.glow;
        ctx.shadowBlur = 24;
        ctx.fillRect(-30, -30, 60, 60);
        ctx.fillStyle = def.glow;
        ctx.fillRect(-26, -26, 52, 6);
        ctx.fillStyle = '#000000';
        ctx.fillRect(-30, -2, 60, 4);
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 36px Courier New';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        if (cc.rarity === 'mythic') ctx.fillText('★', 0, 1);
        else ctx.fillText('◆', 0, 1);
        ctx.restore();
    }
    // ACT 1: explode open
    else if (t < 120) {
        const k = (t - 60) / 60;
        ctx.save();
        ctx.translate(cx, cy);
        // Burst rays
        ctx.strokeStyle = def.glow;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 30;
        ctx.lineWidth = 4 * (1 - k);
        for (let s = 0; s < 12; s++) {
            const ang = (s / 12) * Math.PI * 2;
            const r1 = 60 + k * 80;
            const r2 = 200 + k * 220;
            ctx.beginPath();
            ctx.moveTo(Math.cos(ang) * r1, Math.sin(ang) * r1);
            ctx.lineTo(Math.cos(ang) * r2, Math.sin(ang) * r2);
            ctx.stroke();
        }
        // Sparkle particles
        for (const s of cc.sparkles) {
            const px = Math.cos(s.ang) * s.spd * (k * 60);
            const py = Math.sin(s.ang) * s.spd * (k * 60);
            ctx.fillStyle = def.glow;
            ctx.shadowColor = def.color;
            ctx.shadowBlur = 12;
            ctx.beginPath();
            ctx.arc(px, py, 2 + Math.random() * 2, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    }
    // ACT 2+: text reveals
    if (t >= 100) {
        const k = Math.min(1, (t - 100) / 50);
        ctx.save();
        ctx.globalAlpha = k;
        ctx.textAlign = 'center';
        // Rarity label top
        ctx.fillStyle = def.glow;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 18;
        ctx.font = 'bold 36px Courier New';
        ctx.fillText(cc.rarity.toUpperCase() + ' DROP', cx, cy - 220);
        ctx.font = 'bold 14px Courier New';
        ctx.fillStyle = '#ffffff';
        ctx.fillText('★ BOSS LOOT ★', cx, cy - 196);
        ctx.shadowBlur = 0;

        // Weapon reveal
        if (cc.weaponIdx >= 0) {
            const w = WEAPONS[cc.weaponIdx];
            const k2 = Math.min(1, Math.max(0, (t - 140) / 60));
            ctx.globalAlpha = k2;
            ctx.fillStyle = w.glow || def.glow;
            ctx.shadowColor = w.color || def.color;
            ctx.shadowBlur = 22;
            ctx.font = 'bold 44px Courier New';
            ctx.fillText('NEW WEAPON', cx, cy - 80);
            ctx.font = 'bold 60px Courier New';
            ctx.fillText(w.name, cx, cy - 20);
            ctx.shadowBlur = 14;
            ctx.font = 'italic 18px Courier New';
            ctx.fillStyle = '#ffeeaa';
            // Word-wrap flavor across the width
            const flavor = w.flavor || '';
            const maxChars = 60;
            let line = '';
            const words = flavor.split(' ');
            const lines = [];
            for (const word of words) {
                if (line.length + word.length + 1 > maxChars) { lines.push(line); line = word; }
                else line = line ? line + ' ' + word : word;
            }
            if (line) lines.push(line);
            for (let i = 0; i < lines.length; i++) {
                ctx.fillText(lines[i], cx, cy + 24 + i * 22);
            }
            ctx.shadowBlur = 0;
        }

        // Reward stack (coins/scrap/RC/HP)
        if (t > 240) {
            const k3 = Math.min(1, (t - 240) / 80);
            ctx.globalAlpha = k3;
            ctx.fillStyle = '#ffdd44';
            ctx.shadowColor = '#ffaa00';
            ctx.shadowBlur = 12;
            ctx.font = 'bold 22px Courier New';
            const lines = [];
            if (cc.coins) lines.push(`+ ${cc.coins} ¢ COINS`);
            if (cc.scrap) lines.push(`+ ${cc.scrap} 🔩 SCRAP`);
            if (cc.rc)    lines.push(`+ ${cc.rc} RC`);
            if (cc.healAmt) lines.push(`+ ${cc.healAmt} HP HEAL`);
            if (cc.hpBoost) lines.push(`+ ${cc.hpBoost} MAX HP`);
            if (cc.freeUpgrade) lines.push('★ FREE WEAPON UPGRADE ★');
            const baseY = cc.weaponIdx >= 0 ? cy + 110 : cy + 20;
            for (let i = 0; i < lines.length; i++) {
                ctx.fillText(lines[i], cx, baseY + i * 30);
            }
            ctx.shadowBlur = 0;
        }
        ctx.globalAlpha = 1;
        ctx.restore();
    }
    // ACT 4: "Press to continue"
    if (t > 360) {
        ctx.save();
        const blink = Math.sin(t * 0.15) * 0.3 + 0.7;
        ctx.globalAlpha = blink;
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = def.glow;
        ctx.shadowBlur = 8;
        ctx.font = 'bold 16px Courier New';
        ctx.textAlign = 'center';
        ctx.fillText('PRESS ENTER / SPACE / E TO CONTINUE', cx, canvas.height - 50);
        ctx.shadowBlur = 0;
        ctx.restore();
    }
    ctx.restore();
}

function updateCrates() {
    for (let i = crates.length - 1; i >= 0; i--) {
        const c = crates[i];
        c.life--;
        c.bobPhase += 0.08;
        if (c.opening) {
            c.openTimer++;
            if (c.openTimer >= 24) {
                openCrate(c);
                crates.splice(i, 1);
            }
            continue;
        }
        if (c.life <= 0) { crates.splice(i, 1); continue; }
        // Physics
        if (!c.landed) {
            c.vy += 0.4;
            c.vx *= 0.97;
            c.x += c.vx;
            c.y += c.vy;
            // Land on platforms
            for (const plat of platforms) {
                if (plat.type === 'recovery' || plat.type === 'spike' || plat.type === 'laser' || plat.type === 'lava') continue;
                if (c.x > plat.x && c.x < plat.x + plat.w && c.y > plat.y && c.y < plat.y + 14 && c.vy > 0) {
                    c.y = plat.y - 2;
                    c.vy = 0;
                    c.vx = 0;
                    c.landed = true;
                    break;
                }
            }
            // Floor catch
            if (c.y > 600) { c.y = 600; c.vy = 0; c.vx = 0; c.landed = true; }
        }
        // Pickup on touch with player
        const px = player.x + player.w / 2;
        const py = player.y + player.h / 2;
        const dx = px - c.x;
        const dy = py - c.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const grabRange = 24 + (c.def ? c.def.size * 0.5 : 8);
        if (dist < grabRange && !c.opening) {
            c.opening = true;
            c.openTimer = 0;
        }
    }
}

function drawCrates() {
    for (const c of crates) {
        const cx = c.x - camera.x;
        const cy = c.y - camera.y;
        const def = c.def;
        const size = def.size;
        const t = c.bobPhase;
        const bob = c.landed ? Math.sin(t) * 2 : 0;
        ctx.save();
        ctx.translate(cx, cy + bob);
        // Open animation: scale up + flash
        if (c.opening) {
            const k = c.openTimer / 24;
            const scale = 1 + k * 1.4;
            const flash = 1 - k;
            ctx.scale(scale, scale);
            ctx.globalAlpha = flash;
            // Lid burst lines
            for (let r = 0; r < 8; r++) {
                const ang = (r / 8) * Math.PI * 2;
                ctx.strokeStyle = def.glow;
                ctx.lineWidth = 3 * (1 - k);
                ctx.beginPath();
                ctx.moveTo(0, 0);
                ctx.lineTo(Math.cos(ang) * size * (1 + k * 1.5), Math.sin(ang) * size * (1 + k * 1.5));
                ctx.stroke();
            }
        }
        // Outer glow ring (rarity color)
        ctx.shadowColor = def.glow;
        ctx.shadowBlur = c.opening ? 30 : 18;
        // Body — beveled box
        const half = size / 2;
        ctx.fillStyle = def.color;
        ctx.fillRect(-half, -half, size, size);
        // Darker rim
        ctx.fillStyle = '#000000';
        ctx.globalAlpha = 0.35 * (ctx.globalAlpha || 1);
        ctx.fillRect(-half, half - 3, size, 3);
        ctx.fillRect(-half, -half, 3, size);
        ctx.globalAlpha = 1;
        // Highlight strip (top)
        ctx.fillStyle = def.glow;
        ctx.fillRect(-half + 2, -half + 2, size - 4, 3);
        // Lid divider
        ctx.fillStyle = '#000000';
        ctx.fillRect(-half, -2, size, 2);
        // Lock badge / rarity star
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#ffffff';
        ctx.font = `bold ${Math.round(size * 0.55)}px Courier New`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        if (c.rarity === 'mythic') ctx.fillText('★', 0, 1);
        else if (c.rarity === 'legendary') ctx.fillText('◆', 0, 1);
        else if (c.rarity === 'epic') ctx.fillText('●', 0, 1);
        else if (c.rarity === 'rare') ctx.fillText('▲', 0, 1);
        else ctx.fillText('■', 0, 1);
        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';
        ctx.restore();
        // Floating rarity label above the crate (when landed)
        if (c.landed && !c.opening) {
            ctx.save();
            ctx.font = 'bold 11px Courier New';
            ctx.textAlign = 'center';
            ctx.fillStyle = def.glow;
            ctx.shadowColor = def.color;
            ctx.shadowBlur = 6;
            const labelAlpha = c.life < 180 ? (c.life / 180) : 1;   // fade out near despawn
            ctx.globalAlpha = labelAlpha;
            ctx.fillText(c.rarity.toUpperCase(), cx, cy + bob - size - 4);
            ctx.restore();
        }
    }
}

// Shop interaction
function updateShop() {
    // Find shop in range
    activeShop = null;
    for (const s of shops) {
        if (player.x + player.w > s.x - 20 && player.x < s.x + s.w + 20 &&
            player.y + player.h > s.y - 60 && player.y < s.y + s.h) {
            activeShop = s;
            break;
        }
    }

    // Find a hackable terminal in range (for press-E-to-cut-wire interaction).
    // Tracked globally so the draw layer can show a "[E] CUT WIRE" prompt.
    activeTerminal = null;
    for (const term of terminals) {
        if (term.disabled) continue;
        if (player.x + player.w > term.x - 28 && player.x < term.x + term.w + 28 &&
            player.y + player.h > term.y - 60 && player.y < term.y + term.h + 28) {
            activeTerminal = term;
            break;
        }
    }

    // Toggle shop with E (or cut wire if no shop in range but a terminal is)
    if (keys['KeyE'] && !player.shopKeyHeld) {
        if (activeShop) {
            shopOpen = !shopOpen;
        } else if (activeTerminal && activeTerminal.wires && activeTerminal.wires.length) {
            cutNextTerminalWire(activeTerminal);
        }
        player.shopKeyHeld = true;
    }
    if (!keys['KeyE']) player.shopKeyHeld = false;

    // Close if walked away
    if (!activeShop) shopOpen = false;

    // Buy items with number keys / letter keys
    if (shopOpen) {
        // Only developers can see/buy items marked dev:true. Bound at call
        // time via window.isDeveloper() (defined in index.html); fallback to
        // false if the page wrapper isn't available (running game.js standalone).
        const devAllowed = (typeof window !== 'undefined' && typeof window.isDeveloper === 'function')
            ? window.isDeveloper() : false;
        for (const item of SHOP_ITEMS) {
            if (item.dev && !devAllowed) continue;   // hide dev items from non-devs
            let code;
            if (item.key === '0') code = 'Digit0';
            else if (/^[0-9]$/.test(item.key)) code = 'Digit' + item.key;
            else if (SPECIAL_SHOP_KEYS[item.key]) code = SPECIAL_SHOP_KEYS[item.key];
            else code = 'Key' + item.key;
            if (keys[code] && !player.shopBuyHeld) {
                // Determine which currency the item costs (defaults to coins)
                const scrapCost = item.costScrap || 0;
                const rcCost = item.costRC || 0;
                const coinCost = item.cost || 0;
                // If weapon already owned, treat purchase as switch
                if (item.weapon && player.weaponsUnlocked[item.weapon]) {
                    player.weaponTier = item.weapon;
                    shopMessage = { text: `Equipped: ${WEAPONS[item.weapon].name}`, timer: 60, color: WEAPONS[item.weapon].color };
                } else if (item.melee && player.meleeWeaponsUnlocked && player.meleeWeaponsUnlocked[item.melee]) {
                    // Melee weapon already owned — toggle equip / unequip back to bare-fist
                    if (player.activeMelee === item.melee) {
                        player.activeMelee = null;
                        shopMessage = { text: `Unequipped: ${item.meleeName}`, timer: 60, color: '#aaa' };
                    } else {
                        player.activeMelee = item.melee;
                        shopMessage = { text: `Equipped: ${item.meleeName}`, timer: 60, color: item.meleeColor || '#ffdd44' };
                    }
                } else {
                    const canAffordCoins = player.coins >= coinCost;
                    const canAffordScrap = player.scrap >= scrapCost;
                    const canAffordRC = player.robotCoins >= rcCost;
                    if (canAffordCoins && canAffordScrap && canAffordRC) {
                        if (coinCost > 0) player.coins -= coinCost;
                        if (scrapCost > 0) player.scrap -= scrapCost;
                        if (rcCost > 0) player.robotCoins -= rcCost;
                        item.action(player);
                        if (item.switcher) {
                            const newW = WEAPONS[player.weaponTier];
                            shopMessage = { text: `Switched to: ${newW.name}`, timer: 60, color: newW.color };
                        } else if (item.weapon) {
                            const wpn = WEAPONS[item.weapon];
                            shopMessage = { text: `Bought: ${wpn.name}`, timer: 90, color: wpn.color };
                        } else if (item.melee) {
                            shopMessage = { text: `Bought + Equipped: ${item.meleeName}`, timer: 90, color: item.meleeColor || '#ffdd44' };
                        } else {
                            shopMessage = { text: `Bought: ${item.name}`, timer: 60, color: '#00ff66' };
                        }
                        spawnParticles(player.x + player.w / 2, player.y, '#00ffaa', 10, 3);
                    } else {
                        // Tell player WHICH currency was short
                        let msg = 'Not enough coins!';
                        if (!canAffordScrap) msg = `Need ${scrapCost} scrap (have ${player.scrap})`;
                        else if (!canAffordRC) msg = `Need ${rcCost} RC (have ${player.robotCoins})`;
                        shopMessage = { text: msg, timer: 60, color: '#ff3333' };
                    }
                }
                player.shopBuyHeld = true;
            }
        }
        let anyBuy = false;
        for (const item of SHOP_ITEMS) {
            if (item.dev && !devAllowed) continue;
            let code;
            if (item.key === '0') code = 'Digit0';
            else if (/^[0-9]$/.test(item.key)) code = 'Digit' + item.key;
            else if (SPECIAL_SHOP_KEYS[item.key]) code = SPECIAL_SHOP_KEYS[item.key];
            else code = 'Key' + item.key;
            if (keys[code]) anyBuy = true;
        }
        if (!anyBuy) player.shopBuyHeld = false;
    }

    if (shopMessage) {
        shopMessage.timer--;
        if (shopMessage.timer <= 0) shopMessage = null;
    }
}

// ============================================================================
// HEALING STATIONS (Step 2 of polish pass)
// ============================================================================
// Reusable repair pillars scattered through stages. Player walks up, presses E
// to heal to full HP. Station then depletes for 6 seconds before recharging.
// Allies in range get a partial heal when the station fires too.
const HEAL_STATION_RECHARGE = 360;      // 6 seconds at 60fps
const HEAL_STATION_DURATION = 90;       // healing animation length (1.5s)

function spawnHealingStation(x, groundY) {
    healingStations.push({
        x, y: groundY - 60, w: 38, h: 60,
        charge: 1,                     // 0..1 — visual gauge
        cooldown: 0,                   // frames until recharged
        healing: false,
        healTimer: 0,                  // counts up during heal animation
        pulse: Math.random() * Math.PI * 2  // random phase so multiple stations don't blink in sync
    });
}

function updateHealingStations() {
    if (gameState !== 'playing') return;
    activeHealingStation = null;
    for (const s of healingStations) {
        // Pulse animation always ticks
        s.pulse += 0.06;
        // Cooldown recharge
        if (s.cooldown > 0) {
            s.cooldown--;
            s.charge = Math.min(1, 1 - (s.cooldown / HEAL_STATION_RECHARGE));
        } else {
            s.charge = 1;
        }
        // Active heal animation tick
        if (s.healing) {
            s.healTimer++;
            // Steady heal stream — 1.5% of maxHp per frame for ~1.5s totals 100%
            const healPerFrame = Math.max(1, Math.round(player.maxHp * 0.015));
            if (player.hp < player.maxHp) {
                player.hp = Math.min(player.maxHp, player.hp + healPerFrame);
            }
            // Particle stream from station to player
            if (s.healTimer % 2 === 0) {
                const sx = s.x + s.w / 2;
                const sy = s.y + 8;
                const px = player.x + player.w / 2;
                const py = player.y + player.h / 2;
                spawnParticles(sx + (Math.random() - 0.5) * 14, sy + (Math.random() - 0.5) * 14,
                    '#66ff88', 1, 1);
                // Trail toward player
                const t = Math.random();
                const mx = sx + (px - sx) * t;
                const my = sy + (py - sy) * t;
                spawnParticles(mx, my, '#88ffaa', 1, 1);
            }
            // Heal allies in range too (50% heal)
            if (s.healTimer === 1) {
                for (const a of allies) {
                    const dx = (a.x + a.w / 2) - (s.x + s.w / 2);
                    const dy = (a.y + a.h / 2) - (s.y + s.h / 2);
                    if (dx * dx + dy * dy < 180 * 180) {
                        a.hp = Math.min(a.maxHp, a.hp + Math.round(a.maxHp * 0.5));
                        spawnParticles(a.x + a.w / 2, a.y + a.h / 2, '#66ff88', 8, 3);
                    }
                }
            }
            if (s.healTimer >= HEAL_STATION_DURATION) {
                s.healing = false;
                s.healTimer = 0;
                s.cooldown = HEAL_STATION_RECHARGE;
                s.charge = 0;
                spawnShockwave(s.x + s.w / 2, s.y + s.h / 2, 60, '#66ff88');
            }
        }
        // Range detection — slightly bigger than the station so the prompt
        // shows a tiny bit before the player visually walks up to it
        if (player.x + player.w > s.x - 24 && player.x < s.x + s.w + 24 &&
            player.y + player.h > s.y - 30 && player.y < s.y + s.h + 8) {
            activeHealingStation = s;
        }
    }

    // Interaction: pressing E (only when no shop is also in range — shop wins)
    // Reuse the shop's `shopKeyHeld` edge-trigger so we don't double-fire on the
    // same press. We trigger BEFORE the shop logic uses the key, but only when
    // no shop is in range (activeShop is null).
    if (!activeShop && activeHealingStation && keys['KeyE'] && !player.shopKeyHeld) {
        const s = activeHealingStation;
        if (s.cooldown <= 0 && !s.healing) {
            if (player.hp >= player.maxHp) {
                shopMessage = { text: 'Already at full HP', timer: 60, color: '#88ff88' };
            } else {
                s.healing = true;
                s.healTimer = 0;
                spawnParticles(s.x + s.w / 2, s.y + 8, '#66ff88', 18, 5);
                spawnShockwave(s.x + s.w / 2, s.y + 8, 50, '#66ff88');
                audio.play('heal');
                shopMessage = { text: '⚕ REPAIRING ⚕', timer: 90, color: '#66ff88' };
            }
            // Block the shop's edge-trigger from firing this same press
            player.shopKeyHeld = true;
        } else if (s.cooldown > 0) {
            const secs = (s.cooldown / 60).toFixed(1);
            shopMessage = { text: `Recharging (${secs}s)`, timer: 30, color: '#ffaa44' };
            player.shopKeyHeld = true;
        }
    }
}

function drawHealingStations() {
    for (const s of healingStations) {
        const sx = s.x - camera.x;
        const sy = s.y - camera.y;

        const charged = s.cooldown <= 0;
        const pulse = (Math.sin(s.pulse) + 1) * 0.5;  // 0..1
        const baseColor = charged ? '#1a3a28' : '#2a1a18';
        const accentColor = charged ? '#66ff88' : '#ff6644';
        const glowColor = charged ? '#aaffcc' : '#ff8866';

        // Pillar base
        const baseY = sy + s.h - 12;
        ctx.fillStyle = '#222';
        ctx.fillRect(sx - 4, baseY, s.w + 8, 12);
        ctx.fillStyle = '#444';
        ctx.fillRect(sx - 4, baseY, s.w + 8, 3);

        // Pillar body
        ctx.fillStyle = baseColor;
        ctx.fillRect(sx, sy + 16, s.w, s.h - 28);
        // Inner glow channel (lighter)
        ctx.fillStyle = '#0a0a0f';
        ctx.fillRect(sx + 8, sy + 22, s.w - 16, s.h - 40);

        // Charge gauge — vertical bar inside the channel
        const gaugeH = (s.h - 40) * s.charge;
        if (s.charge > 0.01) {
            const grad = ctx.createLinearGradient(0, sy + s.h - 18 - gaugeH, 0, sy + s.h - 18);
            grad.addColorStop(0, glowColor);
            grad.addColorStop(1, accentColor);
            ctx.fillStyle = grad;
            ctx.fillRect(sx + 9, sy + s.h - 18 - gaugeH, s.w - 18, gaugeH);
        }

        // Top emitter dome
        const domeR = 10;
        const cx = sx + s.w / 2;
        const cy = sy + 12;
        ctx.fillStyle = baseColor;
        ctx.beginPath();
        ctx.arc(cx, cy, domeR, Math.PI, 0);
        ctx.fill();

        // Glowing core inside dome
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = charged ? 14 + pulse * 10 : 4;
        ctx.fillStyle = accentColor;
        ctx.beginPath();
        ctx.arc(cx, cy, 4 + pulse * 1.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Big medical cross on the front of the pillar
        ctx.fillStyle = charged ? glowColor : '#552222';
        ctx.shadowColor = accentColor;
        ctx.shadowBlur = charged ? 8 : 0;
        ctx.fillRect(sx + s.w / 2 - 3, sy + 22, 6, 18);
        ctx.fillRect(sx + s.w / 2 - 8, sy + 27, 16, 8);
        ctx.shadowBlur = 0;

        // Side LED indicators
        for (let i = 0; i < 3; i++) {
            const ledY = sy + 22 + i * 8;
            const lit = charged && pulse > i * 0.3;
            ctx.fillStyle = lit ? accentColor : '#222';
            ctx.fillRect(sx + 2, ledY, 3, 3);
            ctx.fillRect(sx + s.w - 5, ledY, 3, 3);
        }

        // Active heal beam
        if (s.healing) {
            const px = (player.x + player.w / 2) - camera.x;
            const py = (player.y + player.h / 2) - camera.y;
            ctx.save();
            const flicker = 0.7 + Math.sin(s.healTimer * 0.4) * 0.3;
            ctx.globalAlpha = flicker;
            ctx.strokeStyle = '#aaffcc';
            ctx.lineWidth = 5 + Math.sin(s.healTimer * 0.6) * 2;
            ctx.shadowColor = '#66ff88';
            ctx.shadowBlur = 18;
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            // Slight bezier curve for organic feel
            const midX = (cx + px) / 2 + Math.sin(s.healTimer * 0.2) * 12;
            const midY = (cy + py) / 2 - 20;
            ctx.quadraticCurveTo(midX, midY, px, py);
            ctx.stroke();
            ctx.shadowBlur = 0;
            ctx.restore();
        }

        // "PRESS E TO REPAIR" hint when in range
        if (activeHealingStation === s) {
            const blink = Math.floor(performance.now() / 400) % 2 === 0;
            if (blink) {
                let text;
                let color;
                if (!charged) {
                    text = `RECHARGING ${(s.cooldown / 60).toFixed(1)}s`;
                    color = '#ffaa44';
                } else if (player.hp >= player.maxHp) {
                    text = 'HP FULL';
                    color = '#88ff88';
                } else {
                    text = 'PRESS E TO REPAIR';
                    color = '#66ff88';
                }
                ctx.fillStyle = color;
                ctx.shadowColor = color;
                ctx.shadowBlur = 8;
                ctx.font = 'bold 12px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText(text, cx, sy - 14);
                ctx.shadowBlur = 0;
                ctx.textAlign = 'left';
            }
        }
    }
}

// Player update
function updatePlayer() {
    if (gameState !== 'playing') return;

    // Animate boss gates opening when player approaches
    for (const bg of bossGates) {
        // Antechamber entry gate: auto-opens on approach, then closes behind
        // the player once they walk past it (locking them in with the warden).
        if (bg.antechamberEntry) {
            const px = player.x + player.w / 2;
            const gx = bg.x + bg.w / 2;
            const dist = Math.abs(px - gx);
            if (!bg.closedBehind) {
                // First phase: auto-open as the player approaches
                if (!bg.open) {
                    if (dist < 200) {
                        bg.animTimer = Math.min(60, bg.animTimer + 1);
                        if (bg.animTimer >= 60) {
                            bg.open = true;
                            spawnParticles(bg.x + bg.w / 2, bg.y + bg.h / 2, bg.color, 30, 6);
                            screenShake = 8;
                        }
                    } else {
                        bg.animTimer = Math.max(0, bg.animTimer - 1);
                    }
                } else if (px > gx + 60) {
                    // Player has crossed past the entry gate — slam it shut
                    bg.open = false;
                    bg.animTimer = 0;
                    bg.closedBehind = true;
                    spawnParticles(bg.x + bg.w / 2, bg.y + bg.h / 2, bg.color, 24, 8);
                    spawnShockwave(bg.x + bg.w / 2, bg.y + bg.h / 2, 80, bg.color);
                    screenShake = 14;
                    if (typeof shopMessage !== 'undefined') {
                        const wardenTheme = getWardenTheme(currentStage);
                        shopMessage = { text: '⚠ MINI-BOSS: WARDEN-K ⚠', timer: 180, color: wardenTheme.glow };
                    }
                    audio.play('bossIntro');
                }
            } else {
                // Phase 2: stays locked closed until warden is dead, then
                // auto-opens permanently so the player can backtrack.
                const wardenAlive = enemies.some(e => e.subtype === 'warden');
                if (!wardenAlive && !bg.open) {
                    bg.open = true;
                    bg.animTimer = 60;
                    spawnParticles(bg.x + bg.w / 2, bg.y + bg.h / 2, '#66ff88', 30, 6);
                    spawnShockwave(bg.x + bg.w / 2, bg.y + bg.h / 2, 80, '#66ff88');
                }
            }
            continue;
        }

        // Standard boss gate logic
        if (bg.open) continue;
        // If this gate requires the warden to be dead, refuse to open while
        // any warden is alive on the field.
        if (bg.requiresWardenDead) {
            const wardenAlive = enemies.some(e => e.subtype === 'warden');
            if (wardenAlive) {
                // Drain the open animation back to zero so we don't sneak through
                bg.animTimer = Math.max(0, bg.animTimer - 1);
                continue;
            }
        }
        const dist = Math.abs((player.x + player.w/2) - (bg.x + bg.w/2));
        if (dist < 200) {
            bg.animTimer = Math.min(60, bg.animTimer + 1);
            if (bg.animTimer >= 60) {
                bg.open = true;
                spawnParticles(bg.x + bg.w / 2, bg.y + bg.h / 2, bg.color, 30, 6);
                screenShake = 8;
            }
        } else {
            bg.animTimer = Math.max(0, bg.animTimer - 1);
        }
    }

    // Boss gate collision - closed boss gates block the player
    for (const bg of bossGates) {
        if (bg.open) continue;
        if (rectCollide(player, bg)) {
            if (player.x + player.w / 2 < bg.x + bg.w / 2) {
                player.x = bg.x - player.w;
            } else {
                player.x = bg.x + bg.w;
            }
            player.vx = 0;
        }
    }

    // Check exit portal collision (advances to next stage)
    for (const ep of exitPortals) {
        if (rectCollide(player, ep)) {
            // Trigger space transition fight before next stage. If the stage
            // defines a spaceCutscene, play it first; the cutscene handler will
            // start the actual space transition once dialogue ends.
            if (gameState === 'playing') {
                const stg = STAGES[currentStage];
                if (stg && stg.spaceCutscene && !stg.spaceCutsceneShown) {
                    stg.spaceCutsceneShown = true;
                    cutscene = {
                        stage: currentStage,
                        lines: stg.spaceCutscene,
                        idx: 0,
                        timer: 0,
                        nextState: 'space'   // signal for cutscene-end transition
                    };
                    player.vx = 0;
                    player.vy = 0;
                    gameState = 'cutscene';
                } else {
                    startSpaceTransition();
                }
            }
        }
    }

    // Check danger zones
    for (const z of dangerZones) {
        if (!z.triggered && player.x >= z.x) {
            z.triggered = true;
            activeWarning = { text: z.text, timer: 150 };
        }
    }
    if (activeWarning) {
        activeWarning.timer--;
        if (activeWarning.timer <= 0) activeWarning = null;
    }

    // Check boss cutscene trigger
    const stage = STAGES[currentStage];
    if (stage && stage.bossTriggerX && player.x >= stage.bossTriggerX && !stage.cutsceneShown) {
        stage.cutsceneShown = true;
        // Stop player movement
        player.vx = 0;
        player.vy = 0;
        // Build the boss arena (open and themed to the boss)
        const boss = enemies.find(e => e.type === 'boss');
        if (boss) {
            buildBossArena(currentStage, player.x, boss);
        }
        // OMEGA-PRIME: special throne-rising cinematic plays BEFORE dialogue.
        if (boss && boss.subtype === 'omega') {
            throneCutscene = {
                timer: 0,
                duration: 240,
                bossX: boss.x, bossY: boss.y,
                playerStartX: player.x - 200,
                playerEndX: boss.x - 250,
                throneCutsceneNext: {
                    stage: currentStage,
                    lines: stage.cutscene,
                    idx: 0,
                    timer: 0
                }
            };
            gameState = 'throneCutscene';
        } else if (boss) {
            // Every other boss now gets a SUBTYPE-SPECIFIC INTRO cinematic
            // (drop-in, rise-from-lava, phase-glitch, transformer-fold-down,
            // etc.) before its dialogue cutscene fires.
            bossIntro = createBossIntro(boss, stage, currentStage);
            gameState = 'bossIntro';
        } else {
            cutscene = {
                stage: currentStage,
                lines: stage.cutscene,
                idx: 0,
                timer: 0
            };
            gameState = 'cutscene';
        }
    }

    // Horizontal movement
    let moveX = 0;
    if (keys['KeyA'] || keys['ArrowLeft']) moveX = -1;
    if (keys['KeyD'] || keys['ArrowRight']) moveX = 1;

    if (!player.dashing) {
        // Per-vehicle speed scaling — bike is fast, hover medium, tank slow,
        // jet fast, starfighter fastest. Robot mode = 1.0×.
        let speedScale = 1;
        if (player.transformed) {
            const speedTable = { bike: 1.7, hover: 1.5, tank: 0.85, jet: 1.6, starfighter: 1.8 };
            speedScale = speedTable[player.vehicleType] || 1.5;
        }
        // Ice-slow effect from arctic icicle hazard hits
        if (player.iceSlowTimer > 0) {
            player.iceSlowTimer--;
            speedScale *= 0.5;
        }
        // FLUTE haste — quickstep buff after firing the band weapon's flute
        if (player.fluteHasteTimer && player.fluteHasteTimer > 0) {
            player.fluteHasteTimer--;
            speedScale *= 1.30;
            // Sparkle trail under feet
            if (player.fluteHasteTimer % 4 === 0) {
                spawnParticles(player.x + player.w/2, player.y + player.h - 4, '#cc88ff', 1, 3);
            }
        }
        player.vx = moveX * player.speed * speedScale;
        if (moveX !== 0) player.facing = moveX;
    }

    if (player.sliding) {
        player.slideTimer--;
        if (player.slideTimer <= 0) {
            player.sliding = false;
            player.h = 40;
        }
    } else {
        player.h = 40;
    }

    // Slide
    if ((keys['KeyS'] || keys['ArrowDown']) && player.onGround && Math.abs(player.vx) > 1 && !player.sliding) {
        player.sliding = true;
        player.slideTimer = 20;
        player.vx = player.facing * 6;
        player.h = 24;
    }

    // Jumping - accept Up Arrow, W, or Space; with coyote time + jump buffer for forgiving feel
    const jumpKey = keys['Space'] || keys['ArrowUp'] || keys['KeyW'];

    // Buffer the jump press so it still works if pressed slightly before landing
    if (jumpKey && !player.jumpHeld) {
        player.jumpBuffer = 8;
    }
    player.jumpHeld = jumpKey;

    if (player.jumpBuffer > 0) player.jumpBuffer--;

    // Coyote time - allow jumping for a few frames after leaving the ground
    if (player.onGround) {
        player.coyoteTime = 8;
    } else if (player.coyoteTime > 0) {
        player.coyoteTime--;
    }

    // Try to jump
    if (player.jumpBuffer > 0) {
        if (player.onWall && !player.onGround) {
            // Wall jump
            player.vx = -player.wallDir * 7;
            player.vy = player.jumpForce * 0.9;
            player.jumps = 1;
            player.jumpBuffer = 0;
            player.coyoteTime = 0;
            spawnParticles(player.x + (player.wallDir > 0 ? 0 : player.w), player.y + player.h / 2, '#00ffaa', 5, 3);
            audio.play('wallJump');
        } else if (player.coyoteTime > 0 || player.jumps < player.maxJumps + player.maxJumpsBonus) {
            // Ground jump (or coyote-time jump) — counts as first jump
            if (player.coyoteTime > 0 && player.jumps === 0) {
                player.vy = player.jumpForce;
                player.jumps = 1;
                audio.play('jump');
            } else if (player.jumps < player.maxJumps + player.maxJumpsBonus) {
                player.vy = player.jumpForce * (player.jumps === 0 ? 1 : 0.85);
                player.jumps++;
                audio.play(player.jumps === 1 ? 'jump' : 'doubleJump');
            }
            player.jumpBuffer = 0;
            player.coyoteTime = 0;
            spawnParticles(player.x + player.w / 2, player.y + player.h, '#00ffaa', 5, 2);
        }
    }

    // Variable jump height - if you release jump early, cut velocity for a shorter hop
    if (!jumpKey && player.vy < -4) {
        player.vy = -4;
    }

    // Dashing
    if ((keys['ShiftLeft'] || keys['ShiftRight']) && player.dashCooldown <= 0 && !player.dashing) {
        player.dashing = true;
        player.dashTimer = 8;
        player.dashCooldown = 40;
        let dx = moveX || player.facing;
        let dy = 0;
        if (keys['KeyS'] || keys['ArrowDown']) dy = 1;
        const len = Math.sqrt(dx * dx + dy * dy) || 1;
        player.dashDir = { x: dx / len, y: dy / len };
        player.vy = 0;
        spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#00ffaa', 8, 4);
        audio.play('dash');
        // Style Combat: track dash usage for bossAdapt (gated)
        if (typeof SC !== 'undefined' && SC.flags.bossAdapt) SC.bossAdapt.observe('dash');
    }

    if (player.dashing) {
        player.vx = player.dashDir.x * player.dashRange;
        player.vy = player.dashDir.y * player.dashRange;
        player.dashTimer--;
        // Dash trail
        dashTrails.push({ x: player.x, y: player.y, w: player.w, h: player.h, life: 1 });
        if (player.dashTimer <= 0) {
            player.dashing = false;
        }
    }

    if (player.dashCooldown > 0) player.dashCooldown--;

    // ===== DODGE ROLL (Ctrl) =====
    // Quick low-profile horizontal roll with i-frames. Faster cooldown than
    // dash but no slow-mo. Cancels gravity briefly.
    if (player.rollCooldown > 0) player.rollCooldown--;
    const rollKeyDown = (keys['ControlLeft'] || keys['ControlRight']);
    if (rollKeyDown && !player.rollKeyHeld && player.rollCooldown <= 0 &&
        !player.rolling && !player.dashing && !player.parrying && player.onGround) {
        player.rolling = true;
        player.rollTimer = 18;
        player.rollCooldown = 50;
        player.rollDir = (moveX !== 0) ? Math.sign(moveX) : player.facing;
        player.rollAnim = 0;
        player.invincible = Math.max(player.invincible, 18);
        player.h = 24;       // duck profile during roll
        spawnParticles(player.x + player.w / 2, player.y + player.h, '#88ddff', 10, 3);
        audio.play('roll');
    }
    player.rollKeyHeld = rollKeyDown;
    if (player.rolling) {
        player.vx = player.rollDir * 9;
        player.rollTimer--;
        player.rollAnim += 0.08;
        // Trail dust
        if (player.rollTimer % 3 === 0) {
            spawnParticles(player.x + player.w / 2, player.y + player.h - 4, '#aaccff', 3, 2);
        }
        if (player.rollTimer <= 0) {
            player.rolling = false;
            player.h = 40;
        }
    }

    // ===== PARRY (C) =====
    // 12-frame window. Reflects enemy bullets back as player bullets if hit.
    if (player.parryCooldown > 0) player.parryCooldown--;
    if (player.parryTimer > 0) player.parryTimer--;
    if (player.parrySuccess > 0) player.parrySuccess--;
    if (keys['KeyC'] && !player.parryKeyHeld && player.parryCooldown <= 0 &&
        !player.parrying && !player.rolling && !player.dashing) {
        player.parrying = true;
        player.parryTimer = 14;
        player.parryCooldown = 60;
        spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#ffffff', 10, 3);
        audio.play('ui');
    }
    player.parryKeyHeld = keys['KeyC'];
    if (player.parrying && player.parryTimer <= 0) {
        player.parrying = false;
    }

    // ===== GROUND POUND (S/↓ while in air) =====
    // Slams downward; on landing, creates a damaging shockwave.
    if (!player.pounding && !player.onGround && (keys['KeyS'] || keys['ArrowDown']) &&
        !player.poundKeyHeld && !player.dashing && !player.rolling) {
        player.pounding = true;
        player.vy = 0;
        player.vx = 0;
        spawnParticles(player.x + player.w / 2, player.y + player.h, '#ffaa44', 10, 3);
        audio.play('dash');
    }
    player.poundKeyHeld = (keys['KeyS'] || keys['ArrowDown']);
    if (player.pounding) {
        // Strong downward acceleration
        player.vy = Math.min(player.vy + 1.6, 22);
        player.vx = 0;
        player.poundTrail = (player.poundTrail || 0) + 1;
        // Trail particles
        if (player.poundTrail % 2 === 0) {
            spawnParticles(player.x + player.w / 2, player.y, '#ffaa44', 2, 2);
        }
        // Detect landing — checked in collision after movement; we set a flag
        // for the collision pass to trigger the explosion.
        player._wantPoundExplode = true;
    }

    // Gravity
    if (!player.dashing) {
        // Vehicle flight handling. Jet and starfighter FLY: gravity is
        // negated and vertical input (W/S/Up/Down) directly controls altitude.
        // Hover bike + hovertank have reduced gravity (floaty feel).
        // Tank/bike use normal gravity.
        const isFlyer = player.transformed && (player.vehicleType === 'jet' || player.vehicleType === 'starfighter');
        const isHover = player.transformed && player.vehicleType === 'hover';
        const isHoverTank = player.transformed && player.vehicleType === 'hovertank';

        if (isFlyer) {
            // Pure flight — gravity disabled, vertical input drives vy
            const upKey = keys['ArrowUp'] || keys['KeyW'] || keys['Space'];
            const downKey = keys['ArrowDown'] || keys['KeyS'];
            const flySpeed = player.vehicleType === 'starfighter' ? 6 : 5;
            let targetVy = 0;
            if (upKey) targetVy -= flySpeed;
            if (downKey) targetVy += flySpeed;
            // Smooth toward target so flight feels weighted, not snappy
            player.vy += (targetVy - player.vy) * 0.25;
            if (Math.abs(player.vy) > flySpeed) player.vy = Math.sign(player.vy) * flySpeed;
            // Disable jump-related state since flight overrides it
            player.jumps = 0;
            player.jumpBuffer = 0;
        } else if (isHover) {
            // Hover bike: half gravity for that floaty feel
            player.vy += player.gravity * 0.5;
            if (player.vy > 12) player.vy = 12;
        } else if (isHoverTank) {
            // CONVOY hover-tank: heavy hover. Quarter gravity, gentle bob,
            // moderate top fall speed. Feels like a Cybertron hovertank
            // skimming the ground.
            player.vy += player.gravity * 0.25;
            // Gentle hover bob (small sin-wave additive force)
            player.vy += Math.sin(performance.now() * 0.005) * 0.08;
            if (player.vy > 8) player.vy = 8;
        } else {
            // Robot mode (and tank/bike) — normal gravity
            player.vy += player.gravity;
            if (player.vy > 15) player.vy = 15;
        }

        // Wall slide
        if (player.onWall && !player.onGround && player.vy > 0) {
            player.vy = Math.min(player.vy, 2);
        }
    }

    // Apply velocity
    player.x += player.vx;
    player.y += player.vy;

    // Invincibility timer
    if (player.invincible > 0) player.invincible--;

    // === PRIME MODE TICK (Convoy Ion Blaster) ===
    // While in Prime mode, sustain a gold halo. When time runs out,
    // revert maxHp buff and start the cooldown that gates the next
    // transformation. Cooldown ticks down separately.
    if (player.primeMode && player.primeMode > 0) {
        player.primeMode--;
        // Halo / ember particles trail the player
        if (player.primeMode % 4 === 0) {
            spawnParticles(player.x + player.w / 2 + (Math.random() - 0.5) * player.w,
                player.y + Math.random() * player.h,
                Math.random() < 0.5 ? '#ffd744' : '#ffaa00', 1, 4);
        }
        if (player.primeMode <= 0) {
            // Revert max HP buff. Clamp current HP if it now exceeds max.
            if (player.primeMaxHpBuff && player.primeMaxHpBuff > 0) {
                player.maxHp = Math.max(1, player.maxHp - player.primeMaxHpBuff);
                if (player.hp > player.maxHp) player.hp = player.maxHp;
                player.primeMaxHpBuff = 0;
            }
            player.primeCooldown = 1800;     // 30s cooldown after expiration
            spawnShockwave(player.x + player.w / 2, player.y + player.h / 2, 200, '#ffaa00');
            spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#ffd744', 30, 8);
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: '⚙ PRIME RECHARGING — 30s', timer: 180, color: '#ff8844' };
            }
        }
    } else if (player.primeCooldown && player.primeCooldown > 0) {
        player.primeCooldown--;
        if (player.primeCooldown === 0 && typeof shopMessage !== 'undefined') {
            shopMessage = { text: '⚙ PRIME READY — F to transform', timer: 180, color: '#ffd744' };
        }
    }

    // Platform collision
    player.onGround = false;
    player.onWall = false;
    player.wallDir = 0;

    for (const plat of platforms) {
        if (plat.type === 'spike' || plat.type === 'laser' || plat.type === 'lava') continue;
        if (!rectCollide(player, plat)) continue;
        // Determine collision side
        const overlapX = Math.min(player.x + player.w - plat.x, plat.x + plat.w - player.x);
        const overlapY = Math.min(player.y + player.h - plat.y, plat.y + plat.h - player.y);

        if (overlapX < overlapY) {
            // Horizontal collision (wall)
            if (player.x + player.w / 2 < plat.x + plat.w / 2) {
                player.x = plat.x - player.w;
                player.wallDir = 1;
            } else {
                player.x = plat.x + plat.w;
                player.wallDir = -1;
            }
            player.vx = 0;
            player.onWall = true;
        } else {
            // Vertical collision
            if (player.y + player.h / 2 < plat.y + plat.h / 2) {
                player.y = plat.y - player.h;
                player.vy = 0;
                player.onGround = true;
                player.jumps = 0;
                // GROUND POUND impact — shockwave + AOE damage on landing
                if (player.pounding) {
                    player.pounding = false;
                    player.poundTrail = 0;
                    player._wantPoundExplode = false;
                    const cx = player.x + player.w / 2;
                    const cy = player.y + player.h;
                    spawnExplosion(cx, cy);
                    spawnShockwave(cx, cy, 180, '#ffaa44');
                    spawnShockwave(cx, cy, 140, '#ff8844');
                    spawnParticles(cx, cy, '#ffaa44', 30, 8);
                    spawnParticles(cx, cy, '#ffcc88', 18, 5);
                    screenShake = 18;
                    applyHitStop(4);
                    audio.play('pound');
                    // AOE damage to enemies in radius
                    const radius = 130;
                    const dmg = 60 + Math.round((player.dmgMul || 1) * 30);
                    for (let ei = enemies.length - 1; ei >= 0; ei--) {
                        const e = enemies[ei];
                        const ex = e.x + e.w / 2;
                        const ey = e.y + e.h / 2;
                        const dd = (ex - cx) ** 2 + (ey - cy) ** 2;
                        if (dd < radius * radius) {
                            e.hp -= dmg;
                            spawnDamageNumber(ex, e.y, dmg, 'aoe');
                            // Knockback up + outward
                            e.vy = -8;
                            if (e.x !== undefined) e.x += Math.sign(ex - cx) * 14;
                            if (e.hp <= 0) handleEnemyKilled(e, ei);
                        }
                    }
                    floatTexts.push({ text: 'SLAM!', x: cx, y: cy - 20, life: 50, color: '#ffaa44' });
                }
            } else {
                player.y = plat.y + plat.h;
                player.vy = 0;
            }
        }
    }

    // Minecraft blocks — solid, breakable platforms placed by MICAH MINECRAFTER.
    // Same physics as a normal platform; no spike/lava handling needed.
    for (const mb of minecraftBlocks) {
        if (!rectCollide(player, mb)) continue;
        const overlapX = Math.min(player.x + player.w - mb.x, mb.x + mb.w - player.x);
        const overlapY = Math.min(player.y + player.h - mb.y, mb.y + mb.h - player.y);
        if (overlapX < overlapY) {
            // Wall
            if (player.x + player.w / 2 < mb.x + mb.w / 2) {
                player.x = mb.x - player.w;
                player.wallDir = 1;
            } else {
                player.x = mb.x + mb.w;
                player.wallDir = -1;
            }
            player.vx = 0;
            player.onWall = true;
        } else {
            if (player.y + player.h / 2 < mb.y + mb.h / 2) {
                player.y = mb.y - player.h;
                player.vy = 0;
                player.onGround = true;
                player.jumps = 0;
            } else {
                player.y = mb.y + mb.h;
                player.vy = 0;
            }
        }
    }

    // Door collision (closed doors act as walls)
    for (const d of doors) {
        if (d.open) continue;
        if (rectCollide(player, d)) {
            const overlapX = Math.min(player.x + player.w - d.x, d.x + d.w - player.x);
            if (player.x + player.w / 2 < d.x + d.w / 2) {
                player.x = d.x - player.w;
            } else {
                player.x = d.x + d.w;
            }
            player.vx = 0;
        }
    }

    // Arena gate collision (boss arena lock-in)
    for (const ag of arenaGates) {
        if (ag.open) continue;
        if (rectCollide(player, ag)) {
            if (player.x + player.w / 2 < ag.x + ag.w / 2) {
                player.x = ag.x - player.w;
            } else {
                player.x = ag.x + ag.w;
            }
            player.vx = 0;
        }
    }

    // Track last safe position when grounded
    if (player.onGround && player.y < 600) {
        player.safeX = player.x;
        player.safeY = player.y - 10;
    }

    // Environmental hazard collisions (spike/laser/lava)
    if (player.invincible <= 0) {
        for (const plat of platforms) {
            if (plat.type === 'spike' || plat.type === 'laser' || plat.type === 'lava') {
                if (rectCollide(player, plat)) {
                    if (plat.type === 'laser') {
                        // "alwaysOn" lasers stay active permanently — must dodge around.
                        // Otherwise read the time-based on/off cycle (default 500ms).
                        if (!plat.alwaysOn) {
                            const cycle = plat.cycle || 500;
                            const phase = (Math.floor(performance.now() / cycle) + (plat.phase || 0)) % 2;
                            if (phase !== 0) continue;
                        }
                    }
                    const dmg = plat.type === 'lava' ? 12 : (plat.type === 'laser' ? 12 : 8);
                    player.hp -= dmg;
                    hitFlash = Math.min(1, hitFlash + 0.5);
                    player.invincible = 30;
                    screenShake = 6;
                    spawnParticles(player.x + player.w / 2, player.y + player.h / 2,
                        plat.type === 'lava' ? '#ff6600' : '#ff3300', 8, 4);
                    player.vy = -10;
                    player.vx = (player.x < plat.x + plat.w / 2 ? -6 : 6);
                    if (player.hp <= 0) {
                        gameState = 'dead';
                        spawnExplosion(player.x + player.w / 2, player.y + player.h / 2);
                    }
                    break;
                }
            }
        }
        // Mission-Impossible style laser GRIDS — continuous deadly walls until disabled.
        for (const lg of laserGrids) {
            if (lg.disabled) continue;
            if (rectCollide(player, lg)) {
                player.hp -= 14;
                hitFlash = Math.min(1, hitFlash + 0.6);
                applyHitStop(2);
                player.invincible = 35;
                screenShake = 9;
                spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#ff2244', 14, 6);
                // Knock the player out of the beam
                player.vy = -10;
                player.vx = (player.x < lg.x + lg.w / 2 ? -8 : 8);
                if (player.hp <= 0) {
                    gameState = 'dead';
                    spawnExplosion(player.x + player.w / 2, player.y + player.h / 2);
                }
                break;
            }
        }
    }

    // Pick up keys on touch
    for (let ki = keyPickups.length - 1; ki >= 0; ki--) {
        const k = keyPickups[ki];
        if (k.collected) { keyPickups.splice(ki, 1); continue; }
        if (rectCollide(player, k)) {
            k.collected = true;
            player.keysHeld.push(k.id);
            spawnParticles(k.x + k.w / 2, k.y + k.h / 2, '#ffdd44', 30, 6);
            spawnShockwave(k.x + k.w / 2, k.y + k.h / 2, 80, '#ffdd44');
            screenShake = 8;
            shopMessage = { text: `🔑 KEY ACQUIRED — find the cage`, timer: 220, color: '#ffdd44' };
            keyPickups.splice(ki, 1);
        }
    }

    // Fall off screen - respawn instead of dying (with HP penalty)
    if (player.y > 700) {
        player.x = player.safeX;
        player.y = player.safeY - 60;
        player.vx = 0;
        player.vy = 0;
        player.hp = Math.max(10, player.hp - 15);
        player.invincible = 60;
        spawnParticles(player.x + player.w / 2, player.y + player.h / 2, '#00ffaa', 12, 4);
        if (player.hp <= 0) {
            gameState = 'dead';
        }
    }

    // Activate ability with Q
    if ((keys['KeyQ']) && !player.abilityKeyHeld) {
        if (player.abilityTimer <= 0) {
            activateAbility();
        }
        player.abilityKeyHeld = true;
    }
    if (!keys['KeyQ']) player.abilityKeyHeld = false;

    // Evolution active ability with R
    if (evoAbilityCooldown > 0) evoAbilityCooldown--;
    const evo = EVOLUTIONS[player.evoLevel];
    if (evo && evo.ability && keys['KeyR'] && !player.evoAbilityHeld && evoAbilityCooldown <= 0) {
        triggerEvoAbility(evo.ability);
        evoAbilityCooldown = evo.ability === 'convoyMatrix' ? 900 :
                             evo.ability === 'primeBeam' ? 720 :
                             evo.ability === 'apexNova' ? 600 :
                             evo.ability === 'omegaBlast' ? 480 : 240;
        player.evoAbilityHeld = true;
    }
    if (!keys['KeyR']) player.evoAbilityHeld = false;

    // OMEGA passive aura - damages enemies near the player
    if (player.evoLevel >= 3) {
        player.auraTick = (player.auraTick || 0) + 1;
        if (player.auraTick % 30 === 0) {
            // APEX: bigger radius and double aura damage
            // PRIME: even bigger radius + more damage
            // CONVOY: massive radius + crushing damage
            const isConvoy = player.evoLevel >= 6;
            const isPrime = player.evoLevel >= 5;
            const isApex = player.evoLevel >= 4;
            const ar = isConvoy ? 200 : isPrime ? 160 : isApex ? 130 : 90;
            const dmg = isConvoy ? 16 : isPrime ? 12 : isApex ? 8 : 4;
            const auraColor = isConvoy ? '#ffd744' : isPrime ? '#ff3344' : isApex ? '#66ffff' : '#ffff44';
            for (let i = enemies.length - 1; i >= 0; i--) {
                const e = enemies[i];
                const ddx = (e.x + e.w/2) - (player.x + player.w/2);
                const ddy = (e.y + e.h/2) - (player.y + player.h/2);
                if (ddx * ddx + ddy * ddy < ar * ar) {
                    e.hp -= dmg;
                    if (Math.random() < 0.4) spawnParticles(e.x + e.w/2, e.y + e.h/2, auraColor, 1, 1);
                    if (e.hp <= 0) handleEnemyKilled(e, i);
                }
            }
        }
        // Visible aura ring
        if (player.auraTick % 6 === 0) {
            const auraColor = player.evoLevel >= 6 ? '#ffd744' :
                              player.evoLevel >= 5 ? '#ff3344' :
                              player.evoLevel >= 4 ? '#66ffff' : '#ffff44';
            spawnParticles(player.x + player.w/2 + (Math.random() - 0.5) * 90, player.y + player.h/2 + (Math.random() - 0.5) * 90, auraColor, 1, 0.5);
        }
    }

    // Tick ability timers
    if (player.abilityTimer > 0) player.abilityTimer--;

    // === VEHICLE TRANSFORMATION (X key) ===
    // Edge-trigger: pressing X toggles between robot and vehicle form. The
    // animation progresses each frame; once complete, transformed flips.
    // Each evolution tier gets a unique vehicle silhouette (see drawPlayer).
    if (player.transformCooldown > 0) player.transformCooldown--;
    const xPressed = !!keys['KeyX'];
    if (xPressed && !player.transformHeld && player.transformCooldown <= 0) {
        // Start a transform anim — direction depends on current state
        player.transformDir = player.transformed ? -1 : 1;
        player.transformAnim = player.transformed ? 1 : 0;
        player.transformCooldown = 18;
        // Pick the vehicle type based on current evolution tier.
        // BASE→bike, MK-II→hover, MK-III→tank, OMEGA→jet, APEX→starfighter,
        // PRIME→starfighter (kept), CONVOY→hovertank (Optimus-style hovering
        // tank, not the starfighter).
        const vTypes = ['bike', 'hover', 'tank', 'jet', 'starfighter', 'starfighter', 'hovertank'];
        player.vehicleType = vTypes[Math.min(player.evoLevel, vTypes.length - 1)];
        spawnShockwave(player.x + player.w/2, player.y + player.h/2, 60, player.charColor || '#00ddff');
        spawnParticles(player.x + player.w/2, player.y + player.h/2, player.charAccent || '#00ffaa', 18, 6);
        screenShake = 6;
        audio.play('transform');
    }
    player.transformHeld = xPressed;
    // Animate the transform progress
    if (player.transformDir !== 0) {
        const ANIM_RATE = 0.08;
        player.transformAnim += player.transformDir * ANIM_RATE;
        if (player.transformAnim >= 1) {
            player.transformAnim = 1;
            player.transformed = true;
            player.transformDir = 0;
        } else if (player.transformAnim <= 0) {
            player.transformAnim = 0;
            player.transformed = false;
            player.transformDir = 0;
        }
    }

    // === RAM DAMAGE: vehicle form damages enemies on contact ===
    // Tank/jet/starfighter ram for more; bike/hover for less. Damage scales
    // with player.dmgMul so it stays meaningful at every evolution tier.
    if (player.transformed && Math.abs(player.vx) > 1) {
        const ramTable = { bike: 14, hover: 18, tank: 28, jet: 24, starfighter: 36 };
        const ramBase = ramTable[player.vehicleType] || 14;
        const ram = Math.round(ramBase * (player.dmgMul || 1));
        for (let i = enemies.length - 1; i >= 0; i--) {
            const e = enemies[i];
            if (!rectCollide(player, e)) continue;
            // Tick a per-enemy ram cooldown so we hit ~5 times/sec, not 60
            e._ramCd = (e._ramCd || 0) - 1;
            if (e._ramCd > 0) continue;
            e._ramCd = 12;
            e.hp -= ram;
            spawnDamageNumber(e.x + e.w/2, e.y, ram, 'aoe');
            spawnParticles(e.x + e.w/2, e.y + e.h/2, player.charAccent || '#00ffaa', 8, 5);
            screenShake = Math.max(screenShake, 6);
            // Knock the enemy slightly
            if (e.x !== undefined) e.x += player.facing * 6;
            if (e.hp <= 0) handleEnemyKilled(e, i);
        }
    }

    if (player.abilityActiveTimer > 0) {
        player.abilityActiveTimer--;
        // Hover ability cancels gravity
        if (player.abilityType === 'hover' && player.abilityActiveTimer > 0) {
            if (player.vy > 0.5) player.vy = 0.5;
        }
        if (player.abilityActiveTimer <= 0) {
            player.abilityActive = false;
            timeSlowFactor = 1;
        }
    }

    // Perfect dodge timer
    if (player.perfectDodgeTimer > 0) {
        player.perfectDodgeTimer--;
        if (player.perfectDodgeTimer <= 0 && !player.abilityActive) {
            timeSlowFactor = 1;
        }
    }

    // Shooting - press F (or J) to shoot. Tap to fire single shots.
    if (player.shootCooldown > 0) player.shootCooldown--;
    const shootKey = keys['KeyF'] || keys['KeyJ'];
    const w = WEAPONS[player.weaponTier];
    // Vehicle form: bike/hover are pure rammers (no shooting). Tank, jet,
    // and starfighter can fire their own vehicle-mounted weapons. The mid-
    // transform fold-down still blocks shooting for both modes.
    const midTransform = player.transformAnim > 0.05 && player.transformAnim < 0.95;
    const canShootInVehicle = player.transformed && (
        player.vehicleType === 'tank' ||
        player.vehicleType === 'jet' ||
        player.vehicleType === 'starfighter' ||
        player.vehicleType === 'hovertank'
    );
    const blockedByVehicle = midTransform || (player.transformed && !canShootInVehicle);
    // Minigun is full-auto (just hold F); other weapons are tap-to-fire
    const canFire = w.cooldown <= 4 ? shootKey : (shootKey && !player.shootHeld);
    // Style Combat: also gate on heat — overheated weapons can't fire.
    const heatBlocked = (typeof SC !== 'undefined' && SC.flags.expandedArsenal &&
                        w && w.overheat && !SC.heat.canFire());
    if (canFire && player.shootCooldown <= 0 && !blockedByVehicle && !heatBlocked) {
        if (canShootInVehicle) {
            shootVehicleProjectile();
            // Vehicle weapons get heavier sound. Tank/hovertank = rocket, others = beam
            if (player.vehicleType === 'tank' || player.vehicleType === 'hovertank') {
                audio.play('rocket');
            } else {
                audio.play('shootBeam');
            }
        } else {
            shootBullet();
            // Pick SFX flavor by weapon tier — explosive weapons sound heavy
            if (w.explosive || w.bullets >= 5) {
                audio.play('shootHeavy');
            } else {
                audio.play('shoot');
            }
        }
        let cd = w.cooldown * player.fireRateMul;
        // Each weapon-upgrade level reduces this weapon's cooldown by 5%.
        // Capped at level 5 → 25% faster than base.
        const _wLvl = (player.weaponLevels && player.weaponLevels[player.weaponTier]) || 0;
        cd *= (1 - _wLvl * 0.05);
        // Bullet storm ability halves cooldown
        if (player.abilityActive && player.abilityType === 'bulletstorm') cd *= 0.4;
        // Vehicle-specific cooldown overrides — each vehicle has its own rhythm
        if (canShootInVehicle) {
            const vehicleCd = player.vehicleType === 'tank' ? 55 :   // slow heavy rocket
                              player.vehicleType === 'jet'  ? 28 :   // missile barrage
                              player.vehicleType === 'starfighter' ? 12 :  // rapid plasma
                              player.vehicleType === 'hovertank' ? 38 : cd; // Matrix ion blast
            cd = vehicleCd * player.fireRateMul;
        }
        // Style Combat: overheat replaces cooldown for weapons that have
        // an `overheat` flag. We still pay the normal cooldown but heat
        // builds per shot. When heat hits 100, the weapon locks for 90f
        // regardless of cooldown.
        if (typeof SC !== 'undefined' && SC.flags.expandedArsenal) {
            if (w && w.overheat) {
                SC.heat.addShot(w.overheat.perShot);
            }
        }
        // Style Combat: overclock halves the cooldown for ×2 fire rate.
        // Gated — no-op when step 12 is disabled.
        if (typeof SC !== 'undefined' && SC.flags.overclock) cd /= SC.overclock.fireRateMul();
        player.shootCooldown = Math.max(2, Math.round(cd));
        // Gun recoil for the animated arm/gun rig
        player.gunRecoil = Math.min(6, (player.gunRecoil || 0) + 4);
        // Style Combat: notify so transform-chain window can open if X
        // is pressed in the next 30f.
        if (typeof SC !== 'undefined') SC.onPlayerAttack('shoot');
    }
    player.shootHeld = shootKey;

    // Melee combat - G key for 3-hit combo
    if (player.meleeCooldown > 0) player.meleeCooldown--;
    if (player.meleeAnimTimer > 0) player.meleeAnimTimer--;
    if (player.meleeComboTimer > 0) {
        player.meleeComboTimer--;
        if (player.meleeComboTimer <= 0) player.meleeCombo = 0;
    }
    if (keys['KeyG'] && !player.meleeKeyHeld && player.meleeCooldown <= 0) {
        executeMelee();
        player.meleeKeyHeld = true;
    }
    if (!keys['KeyG']) player.meleeKeyHeld = false;

    // BAND BLASTER — press B to cycle instrument (DRUM/SAX/CLARINET/FLUTE).
    // Edge-triggered so a held key only switches once. Skip while the
    // shop is open since B is also a shop hotkey there (Soul Cannon).
    {
        const wEquipped = WEAPONS[player.weaponTier];
        if (!shopOpen && wEquipped && wEquipped.bandWeapon) {
            if (keys['KeyB'] && !player.bandSwitchHeld) {
                cycleBandInstrument();
                player.bandSwitchHeld = true;
            }
            if (!keys['KeyB']) player.bandSwitchHeld = false;
            // V — fire SPECIAL MOVE for the active instrument. Uses its
            // own cooldown (3 sec) so it's not gated by the regular shoot
            // cooldown. Edge-triggered.
            if (keys['KeyV'] && !player.bandSpecialHeld && player.bandSpecialCooldown <= 0) {
                executeBandSpecial();
                player.bandSpecialHeld = true;
            }
            if (!keys['KeyV']) player.bandSpecialHeld = false;
        }
        // Always tick the FX even if weapon was swapped mid-special so it
        // cleanly finishes (or we'd leak the maxHp buff etc.)
        if (typeof updateBandSpecialFx === 'function') updateBandSpecialFx();
    }

    // CONVOY ION BLASTER ultimate — V key triggers the full Prime mode
    // (transform PLAYER) + summons the PRIMUS TITAN ally at the same
    // time. Both effects share a 60-sec timing window: 30s active, 30s
    // cooldown before another V press is allowed. Edge-triggered.
    {
        const wEq = WEAPONS[player.weaponTier];
        if (!shopOpen && wEq && wEq.primusSummon) {
            if (keys['KeyV'] && !player.primeSwitchHeld) {
                executePrimusUltimate();
                player.primeSwitchHeld = true;
            }
            if (!keys['KeyV']) player.primeSwitchHeld = false;
        }
    }
}

// Shooting - fires in the direction you're facing, using current weapon
function shootBullet() {
    const cx = player.x + player.w / 2;
    const cy = player.y + player.h / 2;
    const w = WEAPONS[player.weaponTier];
    // Direction: forward by default; aim up if pressing up, down if pressing down
    let baseDx = player.facing;
    let baseDy = 0;
    if (keys['ArrowUp'] || keys['KeyW']) { baseDy = -0.6; }
    if (keys['ArrowDown'] || keys['KeyS']) { baseDy = 0.6; }
    const baseLen = Math.sqrt(baseDx * baseDx + baseDy * baseDy);
    baseDx /= baseLen; baseDy /= baseLen;
    const baseAngle = Math.atan2(baseDy, baseDx);

    // BAND BLASTER — divert to the instrument-specific shoot helper.
    // It handles its own bullet count, color, and per-instrument special FX.
    if (w.bandWeapon) {
        shootBandWeapon(cx, cy, baseDx, baseDy, baseAngle);
        spawnParticles(cx + baseDx * 22, cy + baseDy * 22, w.glow, 5, 3);
        screenShake = 4;
        return;
    }
    // DRAGON DANCER — F summons a Chinese New Year dragon that flows
    // through enemies and bursts into fireworks. No bullet is fired.
    if (w.dragonDanceWeapon) {
        if (typeof spawnDancingDragon === 'function') {
            // Spawn just in front of the player so the dragon emerges from
            // the gun. Direction follows the aim, biased forward.
            spawnDancingDragon(cx + baseDx * 28, cy + baseDy * 28, player.facing || 1);
        }
        return;
    }
    // PRIMUS SUMMONER / CONVOY ION BLASTER — F always fires the convoy
    // ion-blaster volley (triple piercing explosive shots from the
    // weapon definition). The TRANSFORMATION + PRIMUS SUMMON happens on
    // a separate V key press inside updatePlayer (executePrimusUltimate).
    // Falls through to the regular bullet-fire loop below.
    if (w.primusSummon) {
        // intentional fall-through — F just shoots, V triggers ultimate
    }

    // ===== WEAPON UPGRADE LEVELS =====
    // Each level (1..5) adds +25% damage to the active weapon. Stored on
    // player.weaponLevels[tier] so each gun upgrades independently.
    const wpnLvl = (player.weaponLevels && player.weaponLevels[player.weaponTier]) || 0;
    const lvlDmgMul = 1 + wpnLvl * 0.25;

    // Fire one or more bullets
    for (let i = 0; i < w.bullets; i++) {
        let angle = baseAngle;
        if (w.bullets > 1) {
            // Spread shotgun-style
            const t = w.bullets === 1 ? 0 : (i / (w.bullets - 1) - 0.5) * 2;
            angle += t * w.spread;
        } else if (w.spread > 0) {
            // Random spread (minigun)
            angle += (Math.random() - 0.5) * 2 * w.spread;
        }
        const dx = Math.cos(angle), dy = Math.sin(angle);
        bullets.push({
            x: cx + dx * 18, y: cy + dy * 18,
            vx: dx * w.speed,
            vy: dy * w.speed,
            life: w.life,
            damage: Math.round((w.damage + player.bulletDamage) * (player.dmgMul || 1) * lvlDmgMul),
            color: w.color, glow: w.glow, size: w.size,
            pierce: !!w.pierce, hitEnemies: new Set(),
            explosive: !!w.explosive,
            aoeRadius: w.aoeRadius || 100,
            burn: !!w.burn, burnDmg: w.burnDmg, burnDur: w.burnDur,
            slow: !!w.slow, slowDur: w.slowDur, slowFactor: w.slowFactor,
            flame: !!w.flame,
            ice: !!w.ice,
            beam: !!w.beam,
            acid: !!w.acid,
            water: !!w.water,
            lightning: !!w.lightning,
            chainDmg: w.chainDmg, chainRadius: w.chainRadius, chainCount: w.chainCount,
            lightningStrike: !!w.lightningStrike,
            strikeDmg: w.strikeDmg, strikeRadius: w.strikeRadius,
            soccerBall: !!w.soccerBall,
            minecraftBlock: !!w.minecraftBlock,
            // JAX BLASTER extras
            bounce: w.bounce || 0,
            bouncesLeft: w.bounce || 0,
            homing: !!w.homing,
            spawnGoalSpark: !!w.spawnGoalSpark,
            // MICAH MINECRAFTER extras
            leavesLava: !!w.leavesLava,
            craftBonus: !!w.craftBonus
        });
    }
    // Muzzle flash
    spawnParticles(cx + baseDx * 22, cy + baseDy * 22, w.glow, 5, 3);
    screenShake = w.bullets > 1 ? 5 : 3;

    // ===== MICAH MINECRAFTER side-effect: spawn a friendly mob OR a block =====
    // The bullet itself (creeper-TNT block) does damage on impact; this
    // additional spawn makes the gun a "summon weapon" — every shot also
    // drops one minion or buildable platform into the world.
    if (w.minecraftBlock) {
        spawnMinecraftSummon(cx, cy, baseDx, baseDy);
    }

    // Evolution side-arm bonus shots — Transformer-style: spawn from the
    // visible shoulder mounts on the player so it reads as the actual weapon
    // firing, with a muzzle flash + screen shake scaled to weapon size.
    //
    // Balance note: PRIME/CONVOY used to fire 6/8 piercing bullets PER weapon
    // shot, on top of the base weapon. That overwhelmed boss fights to the
    // point of trivializing them. Now we fire fewer bullets per volley AND
    // only fire the volley every Nth weapon shot (player.sideArmShotCounter).
    // The result is a "powerful precise" feel instead of a wall-of-bullets.
    const evo = EVOLUTIONS[player.evoLevel];
    if (evo && evo.sideArm) {
        // Both shoulder mount positions (mirror of drawPlayer side-arm code).
        const shoulderL = { x: cx - player.facing * 10, y: cy - 12 };
        const shoulderR = { x: cx + player.facing * (player.w / 2 - 4), y: cy - 12 };
        // Tier-specific gate: PRIME fires every 2nd shot, CONVOY every 3rd.
        // Other tiers fire every shot — UNLESS the equipped weapon is FLAME-
        // type. Flame weapons fire 30 shots/sec; if the side-arm rode along
        // with each flame, OMEGA missile array would do ~150 DPS just from
        // the side-arm alone (broken, unfair). Flame weapons completely
        // disable the side-arm — flame is a "screen filler", not a launcher.
        const isFlameWeapon = !!w.flame;
        if (isFlameWeapon) {
            // Flame weapons never trigger the side-arm. Skip entirely.
            return;
        }
        player.sideArmShotCounter = (player.sideArmShotCounter || 0) + 1;
        const gate = (evo.sideArm === 'prime') ? 2
                   : (evo.sideArm === 'convoy') ? 3
                   : 1;
        const sideArmFires = (player.sideArmShotCounter % gate) === 0;
        if (!sideArmFires && (gate > 1)) {
            // Skip side-arm this shot — base weapon still fires from the loop above.
            return;
        }
        if (evo.sideArm === 'pulse') {
            // Single pulse shot from RIGHT shoulder pulse cannon
            bullets.push({
                x: shoulderR.x, y: shoulderR.y,
                vx: baseDx * 13, vy: baseDy * 13,
                life: 60, damage: Math.round(20 * player.dmgMul),
                color: '#ff88ff', glow: '#ff44ff', size: 6,
                pierce: false, hitEnemies: new Set(), explosive: false
            });
            spawnParticles(shoulderR.x, shoulderR.y, '#ff44ff', 6, 4);
            spawnShockwave(shoulderR.x, shoulderR.y, 30, '#ff44ff');
        } else if (evo.sideArm === 'rocket') {
            // TWO rockets — one from each shoulder rocket pod
            for (const sh of [shoulderL, shoulderR]) {
                bullets.push({
                    x: sh.x, y: sh.y,
                    vx: baseDx * 8 + (Math.random() - 0.5) * 0.5,
                    vy: -2 - Math.random() * 0.5,
                    life: 90, damage: Math.round(60 * player.dmgMul),
                    color: '#ff4400', glow: '#ff0000', size: 9,
                    pierce: false, hitEnemies: new Set(),
                    explosive: true, aoeRadius: 90,
                    rocket: true
                });
                spawnParticles(sh.x, sh.y, '#ffaa00', 8, 5);
                spawnShockwave(sh.x, sh.y, 40, '#ff8800');
            }
            screenShake = Math.max(screenShake, 7);
        } else if (evo.sideArm === 'omega') {
            // OMEGA: 2 missiles, alternating shoulders, fan pattern (further
            // nerfed — was bursting bosses too fast even after first nerf)
            for (let r = 0; r < 2; r++) {
                const sh = (r % 2 === 0) ? shoulderL : shoulderR;
                bullets.push({
                    x: sh.x, y: sh.y - r * 2,
                    vx: baseDx * 9,
                    vy: -3 + r * 1.5,
                    life: 100, damage: Math.round(30 * player.dmgMul),
                    color: '#ffff00', glow: '#ffaa00', size: 10,
                    pierce: false, hitEnemies: new Set(),
                    explosive: true, aoeRadius: 50,
                    rocket: true
                });
                spawnParticles(sh.x, sh.y, '#ffff00', 4, 4);
            }
            spawnShockwave(shoulderL.x, shoulderL.y, 60, '#ffff00');
            spawnShockwave(shoulderR.x, shoulderR.y, 60, '#ffff00');
            screenShake = Math.max(screenShake, 12);
        } else if (evo.sideArm === 'apex') {
            // APEX: 4 plasma cannons fire concurrently in a tight fan,
            // one from each shoulder pulse-cannon and one from each chest port.
            const ports = [
                shoulderL,
                shoulderR,
                { x: cx - player.facing * 4, y: cy + 2 },
                { x: cx + player.facing * 6, y: cy + 2 }
            ];
            for (let r = 0; r < ports.length; r++) {
                const sh = ports[r];
                bullets.push({
                    x: sh.x, y: sh.y,
                    vx: baseDx * 14 + (Math.random() - 0.5) * 0.6,
                    vy: -1 + (r - 1.5) * 0.7,
                    life: 100, damage: Math.round(22 * player.dmgMul),
                    color: '#66ffff', glow: '#00ffff', size: 8,
                    pierce: true, hitEnemies: new Set(),
                    explosive: false
                });
                spawnParticles(sh.x, sh.y, '#66ffff', 4, 4);
            }
            spawnShockwave(shoulderL.x, shoulderL.y, 70, '#00ffff');
            spawnShockwave(shoulderR.x, shoulderR.y, 70, '#00ffff');
            screenShake = Math.max(screenShake, 14);
        } else if (evo.sideArm === 'prime') {
            // PRIME: 3 cannons fire in a focused fan from shoulders + chest.
            // Crimson plasma streams. (Was 6 — toned down for boss balance.)
            const ports = [
                shoulderL,
                shoulderR,
                { x: cx + player.facing * 4, y: cy + 8 }   // chest reactor port
            ];
            for (let r = 0; r < ports.length; r++) {
                const sh = ports[r];
                bullets.push({
                    x: sh.x, y: sh.y,
                    vx: baseDx * 16 + (Math.random() - 0.5) * 0.4,
                    vy: -1 + (r - 1) * 0.6,
                    life: 110, damage: Math.round(80 * player.dmgMul),
                    color: '#ff6644', glow: '#ff3322', size: 9,
                    pierce: true, hitEnemies: new Set()
                });
                spawnParticles(sh.x, sh.y, '#ff6644', 4, 4);
            }
            spawnShockwave(shoulderL.x, shoulderL.y, 80, '#ff3344');
            spawnShockwave(shoulderR.x, shoulderR.y, 80, '#ff3344');
            screenShake = Math.max(screenShake, 14);
        } else if (evo.sideArm === 'convoy') {
            // CONVOY: 4 cannon volley — both shoulders + twin chest ports.
            // Each shot is a ravaging golden plasma orb. (Was 8 — toned down
            // for boss balance; per-shot damage bumped so feel stays "final tier"
            // but bosses aren't melted instantly.)
            const ports = [
                shoulderL,
                shoulderR,
                { x: cx - player.facing * 2, y: cy + 4 },
                { x: cx + player.facing * 6, y: cy + 4 }
            ];
            for (let r = 0; r < ports.length; r++) {
                const sh = ports[r];
                bullets.push({
                    x: sh.x, y: sh.y,
                    vx: baseDx * 18 + (Math.random() - 0.5) * 0.3,
                    vy: -1 + (r - 1.5) * 0.4,
                    life: 120, damage: Math.round(110 * player.dmgMul),
                    color: '#ffcc44', glow: '#ff6600', size: 10,
                    pierce: true, hitEnemies: new Set(),
                    explosive: true, aoeRadius: 60
                });
                spawnParticles(sh.x, sh.y, '#ffcc44', 5, 5);
            }
            spawnShockwave(shoulderL.x, shoulderL.y, 100, '#ffcc44');
            spawnShockwave(shoulderR.x, shoulderR.y, 100, '#ffcc44');
            screenShake = Math.max(screenShake, 18);
        }
    }
}

function updateBullets() {
    for (let i = bullets.length - 1; i >= 0; i--) {
        const b = bullets[i];
        // Rockets get slight gravity for arc
        if (b.rocket) {
            b.vy += 0.15;
        }
        // Homing — gently steer toward the nearest enemy. Used by missiles
        // (jet) and plasma torpedoes (starfighter). Strength is small so the
        // projectile still feels physical.
        if (b.homing) {
            let nearest = null;
            let nd = Infinity;
            for (const e of enemies) {
                const dx = (e.x + e.w / 2) - b.x;
                const dy = (e.y + e.h / 2) - b.y;
                const d = dx * dx + dy * dy;
                if (d < nd && d < 700 * 700) { nd = d; nearest = e; }
            }
            if (nearest) {
                const dx = (nearest.x + nearest.w / 2) - b.x;
                const dy = (nearest.y + nearest.h / 2) - b.y;
                const dist = Math.sqrt(dx * dx + dy * dy) || 1;
                const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy) || 1;
                // Blend current velocity with target direction
                const turnRate = 0.08;
                b.vx += ((dx / dist) * speed - b.vx) * turnRate;
                b.vy += ((dy / dist) * speed - b.vy) * turnRate;
                // Re-normalize so homing doesn't accelerate the bullet
                const newSpeed = Math.sqrt(b.vx * b.vx + b.vy * b.vy) || 1;
                b.vx = (b.vx / newSpeed) * speed;
                b.vy = (b.vy / newSpeed) * speed;
            }
        }
        b.x += b.vx;
        b.y += b.vy;
        b.life--;

        // Despawn if too far from camera (perf)
        if (Math.abs(b.x - camera.x) > 1500 || Math.abs(b.y - camera.y) > 900) {
            bullets.splice(i, 1);
            continue;
        }

        // Bullets blocked by solid platforms (walls/ground/normal platforms)
        let hitWall = false;
        for (let pi = 0; pi < platforms.length; pi++) {
            const plat = platforms[pi];
            if (plat.type === 'recovery' || plat.type === 'spike' || plat.type === 'laser' || plat.type === 'lava') continue;
            if (b.x >= plat.x && b.x <= plat.x + plat.w && b.y >= plat.y && b.y <= plat.y + plat.h) {
                // BOUNCING bullets (JAX BLASTER soccer balls) ricochet off
                // surfaces instead of being blocked. Decide which axis the
                // bullet hit by which side it overlaps the most, then flip
                // that velocity component. Decrement bouncesLeft so we
                // eventually still terminate.
                if (b.bouncesLeft && b.bouncesLeft > 0) {
                    // Pick axis to flip — whichever overlap is shallower
                    const overL = Math.abs(b.x - plat.x);
                    const overR = Math.abs((plat.x + plat.w) - b.x);
                    const overT = Math.abs(b.y - plat.y);
                    const overB = Math.abs((plat.y + plat.h) - b.y);
                    const minH = Math.min(overL, overR);
                    const minV = Math.min(overT, overB);
                    if (minH < minV) {
                        // Side hit — flip horizontal
                        b.vx = -b.vx * 0.85;
                        b.x += b.vx;        // nudge out of the platform
                    } else {
                        // Floor / ceiling — flip vertical (preserve some bounce energy)
                        b.vy = -b.vy * 0.85;
                        b.y += b.vy;
                    }
                    b.bouncesLeft--;
                    spawnParticles(b.x, b.y, '#ffffff', 6, 4);
                    if (typeof audio !== 'undefined' && audio.play) {
                        audio.play('hit', { throttle: 60 });
                    }
                    continue;     // don't apply normal hitWall path
                }
                spawnParticles(b.x, b.y, '#888', 4, 2);
                // Damage breakable cover
                if (plat.type === 'breakable') {
                    plat.hp = (plat.hp ?? 60) - b.damage;
                    spawnParticles(b.x, b.y, '#aa6622', 6, 4);
                    if (plat.hp <= 0) {
                        spawnParticles(plat.x + plat.w / 2, plat.y + plat.h / 2, '#aa6622', 25, 5);
                        screenShake = 6;
                        // SCRAP DROP — every breakable yields some scrap.
                        // Size scales with crate HP and stage. Cache crates
                        // give a chunkier bonus pile.
                        {
                            const cx2 = plat.x + plat.w / 2;
                            const cy2 = plat.y + plat.h / 2;
                            const baseScrap = Math.max(1, Math.round((plat.hp_max || plat.hp || 60) / 30));
                            const bonus = plat.cache ? 6 + currentStage * 2 : 0;
                            const total = baseScrap + bonus + Math.floor(Math.random() * 2);
                            for (let cc = 0; cc < total; cc++) {
                                const ang = Math.random() * Math.PI * 2;
                                const spd = 1.5 + Math.random() * 3.5;
                                coinPickups.push({
                                    x: cx2, y: cy2,
                                    vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd - 2.5,
                                    value: 1, life: 700,
                                    scrap: true
                                });
                            }
                        }
                        // Drop hidden cache
                        if (plat.cache) {
                            const cx2 = plat.x + plat.w / 2;
                            const cy2 = plat.y + plat.h / 2;
                            for (let cc = 0; cc < (plat.cacheCoins || 30); cc++) {
                                const ang = Math.random() * Math.PI * 2;
                                const spd = 2 + Math.random() * 4;
                                coinPickups.push({
                                    x: cx2, y: cy2,
                                    vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd - 3,
                                    value: 2, life: 600
                                });
                            }
                            healthDrops.push({
                                x: cx2, y: cy2, vx: 0, vy: -3,
                                heal: 50, life: 700
                            });
                            shopMessage = { text: 'HIDDEN CACHE!', timer: 80, color: '#ffdd44' };
                        }
                        platforms.splice(pi, 1);
                    }
                }
                hitWall = true;
                break;
            }
        }
        if (hitWall) { bullets.splice(i, 1); continue; }

        // Hit cages (free the ally) — but only if the player is holding the cage's key
        let hitCage = false;
        for (const cage of cages) {
            if (cage.rescued) continue;
            if (b.x >= cage.x && b.x <= cage.x + cage.w && b.y >= cage.y && b.y <= cage.y + cage.h) {
                // If the cage requires a key, refuse damage until the player has it.
                if (cage.requiresKey && !(player.keysHeld || []).includes(cage.requiresKey)) {
                    spawnParticles(b.x, b.y, '#ff4444', 6, 3);
                    if (!cage._lockedFlashed || (performance.now() - cage._lockedFlashed) > 600) {
                        shopMessage = { text: '🔒 CAGE LOCKED — find the KEY first!', timer: 120, color: '#ff6644' };
                        cage._lockedFlashed = performance.now();
                    }
                    hitCage = true;
                    break;
                }
                cage.hp -= b.damage;
                spawnParticles(b.x, b.y, '#ffdd44', 8, 4);
                if (cage.hp <= 0) {
                    cage.rescued = true;
                    // Squad cap: keep only 2 active allies. Boot the oldest.
                    const ALLY_LIMIT = 2;
                    while (allies.length >= ALLY_LIMIT) {
                        const departing = allies.shift();
                        if (departing) {
                            spawnParticles(
                                departing.x + departing.w / 2,
                                departing.y + departing.h / 2,
                                departing.def.color, 18, 5
                            );
                            shopMessage = {
                                text: `${departing.def.name} departs — squad limit (${ALLY_LIMIT}).`,
                                timer: 180, color: '#ffaa66'
                            };
                        }
                    }
                    // Spawn ally
                    spawnAlly(cage.allyDef, cage.x + cage.w / 2, cage.y + cage.h / 2);
                    spawnParticles(cage.x + cage.w / 2, cage.y + cage.h / 2, cage.allyDef.color, 30, 7);
                    screenShake = 14;
                    shopMessage = { text: `${cage.allyDef.name} JOINED YOU! Walk to the EXIT PORTAL.`, timer: 240, color: cage.allyDef.color };
                    // Spawn exit portal nearby
                    if (currentStage < STAGES.length - 1) {
                        exitPortals.push({
                            x: cage.x + cage.w + 100,
                            y: 470,
                            w: 80, h: 100
                        });
                    } else {
                        // Final stage - go straight into the BOSS RUSH
                        // after a brief beat (90 frames ~= 1.5s). The boss
                        // rush chains 8 prior bosses + MECH KING in
                        // regular-stage style (normal scale, normal controls).
                        deferFrames(90, () => { startBossRush(); });
                    }
                }
                hitCage = true;
                break;
            }
        }
        if (hitCage) { bullets.splice(i, 1); continue; }

        // Hit terminals — bullets just SPARK off the terminal panel; they
        // do NOT cut wires. To cut a wire, walk up and press E. (Old behavior
        // was bullets-cut-wires, but that felt like accidental shooting; the
        // explicit press-E reads as "I'm interacting with the panel.")
        let hitTerminal = false;
        for (const term of terminals) {
            if (term.disabled) continue;
            if (b.x >= term.x && b.x <= term.x + term.w && b.y >= term.y && b.y <= term.y + term.h) {
                spawnParticles(b.x, b.y, '#88ddff', 6, 3);
                // Tiny shake to give feedback that the terminal is here
                screenShake = Math.max(screenShake, 2);
                // Floating prompt nudging the player to actually use the panel
                if (!term.bulletPromptCooldown || term.bulletPromptCooldown <= 0) {
                    floatTexts.push({
                        text: 'PRESS E TO CUT WIRE',
                        x: term.x + term.w / 2,
                        y: term.y - 8,
                        life: 50, color: '#ffdd44'
                    });
                    term.bulletPromptCooldown = 60;
                }
                hitTerminal = true;
                break;
            }
        }
        if (hitTerminal) { bullets.splice(i, 1); continue; }

        // Bullets are blocked by active laser grids (you can't shoot through them)
        let hitLaserGrid = false;
        for (const lg of laserGrids) {
            if (lg.disabled) continue;
            if (b.x >= lg.x && b.x <= lg.x + lg.w && b.y >= lg.y && b.y <= lg.y + lg.h) {
                spawnParticles(b.x, b.y, '#ff2244', 6, 3);
                hitLaserGrid = true;
                break;
            }
        }
        if (hitLaserGrid) { bullets.splice(i, 1); continue; }

        // Hit switches
        let hitSwitch = false;
        for (const sw of switches) {
            if (sw.activated) continue;
            if (b.x >= sw.x && b.x <= sw.x + sw.w && b.y >= sw.y && b.y <= sw.y + sw.h) {
                sw.activated = true;
                spawnParticles(sw.x + sw.w / 2, sw.y + sw.h / 2, '#00ffff', 12, 4);
                screenShake = 5;
                // Check if all switches in this group are activated -> open the door
                const grp = sw.group;
                const all = switches.filter(s => s.group === grp).every(s => s.activated);
                if (all) {
                    for (const d of doors) {
                        if (d.group === grp) {
                            d.open = true;
                            spawnParticles(d.x + d.w / 2, d.y + d.h / 2, '#00ff00', 30, 6);
                            screenShake = 12;
                            shopMessage = { text: 'PATH UNLOCKED', timer: 90, color: '#00ffaa' };
                        }
                    }
                }
                hitSwitch = true;
                break;
            }
        }
        if (hitSwitch) { bullets.splice(i, 1); continue; }

        // Bullets are blocked by closed doors
        let hitDoor = false;
        for (const d of doors) {
            if (d.open) continue;
            if (b.x >= d.x && b.x <= d.x + d.w && b.y >= d.y && b.y <= d.y + d.h) {
                spawnParticles(b.x, b.y, '#ff0000', 4, 2);
                hitDoor = true;
                break;
            }
        }
        if (hitDoor) { bullets.splice(i, 1); continue; }

        // Bullets blocked by closed arena gates
        let hitGate = false;
        for (const ag of arenaGates) {
            if (ag.open) continue;
            if (b.x >= ag.x && b.x <= ag.x + ag.w && b.y >= ag.y && b.y <= ag.y + ag.h) {
                spawnParticles(b.x, b.y, '#ffaa00', 5, 3);
                hitGate = true;
                break;
            }
        }
        if (hitGate) { bullets.splice(i, 1); continue; }

        // Bullets blocked by closed boss gates
        let hitBossGate = false;
        for (const bg of bossGates) {
            if (bg.open) continue;
            if (b.x >= bg.x && b.x <= bg.x + bg.w && b.y >= bg.y && b.y <= bg.y + bg.h) {
                spawnParticles(b.x, b.y, bg.color, 5, 3);
                hitBossGate = true;
                break;
            }
        }
        if (hitBossGate) { bullets.splice(i, 1); continue; }

        // Hit enemies
        let hit = false;
        for (let j = enemies.length - 1; j >= 0; j--) {
            const e = enemies[j];
            // Skip enemies this piercing bullet has already hit
            if (b.pierce && b.hitEnemies && b.hitEnemies.has(e)) continue;
            if (b.x >= e.x && b.x <= e.x + e.w && b.y >= e.y && b.y <= e.y + e.h) {
                // SHIELDER damage reduction from frontal hits
                let dmg = b.damage;
                if (e.type === 'shielder') {
                    const fromFront = (e.dir > 0 && b.x > e.x + e.w / 2) || (e.dir < 0 && b.x < e.x + e.w / 2);
                    if (fromFront) {
                        dmg = Math.round(dmg * 0.2);
                        spawnParticles(b.x, b.y, e.shieldColor || '#44ddff', 5, 3);
                    }
                }
                // FROZEN enemy variant — weak to fire, resistant to ice.
                // Lets the player counter-pick: bring FLAME THROWER to
                // arctic stage for ×1.5 damage, or get punished for using
                // ice on ice-armored enemies (×0.5).
                if (e.frozenEnemy) {
                    if (b.burn || b.flame) {
                        dmg = Math.round(dmg * 1.5);
                        spawnParticles(b.x, b.y, '#ff8844', 4, 3);
                    } else if (b.ice || b.slow) {
                        dmg = Math.round(dmg * 0.5);
                        spawnParticles(b.x, b.y, '#88ccff', 3, 2);
                    }
                }
                // BOSS weak point - hits to top 25% (head) deal 2x damage with crit visual
                if (e.type === 'boss' || e.type === 'miniboss') {
                    const isHeadshot = b.y < e.y + e.h * 0.25;
                    if (isHeadshot) {
                        dmg = Math.round(dmg * 2);
                        spawnParticles(b.x, b.y, '#ffff00', 12, 5);
                        screenShake = 8;
                        critFlash = Math.min(1, critFlash + 0.55);
                        applyHitStop(3);
                        spawnShockwave(b.x, b.y, 90, '#ffdd44');
                        // Float "CRIT" text via particle
                        floatTexts.push({ text: 'CRIT!', x: b.x, y: b.y, life: 40, color: '#ffff00' });
                        spawnDamageNumber(b.x, b.y, dmg, 'crit');
                    } else {
                        spawnDamageNumber(b.x, b.y, dmg, 'normal');
                    }
                } else {
                    spawnDamageNumber(b.x, b.y, dmg, 'normal');
                }
                // Style Combat: apply outgoing-damage multiplier (momentum,
                // transform-chain, overclock, corrupted) THEN armor break
                // reduction. Order matters — armor scales the modified
                // damage, not the raw, so a +60% chained shot still hits
                // armor for 50% absorbed = ~80% effective. Armor reduction
                // is gated on SC.flags.armor — when off, behaves as if
                // every enemy has no armor field at all. Bullets flagged
                // armorPierce skip the armor reduction entirely.
                if (typeof SC !== 'undefined') {
                    const mul = SC.outgoingDmgMul();
                    if (mul !== 1) dmg = Math.round(dmg * mul);
                    if (SC.flags.armor) {
                        if (b && b.armorPierce) {
                            // skip armor entirely — damage passes through
                        } else {
                            dmg = SC.armor.applyDamage(e, dmg);
                        }
                    }
                    SC.consumeTransformChain();
                    // Expanded arsenal: gravity-pull spawn, whip chain,
                    // corruption damage scale all live in onBulletHit.
                    if (SC.flags.expandedArsenal && SC.weaponEffects) {
                        dmg = SC.weaponEffects.onBulletHit(b, e, dmg);
                    }
                }
                // === BOSS RUSH WEAKNESS — 2x damage if bullet element matches boss weakness ===
                let weakBonus = 1;
                if (e.bossRush) {
                    weakBonus = applyBossRushWeaknessMul(b, e);
                    if (weakBonus > 1) {
                        dmg = Math.round(dmg * weakBonus);
                        // Visual flair — gold burst at hit point
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(b.x, b.y, '#ffd744', 8, 5);
                            spawnParticles(b.x, b.y, '#ffffff', 4, 4);
                        }
                        if (typeof spawnDamageNumber === 'function') {
                            spawnDamageNumber(e.x + e.w/2, e.y, dmg, 'crit');
                        }
                    }
                }
                e.hp -= dmg;
                // Apply weapon special effects
                if (b.burn) {
                    e.burnTimer = b.burnDur || 90;
                    e.burnDamage = b.burnDmg || 8;
                }
                if (b.slow) {
                    e.slowTimer = b.slowDur || 90;
                    e.slowFactor = b.slowFactor || 0.4;
                }
                // ICE weapons freeze enemies — short hard-stop (e.frozen) plus
                // a longer slow when they unfreeze. Visible ice overlay during
                // frozen state. Note: bosses/minibosses get a much shorter
                // freeze so they're not trivialized.
                if (b.ice) {
                    const isBoss = e.type === 'boss' || e.type === 'miniboss';
                    e.frozen = Math.max(e.frozen || 0, isBoss ? 8 : 30);
                    e.iceFrostTimer = Math.max(e.iceFrostTimer || 0, isBoss ? 30 : 90);
                }
                // ACID weapons MELT armor — apply an "acidTimer" that does
                // % HP damage over time + extra damage from all hits while
                // active (corrosion). Stacks worse than burn since the
                // damage scales with maxHp instead of being flat.
                if (b.acid) {
                    const isBoss = e.type === 'boss' || e.type === 'miniboss';
                    e.acidTimer = Math.max(e.acidTimer || 0, b.burnDur || 120);
                    // Bosses melt slower (1.5% maxHp per tick) so they're not
                    // dissolved instantly. Mobs melt fast (3% per tick).
                    e.acidPct = isBoss ? 0.015 : 0.03;
                }
                // WATER weapons short-circuit — applies a brief frozen-style
                // stun + slow. Doubly effective vs robots (basically all
                // enemies in this game), so deals 1.5× direct damage.
                if (b.water) {
                    const isBoss = e.type === 'boss' || e.type === 'miniboss';
                    e.frozen = Math.max(e.frozen || 0, isBoss ? 4 : 20);
                    e.waterShockTimer = Math.max(e.waterShockTimer || 0, isBoss ? 24 : 60);
                    // Water vs robot bonus
                    dmg = Math.round(dmg * 1.5);
                }
                // LIGHTNING STRIKE — bullet acts as a marker. On hit, a
                // bolt crashes down from above onto the enemy's position
                // and damages everything in a radius. The persistent bolt
                // sprite lives in lightningBolts[] for ~14 frames so the
                // strike is clearly visible (was particles-only — easy to miss).
                if (b.lightningStrike) {
                    const sx = e.x + e.w / 2;
                    const sy = e.y + e.h / 2;
                    const radius = b.strikeRadius || 110;
                    const strikeDmg = b.strikeDmg || 80;
                    // Damage all enemies in radius (including the impact target)
                    for (let ei = enemies.length - 1; ei >= 0; ei--) {
                        const e2 = enemies[ei];
                        const ddx = (e2.x + e2.w / 2) - sx;
                        const ddy = (e2.y + e2.h / 2) - sy;
                        if (ddx * ddx + ddy * ddy < radius * radius) {
                            e2.hp -= strikeDmg;
                            e2.waterShockTimer = Math.max(e2.waterShockTimer || 0, 40);
                            spawnDamageNumber(e2.x + e2.w / 2, e2.y, strikeDmg, 'crit');
                            if (e2.hp <= 0) handleEnemyKilled(e2, ei);
                        }
                    }
                    // Generate a zigzag bolt path top-of-camera → impact
                    const bolt = {
                        impactX: sx, impactY: sy, life: 14, maxLife: 14,
                        radius, segments: []
                    };
                    const segs = 12;
                    const topY = sy - 700;
                    for (let s = 0; s <= segs; s++) {
                        const t = s / segs;
                        bolt.segments.push({
                            x: sx + (Math.random() - 0.5) * 30 * (1 - t),
                            y: topY + (sy - topY) * t
                        });
                    }
                    lightningBolts.push(bolt);
                    spawnShockwave(sx, sy, radius, '#ffff44');
                    spawnShockwave(sx, sy, radius * 1.3, '#aaeeff');
                    spawnParticles(sx, sy, '#ffff44', 30, 6);
                    spawnParticles(sx, sy, '#ffffff', 20, 4);
                    screenShake = Math.max(screenShake, 14);
                    if (typeof critFlash !== 'undefined') critFlash = Math.min(1, critFlash + 0.45);
                    if (typeof audio !== 'undefined' && audio.play) audio.play('explosion', { throttle: 80 });
                }
                if (b.pierce) {
                    b.hitEnemies.add(e);
                } else {
                    hit = true;
                }
                spawnParticles(b.x, b.y, b.glow || '#ffff66', 6, 3);
                screenShake = 4;

                // Explosive bullet AOE
                if (b.explosive) {
                    const r = b.aoeRadius || 110;
                    spawnExplosion(b.x, b.y);
                    spawnParticles(b.x, b.y, '#ff8800', 20, 6);
                    screenShake = 12;
                    spawnShockwave(b.x, b.y, r * 1.2, '#ff8844');
                    for (const other of enemies) {
                        if (other === e) continue;
                        const dx = (other.x + other.w / 2) - b.x;
                        const dy = (other.y + other.h / 2) - b.y;
                        if (dx * dx + dy * dy < r * r) {
                            const aoeDmg = Math.round(b.damage * 0.6);
                            other.hp -= aoeDmg;
                            spawnDamageNumber(other.x + other.w/2, other.y, aoeDmg, 'aoe');
                        }
                    }
                }

                // ===== BAND BLASTER per-instrument on-impact effects =====
                // DRUM — knockback + slam shockwave on hit (additive to AOE)
                if (b.drumKnockback) {
                    e.x += Math.sign((e.x + e.w/2) - b.x) * 18;
                    e.vy = -7;
                    spawnShockwave(b.x, b.y, 140, '#ffdd44');
                    spawnShockwave(b.x, b.y, 80, '#ffffff');
                    screenShake = Math.max(screenShake, 8);
                    // Secondary residual ring 30 frames later — handled by
                    // the engine via the AOE block above; we just add visuals.
                    spawnParticles(b.x, b.y, '#ffdd44', 18, 7);
                }
                // CLARINET chain-arc — 4 nearest enemies take 50% chain dmg
                if (b.chainArc && !b._chained) {
                    b._chained = true;     // single-arc per bullet
                    const cap = b.chainCount || 4;
                    let arced = 0;
                    const candidates = [];
                    for (const o of enemies) {
                        if (o === e) continue;
                        const dx = (o.x + o.w/2) - b.x;
                        const dy = (o.y + o.h/2) - b.y;
                        const d2 = dx*dx + dy*dy;
                        if (d2 < (b.chainRadius || 220) * (b.chainRadius || 220)) {
                            candidates.push({ o, d2 });
                        }
                    }
                    candidates.sort((a, x) => a.d2 - x.d2);
                    for (const c of candidates) {
                        if (arced >= cap) break;
                        const o = c.o;
                        o.hp -= b.chainDmg || 100;
                        // Visual arc
                        const sx = b.x, sy = b.y;
                        const ex = o.x + o.w/2, ey = o.y + o.h/2;
                        // Spawn a few sparkle particles along the line
                        for (let k = 0; k < 5; k++) {
                            const tk = k / 5;
                            spawnParticles(
                                sx + (ex - sx) * tk,
                                sy + (ey - sy) * tk,
                                '#88ccff', 1, 3
                            );
                        }
                        spawnParticles(ex, ey, '#aaeeff', 10, 5);
                        spawnDamageNumber(ex, o.y, b.chainDmg, 'aoe');
                        if (o.hp <= 0) {
                            const idx = enemies.indexOf(o);
                            if (idx >= 0) handleEnemyKilled(o, idx);
                        }
                        arced++;
                    }
                    if (arced > 0) {
                        floatTexts.push({
                            text: `CHAIN x${arced}`, x: b.x, y: b.y - 30,
                            life: 50, color: '#88ccff'
                        });
                    }
                }
                // FLUTE split — fire 3 sparkle mini-notes outward on first hit
                if (b.fluteSplit && !b._split) {
                    b._split = true;
                    for (let s = 0; s < 3; s++) {
                        const sa = (s - 1) * 0.6 + Math.random() * 0.2;
                        bullets.push({
                            x: b.x, y: b.y,
                            vx: Math.cos(sa) * 11,
                            vy: Math.sin(sa) * 11 - 3,
                            life: 50,
                            damage: Math.round((b.damage || 80) * 0.5),
                            color: '#cc88ff', glow: '#aa44ff', size: 6,
                            pierce: false, hitEnemies: new Set(),
                            musicNote: true,
                            instrument: 3,
                            wobblePhase: Math.random() * Math.PI * 2
                        });
                    }
                    spawnParticles(b.x, b.y, '#aa44ff', 12, 5);
                }
                // SAX buff — pass-through hits buff allies in path (no special
                // per-impact behavior needed; sax notes pierce + heal on shot
                // already, this just adds a subtle visual on every contact).
                if (b.saxBuff) {
                    spawnParticles(b.x, b.y, '#ffaa00', 4, 3);
                }
                // ===== JAX BLASTER on-impact GOAL! split shots =====
                // Spawns 4 mini soccer balls in a fan, dealing 60% dmg.
                // Kid-pleasing "scored" pop on every hit.
                if (b.spawnGoalSpark) {
                    spawnShockwave(b.x, b.y, 80, '#ffffff');
                    floatTexts.push({
                        text: 'GOAL!', x: b.x, y: b.y - 30,
                        life: 50, color: '#ffdd44'
                    });
                    for (let s = 0; s < 4; s++) {
                        const sa = (s / 4) * Math.PI * 2;
                        bullets.push({
                            x: b.x, y: b.y,
                            vx: Math.cos(sa) * 14,
                            vy: Math.sin(sa) * 14,
                            life: 80,
                            damage: Math.round(b.damage * 0.6),
                            color: '#ffffff', glow: '#000000', size: 8,
                            pierce: false, hitEnemies: new Set(),
                            soccerBall: true,
                            explosive: true, aoeRadius: 60
                        });
                    }
                }
                // ===== MICAH MINECRAFTER on-impact green acid pool =====
                // Adds a damaging puddle ("lava patch") under the impact.
                if (b.leavesLava) {
                    if (typeof stageHazards !== 'undefined') {
                        stageHazards.push({
                            kind: 'lava', themed: 'minecraft',
                            x: b.x - 60, y: 540, w: 120, h: 24,
                            life: 360, dmg: 14,
                            color: '#44ff44', glow: '#88ff88'
                        });
                    }
                    spawnShockwave(b.x, b.y, 90, '#88ff88');
                    spawnParticles(b.x, b.y, '#44ff44', 18, 6);
                }
                // ===== MICAH MINECRAFTER bonus mob from impact =====
                // Each TNT detonation summons one extra free mob (skips the queue).
                if (b.craftBonus && typeof spawnMinecraftMob === 'function') {
                    const bonusKinds = ['zombie', 'wolf', 'enderman', 'blaze'];
                    const bk = bonusKinds[Math.floor(Math.random() * bonusKinds.length)];
                    spawnMinecraftMob(bk, b.x, b.y - 40, b.vx >= 0 ? 1 : -1, false);
                }

                if (e.hp <= 0) {
                    handleEnemyKilled(e, j);
                }
                if (!b.pierce) break;
            }
        }
        if (hit || b.life <= 0) bullets.splice(i, 1);
    }
}

// ============================================================================
// BOSS RUSH WEAKNESSES + INTRO VOICE LINES
// ============================================================================
// Each gauntlet boss takes 2x damage from a specific element. Hit them
// with the matching element (read from the bullet's flag) for crits.
// Mech King has no weakness — he's the mastermind.
const BOSS_RUSH_WEAKNESS = {
    guard:     { flag: 'lightning', label: '⚡ LIGHTNING', color: '#ffff44' },
    skyhammer: { flag: 'ice',       label: '❄ ICE',       color: '#aaeeff' },
    inferno:   { flag: 'water',     label: '💧 WATER',     color: '#88ccff' },
    ravager:   { flag: 'flame',     label: '🔥 FIRE',      color: '#ff4422' },
    cryo:      { flag: 'flame',     label: '🔥 FIRE',      color: '#ff4422' },
    nullifier: { flag: 'lightning', label: '⚡ LIGHTNING', color: '#ffff44' },
    omega:     { flag: 'acid',      label: '☣ ACID',       color: '#88ff44' },
    titan:     { flag: 'flame',     label: '🔥 FIRE',      color: '#ff4422' }
};
function bossRushWeakness(e) {
    if (!e || !e.bossRush || e.subtype === 'mechking') return null;
    return BOSS_RUSH_WEAKNESS[e.subtype] || null;
}
// Apply 2x damage if the bullet matches the boss's weakness element.
// Called from the bullet hit code.
function applyBossRushWeaknessMul(bullet, boss) {
    if (!bullet || !boss) return 1;
    const weak = bossRushWeakness(boss);
    if (!weak) return 1;
    if (bullet[weak.flag]) return 2.0;
    return 1;
}

// Intro voice lines — one per boss, shown as a brief speech bubble when
// the boss arena spawns. Stays for 180 frames then fades.
const BOSS_RUSH_INTRO_LINE = {
    guard:     'YOU SHALL NOT PASS THE GATE!',
    skyhammer: 'FROM THE SKIES, YOUR DOOM!',
    inferno:   'I AM THE HEART OF THE FORGE!',
    ravager:   'TASTE MY BARRELS, MEAT!',
    cryo:      'FREEZE WHERE YOU STAND!',
    nullifier: 'YOU NEVER EXISTED.',
    omega:     'CHILDREN, RISE TO MEET HIM!',
    titan:     'THE TITAN WILL CRUSH YOU!',
    mechking:  'KNEEL BEFORE THE THRONE.'
};

// ============================================================================
// BOSS RUSH FINAL TRANSFORMATIONS
// ============================================================================
// At 50% HP, every rush boss enters its THEMATIC FINAL FORM with a brief
// cinematic then a new map-altering ability. Each boss has a distinct
// transformation:
//   guard      → "RIOT KING"        — spawns shielder reinforcements
//   skyhammer  → "BOMBER PRIME"     — drops nuke meteors from above
//   inferno    → "INFERNO HEART"    — spawns lava columns in arena
//   ravager    → "ACID HORROR"      — spawns acid puddles + acid drones
//   cryo       → "ICE EMPEROR"      — tints arena icy + drops icicles
//   nullifier  → "BLACK HOLE LORD"  — spawns persistent void rifts
//   omega      → "OMEGA WRAITH"     — spawns mini-omega drones
//   titan      → "TITAN EMPEROR"    — drops debris meteors
//
// triggerBossRushTransform — fires once per boss when HP first crosses 50%.
// Sets `_rushTransformed`, `_rushTransformTimer` (cinematic length),
// `_rushFormName`, and `_rushTransformColor`.
const BOSS_RUSH_TRANSFORM_DEFS = {
    guard:     { name: 'RIOT KING',       color: '#88ff44', accent: '#aaff88' },
    skyhammer: { name: 'BOMBER PRIME',    color: '#ffaa00', accent: '#ffdd66' },
    inferno:   { name: 'INFERNO HEART',   color: '#ff4422', accent: '#ff8844' },
    ravager:   { name: 'ACID HORROR',     color: '#88ff44', accent: '#aaff66' },
    cryo:      { name: 'ICE EMPEROR',     color: '#88ddff', accent: '#aaeeff' },
    nullifier: { name: 'BLACK HOLE LORD', color: '#aa00ff', accent: '#cc88ff' },
    omega:     { name: 'OMEGA WRAITH',    color: '#ff44ff', accent: '#ffaaff' },
    titan:     { name: 'TITAN EMPEROR',   color: '#66ffff', accent: '#aaffff' }
};

function triggerBossRushTransform(e) {
    const def = BOSS_RUSH_TRANSFORM_DEFS[e.subtype] || {
        name: 'FINAL FORM', color: '#ff2244', accent: '#ffd744'
    };
    e._rushTransformed = true;
    e._rushTransformTimer = 90;
    e._rushFormName = def.name;
    e._rushTransformColor = def.color;
    e._rushFormAccent = def.accent;
    // Cinematic burst — 3 layered shockwaves + huge particle storm
    if (typeof spawnShockwave === 'function') {
        spawnShockwave(e.x + e.w/2, e.y + e.h/2, 200, def.color);
        spawnShockwave(e.x + e.w/2, e.y + e.h/2, 320, def.accent);
        spawnShockwave(e.x + e.w/2, e.y + e.h/2, 460, '#ffffff');
    }
    if (typeof spawnParticles === 'function') {
        spawnParticles(e.x + e.w/2, e.y + e.h/2, def.color, 80, 12);
        spawnParticles(e.x + e.w/2, e.y + e.h/2, def.accent, 60, 10);
        spawnParticles(e.x + e.w/2, e.y + e.h/2, '#ffffff', 40, 8);
    }
    screenShake = Math.max(screenShake, 30);
    hitStop = Math.max(hitStop, 12);
    // Boss grows ~15% bigger on transformation for visual impact
    if (!e._rushPreTransformW) {
        e._rushPreTransformW = e.w;
        e._rushPreTransformH = e.h;
        e.w = Math.round(e.w * 1.15);
        e.h = Math.round(e.h * 1.15);
        e.x -= (e.w - e._rushPreTransformW) / 2;
    }
    // Color shift to the form's signature color
    e.color = def.color;
    // Banner — uses the new form name
    if (typeof shopMessage !== 'undefined') {
        shopMessage = {
            text: '☠ FINAL FORM ☠   ' + def.name + '   AWAKENS',
            timer: 240,
            color: def.accent
        };
    }
    if (typeof audio !== 'undefined' && audio.play) {
        audio.play('bossIntro');
        audio.play('explosion', { throttle: 60 });
    }
}

// tickBossRushTransformAbility — per-frame ability after transformation.
// Each subtype has its own cooldown timer field on the boss (e._abilityCd).
function tickBossRushTransformAbility(e, slowMul) {
    if (!e._abilityCd) e._abilityCd = 60;
    e._abilityCd -= slowMul;
    if (e._abilityCd > 0) return;
    const ability = BOSS_RUSH_ABILITIES[e.subtype];
    if (!ability) {
        e._abilityCd = 240;
        return;
    }
    e._abilityCd = ability.cooldown + Math.random() * (ability.jitter || 30);
    ability.fire(e);
}

// Per-subtype final-form abilities. Each is called when the boss's
// _abilityCd hits 0 and resets the cooldown to its base + jitter.
const BOSS_RUSH_ABILITIES = {
    guard: {
        cooldown: 300, jitter: 60,
        fire(e) {
            // RIOT KING — summons 2 shielders to flank the player
            for (const sign of [-1, 1]) {
                enemies.push({
                    x: e.x + sign * 200, y: 510, w: 38, h: 40,
                    type: 'shielder', hp: 180, maxHp: 180,
                    vx: 1.4 * sign, dir: -sign,
                    shootTimer: 30,
                    patrolStart: e.x + sign * 200 - 100,
                    patrolEnd: e.x + sign * 200 + 100,
                    color: '#88ff44', shieldColor: '#aaff88',
                    _bossRushMinion: true
                });
            }
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#88ff44', 18, 6);
            screenShake = Math.max(screenShake, 8);
        }
    },
    skyhammer: {
        cooldown: 180, jitter: 30,
        fire(e) {
            // BOMBER PRIME — calls down 3 nuke meteors at player + offsets
            const targetX = (player && player.x) || e.x;
            for (let i = -1; i <= 1; i++) {
                const tx = targetX + i * 220;
                if (typeof stageHazards !== 'undefined') {
                    // Telegraph ring on the ground
                    stageHazards.push({
                        kind: 'lightning', x: tx, y: 0, vx: 0, vy: 0,
                        r: 28, life: 60, dmg: 0, color: '#ffff44',
                        telegraph: 60
                    });
                    // The actual nuke
                    stageHazards.push({
                        kind: 'meteor',
                        x: tx, y: -80 - i * 40,
                        vx: 0, vy: 6, gravity: 0.4,
                        r: 28, life: 240, dmg: 24,
                        color: '#ffaa00', fallStop: true,
                        homing: 0.05
                    });
                }
            }
            // Visual flash — bombing run
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#ffaa00', 14, 5);
            if (typeof shopMessage !== 'undefined' && Math.random() < 0.4) {
                shopMessage = { text: '⚠ BOMBING RUN INCOMING ⚠', timer: 90, color: '#ffaa00' };
            }
        }
    },
    inferno: {
        cooldown: 200, jitter: 40,
        fire(e) {
            // INFERNO HEART — spawns lava column erupting from ground
            const targetX = (player && player.x) || e.x;
            for (let i = -1; i <= 1; i++) {
                const tx = targetX + i * 140;
                if (typeof stageHazards !== 'undefined') {
                    stageHazards.push({
                        kind: 'lava',
                        x: tx, y: 540,
                        vx: 0, vy: -10,
                        gravity: 0.3,
                        r: 24, life: 220, dmg: 18,
                        color: '#ff3300'
                    });
                }
            }
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#ff4422', 16, 6);
            screenShake = Math.max(screenShake, 6);
        }
    },
    ravager: {
        cooldown: 240, jitter: 60,
        fire(e) {
            // ACID HORROR — spawns acid puddles + 1 acid drone monster
            const targetX = (player && player.x) || e.x;
            // 3 acid puddles around the player
            for (let i = -1; i <= 1; i++) {
                if (typeof stageHazards !== 'undefined') {
                    stageHazards.push({
                        kind: 'acidPuddle',
                        x: targetX + i * 100, y: 580,
                        w: 80, h: 16,
                        life: 360, dmg: 6,
                        color: '#88ff44'
                    });
                }
            }
            // 1 ACID MONSTER drone
            enemies.push({
                x: e.x - 60, y: e.y + e.h * 0.4,
                w: 32, h: 28,
                type: 'drone',
                hp: 120, maxHp: 120,
                baseY: e.y + e.h * 0.4 + Math.random() * 60,
                floatTimer: Math.random() * Math.PI * 2,
                shootTimer: 40,
                color: '#88ff44',
                acidShots: true,
                _bossRushMinion: true
            });
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#88ff44', 18, 6);
            screenShake = Math.max(screenShake, 6);
        }
    },
    cryo: {
        cooldown: 90, jitter: 30,
        fire(e) {
            // ICE EMPEROR — drops 3 falling icicles + adds an ice patch
            const targetX = (player && player.x) || e.x;
            for (let i = 0; i < 3; i++) {
                const tx = targetX + (Math.random() - 0.5) * 360;
                if (typeof stageHazards !== 'undefined') {
                    stageHazards.push({
                        kind: 'icicle',
                        x: tx, y: -20,
                        vx: 0, vy: 5, gravity: 0.3,
                        r: 16, life: 220, dmg: 12,
                        color: '#aaeeff', fallStop: true,
                        homing: 0.12,
                        onHit: function (p) {
                            p.iceSlowTimer = 90;
                            spawnParticles(p.x, p.y, '#aaeeff', 8, 4);
                        }
                    });
                }
            }
            // Persistent ice patch on the ground
            if (typeof stageHazards !== 'undefined') {
                stageHazards.push({
                    kind: 'gas',
                    x: targetX + (Math.random() - 0.5) * 200, y: 580,
                    w: 120, h: 14,
                    vx: 0, vy: 0,
                    r: 60, life: 540, dmg: 1,
                    color: '#aaeeff'
                });
            }
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#aaeeff', 14, 5);
        }
    },
    nullifier: {
        cooldown: 280, jitter: 60,
        fire(e) {
            // BLACK HOLE LORD — spawns 1-2 persistent black holes that pull
            // the player. Reuses the void-rift hazard kind (existing pull).
            const targetX = (player && player.x) || e.x;
            const count = 1 + (Math.random() < 0.4 ? 1 : 0);
            for (let i = 0; i < count; i++) {
                const hx = targetX + (Math.random() - 0.5) * 360;
                const hy = 380 + Math.random() * 100;
                if (typeof stageHazards !== 'undefined') {
                    stageHazards.push({
                        kind: 'voidRift',
                        x: hx, y: hy,
                        vx: 0, vy: 0,
                        r: 36, life: 360, dmg: 8,
                        color: '#aa00ff'
                    });
                }
                // Big visual — black hole spawn shockwave
                if (typeof spawnShockwave === 'function') {
                    spawnShockwave(hx, hy, 100, '#aa00ff');
                    spawnShockwave(hx, hy, 160, '#cc88ff');
                }
                spawnParticles(hx, hy, '#aa00ff', 20, 8);
                spawnParticles(hx, hy, '#000000', 14, 6);
            }
            screenShake = Math.max(screenShake, 14);
            if (typeof audio !== 'undefined' && audio.play) {
                audio.play('explosion', { throttle: 200 });
            }
        }
    },
    omega: {
        cooldown: 240, jitter: 50,
        fire(e) {
            // OMEGA WRAITH — spawns 2 mini-omega drones (homing + tough)
            for (const sign of [-1, 1]) {
                enemies.push({
                    x: e.x + sign * 150, y: e.y + 60, w: 30, h: 26,
                    type: 'drone', hp: 100, maxHp: 100,
                    baseY: e.y + 60,
                    floatTimer: Math.random() * Math.PI * 2,
                    shootTimer: 40,
                    color: '#ff44ff',
                    _bossRushMinion: true
                });
            }
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#ff44ff', 18, 6);
            screenShake = Math.max(screenShake, 6);
        }
    },
    titan: {
        cooldown: 200, jitter: 40,
        fire(e) {
            // TITAN EMPEROR — debris meteor storm
            const targetX = (player && player.x) || e.x;
            for (let i = -2; i <= 2; i++) {
                const tx = targetX + i * 120;
                if (typeof stageHazards !== 'undefined') {
                    stageHazards.push({
                        kind: 'meteor',
                        x: tx, y: -60,
                        vx: 0, vy: 5, gravity: 0.35,
                        r: 22, life: 240, dmg: 16,
                        color: '#66ffff', fallStop: true,
                        homing: 0.12
                    });
                }
            }
            spawnParticles(e.x + e.w/2, e.y + e.h/2, '#66ffff', 18, 6);
            screenShake = Math.max(screenShake, 8);
        }
    }
};

// drawBossRushTransformOverlay — visual highlight during the 90-frame
// transformation cinematic. Drawn ON TOP of the boss render. Counter-
// rotating energy rings + radial speed lines + form-name banner.
function drawBossRushTransformOverlay(e, ex, ey) {
    if (!e._rushTransformTimer || e._rushTransformTimer <= 0) return;
    const w = e.w;
    const h = e.h;
    const cx = ex + w / 2;
    const cy = ey + h / 2;
    const t = (90 - e._rushTransformTimer) / 90;   // 0..1 progress
    const color = e._rushTransformColor || '#ff2244';
    const accent = e._rushFormAccent || '#ffd744';
    ctx.save();
    // Counter-rotating energy rings — 3 of them, expanding outward
    for (let r = 0; r < 3; r++) {
        const radius = (50 + r * 40) + t * 60;
        const alpha = (1 - t) * (0.7 - r * 0.2);
        ctx.strokeStyle = r % 2 === 0 ? color : accent;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 18;
        ctx.globalAlpha = alpha;
        const rot = (e._rushTransformTimer * 0.05) * (r % 2 === 0 ? 1 : -1);
        ctx.beginPath();
        for (let s = 0; s < 12; s++) {
            const a1 = rot + (s / 12) * Math.PI * 2;
            const a2 = a1 + (Math.PI * 2 / 24);
            ctx.moveTo(cx + Math.cos(a1) * radius, cy + Math.sin(a1) * radius);
            ctx.lineTo(cx + Math.cos(a2) * radius, cy + Math.sin(a2) * radius);
        }
        ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;

    // Radial speed lines pointing at the boss center — converging
    const lines = 16;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 12;
    for (let l = 0; l < lines; l++) {
        const ang = (l / lines) * Math.PI * 2 + t * 0.3;
        const r1 = 80 + (1 - t) * 200;
        const r2 = 40 + t * 60;
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(ang) * r1, cy + Math.sin(ang) * r1);
        ctx.lineTo(cx + Math.cos(ang) * r2, cy + Math.sin(ang) * r2);
        ctx.stroke();
    }
    ctx.shadowBlur = 0;

    // Form name banner — flies in horizontally, fades out near end
    const bannerAlpha = t < 0.7 ? Math.min(1, t * 3) : Math.max(0, 1 - (t - 0.7) * 3);
    ctx.globalAlpha = bannerAlpha;
    ctx.font = 'bold 36px Courier New';
    ctx.textAlign = 'center';
    ctx.fillStyle = accent;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 22;
    ctx.fillText('☠ ' + (e._rushFormName || 'FINAL FORM') + ' ☠',
        canvas.width / 2, canvas.height / 2 - 80);
    ctx.font = 'bold 14px Courier New';
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = 14;
    ctx.fillText('— FINAL FORM AWAKENS —',
        canvas.width / 2, canvas.height / 2 - 50);
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
    ctx.restore();
}


// After Titan-Lord falls on stage 8, instead of the giant-mech finale we
// chain together 9 boss arenas in REGULAR-STAGE STYLE: normal-sized
// player, normal controls, the boss's own AI + arena theme. Order:
//   0..7 = the 8 prior bosses (GUARD-1, SKYHAMMER, ... TITAN-LORD)
//   8    = MECH KING (new boss — recoloured TITAN AI w/ extra HP)
// When index 8 falls, gameState='won'.
let bossRush = null;

// Per-boss themed platforms to the rush arena so each fight room
// feels distinct. Called from spawnBossRushBoss after buildBossArena.
// All platforms here are lightweight 'platform' type so they don't get
// stripped (buildBossArena ran already).
function addBossRushArenaDecor(idx, isFinal) {
    if (isFinal) {
        // === MECH KING throne room ===
        // Stepped throne dais behind the king + two flanking columns.
        // Player can hop on the dais to attack from above.
        platforms.push({ x: 980, y: 540, w: 220, h: 60, type: 'platform' });   // dais step 1
        platforms.push({ x: 1020, y: 480, w: 140, h: 60, type: 'platform' });  // dais step 2
        platforms.push({ x: 1060, y: 420, w: 60,  h: 60, type: 'platform' });  // throne base
        platforms.push({ x: 600,  y: 350, w: 24,  h: 250, type: 'wall' });     // left column
        platforms.push({ x: 1380, y: 350, w: 24,  h: 250, type: 'wall' });     // right column
        // Mid-air ledge to dodge ground-pound style attacks
        platforms.push({ x: 480,  y: 360, w: 110, h: 16, type: 'platform' });
        platforms.push({ x: 800,  y: 280, w: 110, h: 16, type: 'platform' });
        // Throne braziers — destructible interactives flanking the king
        addBossRushInteractive(1090, 410, 'brazier');     // left of throne
        addBossRushInteractive(1190, 410, 'brazier');     // right of throne
        return;
    }
    // Per-prior-boss layouts. Each arena gets 2-4 themed platforms
    // PLUS a destructible interactive themed to the boss.
    switch (idx) {
        case 0:  // GUARD-1 — facility crates as cover + destructible barrel
            platforms.push({ x: 360, y: 540, w: 90,  h: 60, type: 'platform' });
            platforms.push({ x: 880, y: 540, w: 90,  h: 60, type: 'platform' });
            addBossRushInteractive(620, 530, 'barrel');
            break;
        case 1:  // SKYHAMMER — floating sky platforms (he flies) + flak gun
            platforms.push({ x: 320, y: 380, w: 110, h: 14, type: 'platform' });
            platforms.push({ x: 540, y: 290, w: 100, h: 14, type: 'platform' });
            platforms.push({ x: 800, y: 380, w: 110, h: 14, type: 'platform' });
            addBossRushInteractive(560, 270, 'flak');
            break;
        case 2:  // INFERNO-X — broken bridges over a lava floor + steam vent
            platforms.push({ x: 280, y: 460, w: 130, h: 16, type: 'platform' });
            platforms.push({ x: 520, y: 460, w: 130, h: 16, type: 'platform' });
            platforms.push({ x: 760, y: 460, w: 130, h: 16, type: 'platform' });
            addBossRushInteractive(640, 540, 'vent');
            break;
        case 3:  // RAVAGER — scattered barricades + ammo cache
            platforms.push({ x: 280, y: 540, w: 70,  h: 60, type: 'platform' });
            platforms.push({ x: 460, y: 510, w: 70,  h: 90, type: 'platform' });
            platforms.push({ x: 640, y: 530, w: 70,  h: 70, type: 'platform' });
            platforms.push({ x: 880, y: 520, w: 70,  h: 80, type: 'platform' });
            addBossRushInteractive(560, 530, 'ammo');
            break;
        case 4:  // CRYO-LORD — ice columns + ice spike trap
            platforms.push({ x: 320, y: 420, w: 36,  h: 180, type: 'platform' });
            platforms.push({ x: 580, y: 380, w: 36,  h: 220, type: 'platform' });
            platforms.push({ x: 880, y: 420, w: 36,  h: 180, type: 'platform' });
            addBossRushInteractive(750, 540, 'icespike');
            break;
        case 5:  // NULLIFIER — disconnected void chunks + void anchor
            platforms.push({ x: 240, y: 380, w: 90,  h: 16, type: 'platform' });
            platforms.push({ x: 460, y: 320, w: 90,  h: 16, type: 'platform' });
            platforms.push({ x: 720, y: 380, w: 90,  h: 16, type: 'platform' });
            platforms.push({ x: 940, y: 320, w: 90,  h: 16, type: 'platform' });
            addBossRushInteractive(630, 540, 'voidanchor');
            break;
        case 6:  // OMEGA-PRIME — throne plateau + power crystal
            platforms.push({ x: 800, y: 540, w: 180, h: 60, type: 'platform' });   // throne base
            platforms.push({ x: 840, y: 480, w: 100, h: 60, type: 'platform' });   // throne step
            platforms.push({ x: 380, y: 380, w: 110, h: 16, type: 'platform' });
            addBossRushInteractive(440, 360, 'crystal');
            break;
        case 7:  // TITAN-LORD — ruined city debris + chandelier
            platforms.push({ x: 240, y: 480, w: 80,  h: 120, type: 'platform' });
            platforms.push({ x: 420, y: 420, w: 100, h: 180, type: 'platform' });
            platforms.push({ x: 880, y: 460, w: 90,  h: 140, type: 'platform' });
            platforms.push({ x: 320, y: 320, w: 90,  h: 14,  type: 'platform' });
            addBossRushInteractive(700, 200, 'chandelier');
            break;
    }
}

// addBossRushInteractive — places a destructible/usable arena prop.
// Stored in a `bossRushInteractives` array which is wiped on each spawn.
// Each kind has a unique on-shoot effect:
//   barrel       — explodes for 80 dmg + AOE around boss
//   brazier      — burns boss for 6s on shoot
//   flak         — fires anti-air bullets at boss every 2s
//   vent         — releases steam wave that pushes boss back
//   ammo         — give player +50 ammo / +20 RC pickup
//   icespike     — freezes boss for 2s
//   voidanchor   — disables boss attacks for 3s
//   crystal      — instant heal +30 HP for player
//   chandelier   — falls on boss for 200 dmg
let bossRushInteractives = [];
function addBossRushInteractive(x, y, kind) {
    bossRushInteractives.push({
        x, y,
        w: 36, h: 36,
        kind,
        hp: 30,
        used: false,
        anim: 0
    });
}

// Update interactives (animations + onShoot effect handling).
function updateBossRushInteractives() {
    if (!Array.isArray(bossRushInteractives)) return;
    for (let i = bossRushInteractives.length - 1; i >= 0; i--) {
        const it = bossRushInteractives[i];
        it.anim += 0.06;
        if (it.used) {
            it._fadeTimer = (it._fadeTimer || 30) - 1;
            if (it._fadeTimer <= 0) bossRushInteractives.splice(i, 1);
            continue;
        }
        // Bullet collision → trigger
        for (let bi = bullets.length - 1; bi >= 0; bi--) {
            const b = bullets[bi];
            if (b.x > it.x && b.x < it.x + it.w && b.y > it.y && b.y < it.y + it.h) {
                triggerBossRushInteractive(it);
                if (!b.pierce) bullets.splice(bi, 1);
                break;
            }
        }
    }
}

function triggerBossRushInteractive(it) {
    it.used = true;
    it._fadeTimer = 30;
    const boss = enemies.find(e => e.type === 'boss');
    spawnParticles(it.x + it.w/2, it.y + it.h/2, '#ffaa00', 24, 8);
    spawnShockwave(it.x + it.w/2, it.y + it.h/2, 80, '#ffaa00');
    screenShake = Math.max(screenShake, 12);
    if (typeof audio !== 'undefined' && audio.play) audio.play('explosion', { throttle: 60 });
    switch (it.kind) {
        case 'barrel':
            // Big explosion centred on the barrel — boss takes 80 if in range
            if (boss) {
                const dx = (boss.x + boss.w/2) - (it.x + it.w/2);
                const dy = (boss.y + boss.h/2) - (it.y + it.h/2);
                if (dx*dx + dy*dy < 200*200) {
                    boss.hp -= 80;
                    spawnDamageNumber(boss.x + boss.w/2, boss.y, 80, 'aoe');
                }
            }
            break;
        case 'brazier':
        case 'flak':
        case 'vent':
        case 'icespike':
        case 'voidanchor':
        case 'chandelier':
            // All elemental traps deal damage + apply a status effect via flags
            if (boss) {
                let dmg = 100;
                if (it.kind === 'chandelier') dmg = 200;
                if (it.kind === 'voidanchor') dmg = 60;
                boss.hp -= dmg;
                spawnDamageNumber(boss.x + boss.w/2, boss.y, dmg, 'crit');
                // Status effects
                if (it.kind === 'brazier') { boss.burnTimer = 360; boss.burnDamage = 6; }
                if (it.kind === 'icespike') { boss.iceSlowTimer = 120; }
                if (it.kind === 'voidanchor') { boss.attackTimer = Math.max(boss.attackTimer || 0, 180); }
            }
            break;
        case 'ammo':
            if (typeof player !== 'undefined') {
                player.hp = Math.min(player.maxHp, player.hp + 30);
                player.robotCoins = (player.robotCoins || 0) + 20;
                spawnDamageNumber(player.x, player.y - 30, 30, 'heal');
            }
            break;
        case 'crystal':
            if (typeof player !== 'undefined') {
                player.hp = Math.min(player.maxHp, player.hp + 50);
                spawnDamageNumber(player.x, player.y - 30, 50, 'heal');
            }
            break;
    }
    if (typeof shopMessage !== 'undefined') {
        shopMessage = {
            text: '⚒ ' + it.kind.toUpperCase() + ' TRIGGERED ⚒',
            timer: 90,
            color: '#ffd744'
        };
    }
}

// Render the interactives — kid-readable icons with a shoot prompt.
function drawBossRushInteractives() {
    if (!Array.isArray(bossRushInteractives) || bossRushInteractives.length === 0) return;
    for (const it of bossRushInteractives) {
        if (it.used && it._fadeTimer < 30) continue;
        const sx = Math.round(it.x - camera.x);
        const sy = Math.round(it.y - camera.y);
        const w = it.w;
        const h = it.h;
        const t = it.anim;
        ctx.save();
        // Color theme per kind
        const colors = {
            barrel:     ['#aa4400', '#ff8800'],
            brazier:    ['#aa2200', '#ff4422'],
            flak:       ['#444444', '#aaaaaa'],
            vent:       ['#225555', '#88ddff'],
            ammo:       ['#aa6600', '#ffd744'],
            icespike:   ['#225588', '#aaeeff'],
            voidanchor: ['#220044', '#aa00ff'],
            crystal:    ['#aa0044', '#ff44ff'],
            chandelier: ['#aa6600', '#ffd744']
        }[it.kind] || ['#666', '#aaa'];
        // Drop shadow
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(sx + w/2, sy + h + 4, w/2 + 2, 5, 0, 0, Math.PI * 2);
        ctx.fill();
        // Body — pulsing
        const pulse = 1 + Math.sin(t * 2) * 0.06;
        ctx.shadowColor = colors[1];
        ctx.shadowBlur = 12;
        ctx.fillStyle = colors[0];
        ctx.fillRect(sx + (1 - pulse) * w / 2, sy + (1 - pulse) * h / 2,
                     w * pulse, h * pulse);
        ctx.fillStyle = colors[1];
        ctx.fillRect(sx + 4 + (1 - pulse) * w / 2, sy + 4 + (1 - pulse) * h / 2,
                     (w - 8) * pulse, (h - 8) * pulse);
        ctx.shadowBlur = 0;
        // Kind icon
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 20px Courier New';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const icons = {
            barrel: '💥', brazier: '🔥', flak: '⚙', vent: '💨',
            ammo: '⚡', icespike: '❄', voidanchor: '🕳', crystal: '💎',
            chandelier: '✨'
        };
        ctx.fillText(icons[it.kind] || '?', sx + w/2, sy + h/2);
        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';
        // Hint label above
        ctx.fillStyle = colors[1];
        ctx.font = 'bold 9px Courier New';
        ctx.textAlign = 'center';
        ctx.shadowColor = colors[1];
        ctx.shadowBlur = 6;
        ctx.fillText('SHOOT', sx + w/2, sy - 4);
        ctx.shadowBlur = 0;
        ctx.textAlign = 'left';
        ctx.restore();
    }
}


function spawnBossRushBoss(idx) {
    const isFinal = idx >= STAGES.length;
    let bossDef;
    if (!isFinal) {
        // Set the stage so buildLevel uses the right config
        currentStage = idx;
        // Build the regular stage so the live `enemies` array gets populated
        // with the stage's boss (the boss def lives inside buildStage1/2/...
        // not in STAGES[].enemies). Then we extract & deep-copy the boss
        // and wipe everything else for a clean arena.
        if (typeof buildLevel === 'function') buildLevel();
        const liveBoss = enemies.find(e => e && e.type === 'boss');
        if (!liveBoss) {
            console.error('Boss rush: no boss in built stage', idx);
            return;
        }
        bossDef = JSON.parse(JSON.stringify(liveBoss));
        // === BOSS RUSH BUFF — bosses are way stronger than their stage versions ===
        // Each boss in the rush gets:
        //   - 100% of buildLevel's already-buffed HP (was 80% — still too weak)
        //   - PHASE 3 (RAGE) ATTACKS UNLOCKED FROM THE START
        //   - Faster fire rate (-40% shoot cooldown)
        //   - Higher damage (1.7x base)
        //   - Summons reinforcements when low HP (handled in updateEnemies)
        const rushScale = idx < 4 ? 1.0 : 0.85;
        // === NEW GAME+ MULTIPLIER ===
        // Each completed run bumps a save flag; subsequent runs get
        // tougher bosses. Stacks linearly so loop 4 = 2.0x HP / 1.6x damage.
        const ngLoop = (bossRush && bossRush.loop) || 0;
        const ngHpMul = 1 + ngLoop * 0.5;
        const ngDmgMul = 1 + ngLoop * 0.2;
        bossDef.hp = Math.max(1000, Math.round(bossDef.hp * rushScale * ngHpMul));
        bossDef.maxHp = bossDef.hp;
        // Phase 3 from the start — gives the player the FULL boss arsenal
        // immediately. All rage-mode attacks active.
        bossDef.phase = 3;
        bossDef.phase2Triggered = true;
        bossDef.phase3Triggered = true;
        // Faster fire rate
        bossDef.shootTimer = Math.max(30, Math.round((bossDef.shootTimer || 100) * 0.6));
        // Heavier hitting — extra damage multiplier baked into the def
        bossDef.dmgMul = 1.7 * ngDmgMul;
        // Boss-rush flag so drawEnemies + updateEnemies can apply rush-only
        // visuals (rage aura overlay) and behaviors (summon-on-low-hp).
        bossDef.bossRush = true;
        // Suppress per-stage cutscene + victory cutscene so the rush
        // doesn't freeze on cinematic dialogue.
        const stage = STAGES[idx];
        if (stage) {
            stage.cutsceneShown = true;
            stage.victoryCutsceneShown = true;
        }
    } else {
        // === MECH KING — final boss (idx 8) ===
        // Custom subtype 'mechking' — uses titan as AI base for the heavy
        // attacks but rendered as a TOTALLY DIFFERENT silhouette: massive
        // throne-king with crown, cape, scepter, and twin shoulder pylons.
        // Stats are stronger than every gauntlet boss combined: 50000 HP,
        // 180% damage boost, very fast fire rate, all phases unlocked.
        // (Buffed Jun 7 v3: kid said "stronger and more HP" — 24k -> 50k,
        // 1.9x -> 2.8x dmg, 40f -> 26f shoot cooldown.)
        const ngLoopK = (bossRush && bossRush.loop) || 0;
        const ngHpMulK = 1 + ngLoopK * 0.5;
        const ngDmgMulK = 1 + ngLoopK * 0.2;
        bossDef = {
            type: 'boss', subtype: 'mechking',
            x: 4700, y: 240, w: 280, h: 300,    // also bigger silhouette
            hp: Math.round(50000 * ngHpMulK),
            maxHp: Math.round(50000 * ngHpMulK),
            phase: 3,                       // start in rage protocol
            phase2Triggered: true,
            phase3Triggered: true,
            shootTimer: 26,                 // fast attack rate (was 40)
            moveTimer: 0,
            baseX: 4700, baseY: 240,
            color: '#ff2244',
            attackPattern: 0,
            dmgMul: 2.8 * ngDmgMulK,        // was 1.9
            displayName: 'MECH KING',
            isMechKing: true,
            bossRush: true,
            // MECH KING uses the TITAN AI under the hood — set the alias
            // so updateEnemies routes to updateBossTitan when subtype is
            // 'mechking' (handled by the dispatch fallthrough below).
            aiSubtype: 'titan',
            // Trigger the anime entrance overlay on first spawn
            _animeEntrance: true
        };
        currentStage = STAGES.length - 1;   // keep stage-8 theming for final
    }

    // Reset player to a clean arena entry position
    player.x = 200;
    player.y = 380;
    player.vx = 0; player.vy = 0;
    player.invincible = 90;
    if (player.hp < player.maxHp * 0.5) {
        player.hp = Math.min(player.maxHp, player.hp + Math.round(player.maxHp * 0.40));
    }

    // Wipe arena state — fresh start each boss
    bullets = [];
    enemyBullets = [];
    particles = [];
    enemies = [];
    coinPickups = [];
    healthDrops = [];
    crates = [];
    if (typeof minecraftMobs !== 'undefined') minecraftMobs = [];
    if (typeof minecraftBlocks !== 'undefined') minecraftBlocks = [];
    if (typeof minecraftSpawners !== 'undefined') minecraftSpawners = [];
    if (typeof primusTitans !== 'undefined') primusTitans = [];
    if (typeof dancingDragons !== 'undefined') dancingDragons = [];
    bossRushInteractives = [];   // wipe per-arena interactives
    // Also wipe stage props so leftover arena gates / danger zones / shops
    // / terminals / lasers / keys from buildLevel don't clutter the rush.
    if (typeof dangerZones !== 'undefined') dangerZones = [];
    if (typeof arenaGates !== 'undefined') arenaGates = [];
    if (typeof bossGates !== 'undefined') bossGates = [];
    if (typeof keyPickups !== 'undefined') keyPickups = [];
    if (typeof terminals !== 'undefined') terminals = [];
    if (typeof laserGrids !== 'undefined') laserGrids = [];
    if (typeof exitPortals !== 'undefined') exitPortals = [];
    if (typeof switches !== 'undefined') switches = [];
    if (typeof doors !== 'undefined') doors = [];
    if (typeof cages !== 'undefined') cages = [];
    if (typeof healingStations !== 'undefined') healingStations = [];
    if (typeof stageHazards !== 'undefined') stageHazards = [];
    if (player) player.keysHeld = [];

    // Build a fresh ground line — but stripped + re-added below so it
    // survives buildBossArena's in-range platform purge.
    platforms = [];

    // Use the existing arena builder — it strips local platforms (already
    // empty), places the boss at the far right, and clears stage hazards
    // in the range.
    buildBossArena(idx, player.x, bossDef);

    // Re-add a wide ground platform AFTER buildBossArena so the player
    // has solid floor to walk on. (buildBossArena strips platforms that
    // overlap its range — adding before would lose the ground.)
    platforms.push({ x: 0, y: 600, w: 4000, h: 100, type: 'ground' });

    // === Per-boss arena layout — gives each fight a distinctive look ===
    // Adds a few themed platforms so the rooms feel different. Lightweight
    // variety without rebuilding entire stages.
    addBossRushArenaDecor(idx, isFinal);

    // Move the boss CLOSER to the player so they're visible right from
    // the start of the round. buildBossArena placed it at the far right
    // (~1800px) which means walking right ~1500px to reach it. For a
    // boss rush we want the boss in view immediately.
    bossDef.x = isFinal ? 850 : 700;
    bossDef.baseX = bossDef.x;
    bossDef.y = 380;
    bossDef.baseY = 380;

    enemies.push(bossDef);

    // Reset camera to the player so the new arena lines up
    camera.x = Math.max(0, player.x - canvas.width * 0.3);

    // Banner — different for prior boss vs final mech king
    if (typeof shopMessage !== 'undefined') {
        const stageName = !isFinal && STAGES[idx] && STAGES[idx].name
            ? (STAGES[idx].name.split(':')[1] || '').trim()
            : '';
        if (isFinal) {
            shopMessage = {
                text: '⚜ FINAL BOSS — MECH KING ⚜  THE MASTERMIND DESCENDS',
                timer: 300,
                color: '#ff2244'
            };
        } else {
            shopMessage = {
                text: `⚔ BOSS RUSH ${idx + 1}/9 — ${(bossDef.subtype || 'BOSS').toUpperCase()} (${stageName})`,
                timer: 240,
                color: '#ffaa44'
            };
        }
    }
    if (typeof audio !== 'undefined' && audio.play) audio.play('bossIntro');

    // === Boss intro speech bubble — short voice line above the boss ===
    // Sets a `bossSpeechBubble` field on the boss that the renderer reads.
    const subkey = isFinal ? 'mechking' : (bossDef.subtype || '');
    const introLine = BOSS_RUSH_INTRO_LINE[subkey];
    if (introLine) {
        bossDef.bossSpeechBubble = {
            text: introLine,
            timer: 240,        // visible duration
            maxTimer: 240
        };
    }

    // === MECH KING grand entrance ===
    // Uses a custom flash + shockwave entrance instead of the omega-themed
    // throne cutscene (which was misaligned for MECH KING and made him
    // appear invisible). The throne backdrop now stays permanently behind
    // the boss for the whole fight via drawBossMechKing's throne-back layer.
    if (isFinal) {
        // Big screen-shake + radial shockwaves + particles around the king
        if (typeof screenShake !== 'undefined') screenShake = 32;
        if (typeof spawnShockwave === 'function') {
            spawnShockwave(bossDef.x + bossDef.w / 2, bossDef.y + bossDef.h / 2, 280, '#ff2244');
            spawnShockwave(bossDef.x + bossDef.w / 2, bossDef.y + bossDef.h / 2, 420, '#ffd744');
        }
        if (typeof spawnParticles === 'function') {
            spawnParticles(bossDef.x + bossDef.w / 2, bossDef.y + bossDef.h / 2, '#ff2244', 80, 12);
            spawnParticles(bossDef.x + bossDef.w / 2, bossDef.y + bossDef.h / 2, '#ffd744', 60, 9);
            spawnParticles(bossDef.x + bossDef.w / 2, bossDef.y + bossDef.h / 2, '#ffffff', 40, 8);
        }
        if (typeof hitStop !== 'undefined') hitStop = 14;
        // Dramatic banner — replaces the regular boss-rush banner
        if (typeof shopMessage !== 'undefined') {
            shopMessage = {
                text: '⚜  M E C H   K I N G  —  T H E   T H R O N E   D E S C E N D S  ⚜',
                timer: 360,
                color: '#ffd744'
            };
        }
        // Brief invincibility so the kid sees the king before damage starts
        bossDef.invincible = 60;
    }
}

// Entry point — kicks off the boss rush. Replaces the old startFinale
// call after stage 8 in normal play. The giant-mech finale rig still
// exists (dev panel button) for testing but is no longer the main ending.
function startBossRush() {
    // Read NG+ loop count from save — each completed run bumps it
    let loop = 0;
    if (typeof save !== 'undefined') {
        const meta = save.getMeta();
        loop = (meta.bossRushLoop || 0);
    }
    bossRush = {
        active: true,
        index: 0,
        loop: loop,
        bossesKilledThisLoop: 0
    };
    spawnBossRushBoss(0);
    gameState = 'playing';
    if (loop > 0 && typeof shopMessage !== 'undefined') {
        shopMessage = {
            text: '⚜  N E W   G A M E +   —   L O O P  ' + (loop + 1) + '  ⚜',
            timer: 360,
            color: '#ffd744'
        };
    }
}

