// =====================================================================
// === MECH SPRITES — actual visual designs for each form ==============
// =====================================================================
// Replaces the simple "outline glow + tint" look from earlier with full
// per-mech silhouettes drawn ON TOP of the existing player render.
// Order matters: this runs late (after the normal player body draws)
// so the mech silhouette covers the default character.
//
// Each design is hand-drawn with rectangles + arcs + glow lines so the
// mech reads instantly:
//   • NINJA — slim, hooded silhouette, twin shoulder katanas, scarf trail
//   • TITAN — bulky shoulders, twin chest cannons, crown crest, glowing core
//   • BERSERKER — exposed coils, heat vents on shoulders, skull faceplate
//   • SPIDER — extra walking legs sprouting from torso, segmented carapace
//   • STEALTH — phase-glitched outline, ghost crests on shoulders, faded
//
// All renders take (px, py) where px = player.x - camera.x.
// ---------------------------------------------------------------------

SC.mechs.renderSprite = function() {
    if (!this.activeForm) return;
    const def = this.defs[this.activeForm];
    if (!def) return;
    // Don't render the mech sprite during cinematics / boss intros where
    // the player isn't supposed to be visible — those screens have their
    // own actor rendering and the mech sprite would float in oddly.
    if (gameState === 'bossIntro' || gameState === 'evoCutscene' ||
        gameState === 'cutscene' || gameState === 'throneCutscene' ||
        gameState === 'spaceTransition' || gameState === 'stageComplete') {
        return;
    }
    // === Pacific Rim sprite scaling ===
    // The hitbox is the small standard player size. The sprite is
    // drawn at spriteScale× that size, centered horizontally on the
    // hitbox, with the bottom of the sprite anchored to the bottom
    // of the hitbox (so the mech's feet land where the player feet
    // would land). Result: sprite looks like a giant Jaeger but the
    // player still fits through the same doorways.
    //
    // FOOT_LIFT — visual nudge UP so the mech's feet sit clearly
    // above the platform top instead of clipping into the visible
    // floor band (some stages have thick decorative floor visuals
    // below the platform's collision top).
    const FOOT_LIFT = 6;
    const scale = def.spriteScale || 1.3;
    const w = player.w * scale;
    const h = player.h * scale;
    const px = (player.x + player.w / 2) - (w / 2) - camera.x;
    const py = (player.y + player.h) - h - FOOT_LIFT;
    const cx = px + w / 2;
    const cy = py + h / 2;
    const facing = player.facing || 1;

    ctx.save();

    // === NINJA MECH ===
    if (this.activeForm === 'ninja') {
        // Body: dark slim torso with magenta accents
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 14;
        // Hooded helm
        ctx.fillStyle = '#1a0a22';
        ctx.fillRect(px + w * 0.18, py - 4, w * 0.64, h * 0.32);
        // Hood spike top (anime ninja silhouette)
        ctx.beginPath();
        ctx.moveTo(px + w * 0.18, py - 2);
        ctx.lineTo(cx - 2, py - 14);
        ctx.lineTo(cx + 2, py - 14);
        ctx.lineTo(px + w * 0.82, py - 2);
        ctx.closePath();
        ctx.fill();
        // Glowing visor slit (single horizontal line, magenta)
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 18;
        ctx.fillRect(px + w * 0.28, py + h * 0.12, w * 0.44, 3);
        // Slim torso (tapered)
        ctx.shadowBlur = 10;
        ctx.fillStyle = '#2a0033';
        ctx.beginPath();
        ctx.moveTo(px + w * 0.22, py + h * 0.30);
        ctx.lineTo(px + w * 0.78, py + h * 0.30);
        ctx.lineTo(px + w * 0.62, py + h * 0.74);
        ctx.lineTo(px + w * 0.38, py + h * 0.74);
        ctx.closePath();
        ctx.fill();
        // Chest core diamond
        ctx.fillStyle = def.accent;
        ctx.shadowBlur = 14;
        ctx.beginPath();
        ctx.moveTo(cx, py + h * 0.36);
        ctx.lineTo(cx + 6, py + h * 0.46);
        ctx.lineTo(cx, py + h * 0.56);
        ctx.lineTo(cx - 6, py + h * 0.46);
        ctx.closePath();
        ctx.fill();
        // Twin shoulder katana hilts (black with magenta tip)
        for (const sx of [px + w * 0.16, px + w * 0.84]) {
            ctx.fillStyle = '#000';
            ctx.shadowBlur = 0;
            ctx.fillRect(sx - 2, py + h * 0.22, 4, h * 0.40);
            ctx.fillStyle = def.color;
            ctx.shadowColor = def.color;
            ctx.shadowBlur = 12;
            ctx.fillRect(sx - 1, py + h * 0.22, 2, 6);
        }
        // Slim legs
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#1a0022';
        ctx.fillRect(px + w * 0.30, py + h * 0.74, w * 0.16, h * 0.26);
        ctx.fillRect(px + w * 0.54, py + h * 0.74, w * 0.16, h * 0.26);
        // Magenta knee accents
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 8;
        ctx.fillRect(px + w * 0.30, py + h * 0.85, w * 0.16, 2);
        ctx.fillRect(px + w * 0.54, py + h * 0.85, w * 0.16, 2);
        // Trailing scarf — animated horizontal sine wave behind the back
        ctx.shadowBlur = 12;
        ctx.fillStyle = def.color;
        const t = Date.now() / 100;
        const scarfX = facing > 0 ? px + w * 0.18 : px + w * 0.82;
        for (let i = 0; i < 8; i++) {
            const sy = py + h * 0.34 + i * 4;
            const sx = scarfX - facing * (i * 3 + 4) + Math.sin(t + i * 0.6) * 3;
            ctx.fillRect(sx, sy, 4, 3);
        }
    }

    // === TITAN MECH ===
    else if (this.activeForm === 'titan') {
        // Pulsing yellow core glow behind the body
        const pulse = 0.7 + Math.sin(Date.now() / 200) * 0.3;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 20 * pulse;
        // Helm — square with raised crown
        ctx.fillStyle = '#3a1d00';
        ctx.fillRect(px + w * 0.10, py, w * 0.80, h * 0.30);
        // Crown crests (3 spikes top)
        ctx.fillStyle = def.color;
        ctx.shadowBlur = 14;
        for (const sx of [px + w * 0.20, cx - 3, px + w * 0.74]) {
            ctx.beginPath();
            ctx.moveTo(sx, py);
            ctx.lineTo(sx + 3, py - 8);
            ctx.lineTo(sx + 6, py);
            ctx.closePath();
            ctx.fill();
        }
        // Glowing wide visor
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 18;
        ctx.fillRect(px + w * 0.16, py + h * 0.10, w * 0.68, 5);
        // Massive shoulder pauldrons (trapezoidal, gold-banded)
        ctx.fillStyle = '#552200';
        ctx.shadowBlur = 0;
        ctx.beginPath();
        ctx.moveTo(px - w * 0.05, py + h * 0.28);
        ctx.lineTo(px + w * 0.20, py + h * 0.22);
        ctx.lineTo(px + w * 0.30, py + h * 0.42);
        ctx.lineTo(px - w * 0.10, py + h * 0.46);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(px + w * 1.05, py + h * 0.28);
        ctx.lineTo(px + w * 0.80, py + h * 0.22);
        ctx.lineTo(px + w * 0.70, py + h * 0.42);
        ctx.lineTo(px + w * 1.10, py + h * 0.46);
        ctx.closePath();
        ctx.fill();
        // Gold bands across pauldrons
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 8;
        ctx.fillRect(px - w * 0.08, py + h * 0.36, w * 0.30, 3);
        ctx.fillRect(px + w * 0.78, py + h * 0.36, w * 0.30, 3);
        // Heavy chest with twin chest-mounted cannons
        ctx.fillStyle = '#2a1500';
        ctx.shadowBlur = 0;
        ctx.fillRect(px + w * 0.18, py + h * 0.30, w * 0.64, h * 0.40);
        // Cannon barrels (left + right of chest, glowing)
        ctx.fillStyle = '#1a0a00';
        ctx.fillRect(px + w * 0.22, py + h * 0.40, w * 0.18, 8);
        ctx.fillRect(px + w * 0.60, py + h * 0.40, w * 0.18, 8);
        // Cannon glow tips
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 14 * pulse;
        ctx.fillRect(px + w * 0.20, py + h * 0.40, 4, 8);
        ctx.fillRect(px + w * 0.76, py + h * 0.40, 4, 8);
        // Glowing core (Matrix-of-Leadership look) center chest
        ctx.beginPath();
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 24 * pulse;
        ctx.arc(cx, py + h * 0.50, 7 * pulse, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.arc(cx, py + h * 0.50, 3, 0, Math.PI * 2);
        ctx.fill();
        // Heavy legs — wide stance
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#3a1d00';
        ctx.fillRect(px + w * 0.18, py + h * 0.70, w * 0.26, h * 0.30);
        ctx.fillRect(px + w * 0.56, py + h * 0.70, w * 0.26, h * 0.30);
        // Foot plates (big stompy boots)
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 6;
        ctx.fillRect(px + w * 0.16, py + h - 4, w * 0.30, 4);
        ctx.fillRect(px + w * 0.54, py + h - 4, w * 0.30, 4);
    }

    // === BERSERKER MECH ===
    else if (this.activeForm === 'berserker') {
        const heat = (typeof SC !== 'undefined' && SC.heat) ? SC.heat.level : 0;
        const heatFrac = Math.min(1, heat / 100);
        // Heat-driven red/orange tint scaling
        const torsoTint = heat > 50 ? '#5a1a1a' : '#3a0a0a';
        // Skull faceplate (square with eye sockets glowing red)
        ctx.shadowColor = '#ff8866';
        ctx.shadowBlur = 14 + heatFrac * 14;
        ctx.fillStyle = '#1a0000';
        ctx.fillRect(px + w * 0.16, py - 2, w * 0.68, h * 0.30);
        // Top "horns" (two angular spikes — demonic feel)
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.moveTo(px + w * 0.18, py - 2);
        ctx.lineTo(px + w * 0.06, py - 14);
        ctx.lineTo(px + w * 0.26, py + 2);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(px + w * 0.82, py - 2);
        ctx.lineTo(px + w * 0.94, py - 14);
        ctx.lineTo(px + w * 0.74, py + 2);
        ctx.closePath();
        ctx.fill();
        // Glowing eye sockets — get hotter with heat
        ctx.fillStyle = `rgb(${Math.floor(255)}, ${Math.floor(80 + heatFrac * 80)}, ${Math.floor(40)})`;
        ctx.shadowColor = '#ff2244';
        ctx.shadowBlur = 14 + heatFrac * 18;
        ctx.fillRect(px + w * 0.28, py + h * 0.10, w * 0.16, 5);
        ctx.fillRect(px + w * 0.56, py + h * 0.10, w * 0.16, 5);
        // Torso — exposed coils on the chest (red-hot lines)
        ctx.fillStyle = torsoTint;
        ctx.shadowBlur = 0;
        ctx.fillRect(px + w * 0.18, py + h * 0.30, w * 0.64, h * 0.42);
        // Coil lines across chest — flicker harder with heat
        ctx.shadowColor = '#ff4422';
        ctx.shadowBlur = 8 + heatFrac * 12;
        ctx.fillStyle = `rgba(255, ${100 + Math.floor(heatFrac * 100)}, 60, ${0.6 + heatFrac * 0.4})`;
        for (let i = 0; i < 4; i++) {
            const cy0 = py + h * 0.34 + i * 6;
            ctx.fillRect(px + w * 0.22, cy0, w * 0.56, 2);
        }
        // Shoulder heat vents (triangular, glowing orange)
        ctx.fillStyle = '#ff4422';
        ctx.shadowColor = '#ff8800';
        ctx.shadowBlur = 10 + heatFrac * 10;
        ctx.beginPath();
        ctx.moveTo(px + w * 0.06, py + h * 0.32);
        ctx.lineTo(px + w * 0.24, py + h * 0.30);
        ctx.lineTo(px + w * 0.16, py + h * 0.42);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(px + w * 0.94, py + h * 0.32);
        ctx.lineTo(px + w * 0.76, py + h * 0.30);
        ctx.lineTo(px + w * 0.84, py + h * 0.42);
        ctx.closePath();
        ctx.fill();
        // Legs
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#2a0a0a';
        ctx.fillRect(px + w * 0.22, py + h * 0.72, w * 0.22, h * 0.28);
        ctx.fillRect(px + w * 0.56, py + h * 0.72, w * 0.22, h * 0.28);
        // Knee accents
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 6;
        ctx.fillRect(px + w * 0.22, py + h * 0.84, w * 0.22, 3);
        ctx.fillRect(px + w * 0.56, py + h * 0.84, w * 0.22, 3);
        // Heat steam puffs around shoulders when high heat
        if (heatFrac > 0.4) {
            ctx.shadowBlur = 0;
            ctx.fillStyle = `rgba(255, 200, 150, ${heatFrac * 0.5})`;
            for (let i = 0; i < 4; i++) {
                const ang = (Date.now() / 120 + i * 1.5) % (Math.PI * 2);
                const r = 6 + (Date.now() / 200 + i * 3) % 12;
                ctx.beginPath();
                ctx.arc(cx + Math.cos(ang) * (w * 0.5 + 4), py + h * 0.30 + Math.sin(ang) * 6 - r * 0.3,
                        2 + Math.sin(Date.now() / 80 + i) * 1, 0, Math.PI * 2);
                ctx.fill();
            }
        }
    }

    // === SPIDER MECH ===
    else if (this.activeForm === 'spider') {
        // Compact rounded body + 4 extra spider legs sprouting from torso
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 12;
        // Torso — segmented carapace, oval green with darker bands
        ctx.fillStyle = '#0a2a0a';
        ctx.beginPath();
        ctx.ellipse(cx, py + h * 0.48, w * 0.42, h * 0.34, 0, 0, Math.PI * 2);
        ctx.fill();
        // Segment lines
        ctx.strokeStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 8;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.ellipse(cx, py + h * 0.42, w * 0.32, h * 0.10, 0, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(cx, py + h * 0.55, w * 0.36, h * 0.14, 0, 0, Math.PI * 2);
        ctx.stroke();
        // Head — small, top of body, with multi-eye look
        ctx.fillStyle = '#1a3a1a';
        ctx.shadowBlur = 0;
        ctx.beginPath();
        ctx.ellipse(cx, py + h * 0.18, w * 0.28, h * 0.18, 0, 0, Math.PI * 2);
        ctx.fill();
        // 4 glowing eyes (2 rows of 2)
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 8;
        for (const ey of [py + h * 0.13, py + h * 0.20]) {
            ctx.beginPath();
            ctx.arc(cx - 5, ey, 2, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(cx + 5, ey, 2, 0, Math.PI * 2);
            ctx.fill();
        }
        // Spider legs — 4 legs sprouting from torso (2 each side, segmented)
        ctx.shadowBlur = 6;
        ctx.strokeStyle = '#0a2a0a';
        ctx.lineWidth = 3;
        const legAnim = Math.sin(Date.now() / 80) * 4;
        for (let side = -1; side <= 1; side += 2) {
            for (let leg = 0; leg < 2; leg++) {
                const baseX = cx + side * w * 0.30;
                const baseY = py + h * (0.40 + leg * 0.20);
                const reach = w * 0.6;
                const dropY = h * 0.4 + leg * 8;
                const offset = leg === 0 ? legAnim : -legAnim;
                ctx.beginPath();
                ctx.moveTo(baseX, baseY);
                // Knee
                ctx.lineTo(baseX + side * reach * 0.5, baseY - 6 + offset);
                // Foot
                ctx.lineTo(baseX + side * reach, baseY + dropY + offset);
                ctx.stroke();
            }
        }
        // Tiny standard legs at bottom (vestigial — the player still
        // walks with regular legs visually)
        ctx.fillStyle = '#0a2a0a';
        ctx.shadowBlur = 0;
        ctx.fillRect(px + w * 0.36, py + h * 0.78, w * 0.12, h * 0.22);
        ctx.fillRect(px + w * 0.52, py + h * 0.78, w * 0.12, h * 0.22);
    }

    // === STEALTH MECH ===
    else if (this.activeForm === 'stealth') {
        const flicker = 0.55 + Math.sin(Date.now() / 50) * 0.15;
        ctx.globalAlpha = 0.6 + flicker * 0.2;
        // Thin pointed helm — wraith silhouette
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 16;
        ctx.fillStyle = '#0a0a1a';
        ctx.beginPath();
        ctx.moveTo(px + w * 0.20, py + h * 0.04);
        ctx.lineTo(cx, py - 12);
        ctx.lineTo(px + w * 0.80, py + h * 0.04);
        ctx.lineTo(px + w * 0.78, py + h * 0.30);
        ctx.lineTo(px + w * 0.22, py + h * 0.30);
        ctx.closePath();
        ctx.fill();
        // Glowing single cyclops visor (horizontal slit)
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 18;
        ctx.fillRect(px + w * 0.26, py + h * 0.14, w * 0.48, 3);
        // Slim cape-like torso (tapered + shadow body)
        ctx.fillStyle = '#0a0a14';
        ctx.shadowBlur = 6;
        ctx.beginPath();
        ctx.moveTo(px + w * 0.22, py + h * 0.30);
        ctx.lineTo(px + w * 0.78, py + h * 0.30);
        ctx.lineTo(px + w * 0.62, py + h * 0.78);
        ctx.lineTo(px + w * 0.38, py + h * 0.78);
        ctx.closePath();
        ctx.fill();
        // Two ghost-crest shoulder spikes (translucent feather/wisp)
        ctx.fillStyle = def.accent;
        ctx.shadowColor = def.accent;
        ctx.shadowBlur = 14;
        ctx.globalAlpha = 0.4;
        for (const side of [-1, 1]) {
            ctx.beginPath();
            ctx.moveTo(cx + side * w * 0.30, py + h * 0.30);
            ctx.lineTo(cx + side * w * 0.50, py + h * 0.10);
            ctx.lineTo(cx + side * w * 0.40, py + h * 0.20);
            ctx.lineTo(cx + side * w * 0.30, py + h * 0.40);
            ctx.closePath();
            ctx.fill();
        }
        ctx.globalAlpha = 0.7;
        // Phase-glitch lines: random horizontal ghost tears
        ctx.strokeStyle = def.accent;
        ctx.shadowBlur = 8;
        ctx.lineWidth = 1;
        for (let i = 0; i < 3; i++) {
            const ty = py + h * (0.15 + i * 0.27) + (Date.now() / 80 + i * 30) % 16 - 8;
            ctx.beginPath();
            ctx.moveTo(px - 6, ty);
            ctx.lineTo(px + w + 6, ty + (Math.random() - 0.5) * 4);
            ctx.stroke();
        }
        // Slim legs
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#0a0a14';
        ctx.fillRect(px + w * 0.34, py + h * 0.78, w * 0.14, h * 0.22);
        ctx.fillRect(px + w * 0.52, py + h * 0.78, w * 0.14, h * 0.22);
    }

    ctx.restore();
};

// Replace the old SC.mechs.draw() (which only drew an outline glow)
// with the full sprite render plus the original UI bits (timer bars,
// after-images, heat aura). Order:
//   1. After-images (behind mech)
//   2. Mech sprite (covers default character body)
//   3. Timer bar / heat aura (above mech, on top of everything)
SC.mechs.draw = function() {
    if (!this.activeForm) return;
    const def = this.defs[this.activeForm];
    if (!def) return;
    // After-images first so they sit behind
    if (this.afterImages.length > 0) {
        ctx.save();
        for (const a of this.afterImages) {
            const alpha = (a.life / 12) * 0.45;
            ctx.globalAlpha = alpha;
            ctx.fillStyle = a.color;
            ctx.shadowColor = a.color;
            ctx.shadowBlur = 12;
            ctx.fillRect(a.x - camera.x, a.y, a.w, a.h);
        }
        ctx.restore();
    }
    // Mech sprite
    this.renderSprite();
    // Timer bar (above the mech)
    if (def.tempFormDuration || (def.cloak && def.cloakDuration)) {
        const total = def.tempFormDuration || def.cloakDuration;
        const frac = this.formTimer / total;
        const px = player.x - camera.x;
        ctx.save();
        ctx.fillStyle = 'rgba(8, 8, 16, 0.6)';
        ctx.fillRect(px - 2, player.y - 22, player.w + 4, 6);
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 5;
        ctx.fillRect(px - 2, player.y - 22, (player.w + 4) * frac, 6);
        ctx.restore();
    }
    // Berserker heat aura (above the mech)
    if (def.heatPowered) {
        const hp = (typeof SC !== 'undefined' && SC.heat) ? SC.heat.level : 0;
        if (hp > 30) {
            const px = player.x - camera.x;
            ctx.save();
            ctx.globalAlpha = (hp - 30) / 70 * 0.6;
            ctx.strokeStyle = '#ff2244';
            ctx.shadowColor = '#ff8866';
            ctx.shadowBlur = 16;
            ctx.lineWidth = 2 + (hp / 100) * 3;
            ctx.beginPath();
            ctx.arc(px + player.w/2, player.y + player.h/2,
                player.w * 0.7 + Math.sin(Date.now() / 80) * 4,
                0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }
    }
    // Tutorial overlay — shown for ~4s on form activation. Big panel
    // top-center listing the form's abilities so the kid knows what
    // each form does. Fades in/out at the edges.
    if (this.tutorialTimer > 0 && def.abilities) {
        const total = 240;
        const t = this.tutorialTimer;
        // Fade-in the first 30f, fade-out the last 30f
        let alpha = 1;
        if (t > total - 30) alpha = (total - t) / 30;
        else if (t < 30) alpha = t / 30;
        const x = canvas.width / 2 - 180;
        const y = 80;
        const w = 360;
        const h = 30 + def.abilities.length * 22 + 14;
        ctx.save();
        ctx.globalAlpha = alpha;
        // Backdrop
        ctx.fillStyle = 'rgba(8, 8, 18, 0.92)';
        ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 16;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
        ctx.shadowBlur = 0;
        // Title
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 8;
        ctx.font = 'bold 16px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(this.tutorialName || def.name, x + w/2, y + 8);
        ctx.shadowBlur = 0;
        // Each ability row
        ctx.font = 'bold 11px "Courier New", monospace';
        ctx.textAlign = 'left';
        let row = 0;
        for (const ab of def.abilities) {
            const ry = y + 30 + row * 22;
            // Key column (left, glowing color)
            ctx.fillStyle = def.color;
            ctx.shadowColor = def.color;
            ctx.shadowBlur = 6;
            ctx.fillText(ab.keys, x + 14, ry + 2);
            ctx.shadowBlur = 0;
            // What column (right, white)
            ctx.fillStyle = '#ddddee';
            ctx.font = '11px "Courier New", monospace';
            ctx.fillText('→ ' + ab.what, x + 130, ry + 2);
            ctx.font = 'bold 11px "Courier New", monospace';
            row++;
        }
        ctx.restore();
    }
};

console.log('[SC] Mech sprites loaded.');

// =====================================================================
// === BLACK HOLE GUN — full redesign of gravity weapon =================
// =====================================================================
// Replaces the existing GRAVITY CANNON (tier 30) with a proper black-
// hole weapon. Key differences from the old gravity cannon:
//   • Bullet sprite: dark sphere with swirling event-horizon ring
//   • On impact spawns an actual SINGULARITY for ~2 seconds:
//       - Persistent visible black hole orb at impact point
//       - Strong inward suction (8.0 strength)
//       - Damages everything inside per-frame (50 dmg/tick)
//       - Visible accretion-disc swirl + lensing distortion
//   • Bigger pull radius (340)
//   • Alt-fire: SUPERMASSIVE — even bigger field, longer duration,
//     pulls bosses too
// Singularity is rendered by SC.blackHole.draw() each frame.
// ---------------------------------------------------------------------

SC.blackHole = {
    holes: [],          // active singularities
    spawn(x, y, opts) {
        const o = opts || {};
        this.holes.push({
            x, y,
            radius: o.radius || 340,
            strength: o.strength || 8.0,
            damage: o.damage || 50,        // damage per tick
            life: o.life || 120,
            maxLife: o.life || 120,
            color: o.color || '#aa44ff',
            accretionColor: o.accretionColor || '#ff44dd',
            spin: 0,                        // for visual swirl
            damageInterval: 0
        });
        if (typeof spawnShockwave === 'function') spawnShockwave(x, y, 100, '#ff44dd');
        if (typeof screenShake !== 'undefined') screenShake = Math.max(screenShake, 14);
    },
    tick() {
        // Just lifecycle — life decay + spin animation. The actual
        // suction now happens in applyPull() which runs AFTER
        // updateEnemies so its position changes aren't overwritten.
        for (let i = this.holes.length - 1; i >= 0; i--) {
            const h = this.holes[i];
            h.life--;
            h.spin += 0.18;
            if (h.life <= 0) { this.holes.splice(i, 1); continue; }
        }
    },

    // === applyPull — runs AFTER updateEnemies ===
    // Pulls every enemy inside any active singularity toward its center.
    // Position-deltas + velocity-overrides + damage tick. Bosses get
    // 30% pull strength so they're affected but not trivialized.
    applyPull() {
        if (typeof enemies === 'undefined') return;
        for (const h of this.holes) {
            for (const e of enemies) {
                const ex = e.x + e.w / 2;
                const ey = e.y + e.h / 2;
                const dx = h.x - ex;
                const dy = h.y - ey;
                const d = Math.sqrt(dx*dx + dy*dy);
                if (d < h.radius && d > 4) {
                    const distScale = 1 - (d / h.radius);
                    let pull = h.strength * (0.6 + distScale * 1.6);
                    if (e.type === 'boss') pull *= 0.30;
                    // Apply BOTH position delta AND velocity override so
                    // the suction beats the enemy's AI movement.
                    e.x += (dx / d) * pull;
                    e.y += (dy / d) * pull * 0.8;
                    if (e.type !== 'boss') {
                        // Force velocity to point INWARD. This kills any
                        // outward AI motion (charge, dash, etc.).
                        e.vx = (dx / d) * pull * 0.6;
                        e.vy = (dy / d) * pull * 0.5;
                    }
                    // Damage tick — every 6 frames
                    if ((h.damageInterval || 0) % 6 === 0) {
                        const dmg = e.type === 'boss' ? Math.round(h.damage * 0.4)
                                  : e.type === 'miniboss' ? Math.round(h.damage * 0.6)
                                  : h.damage;
                        e.hp -= dmg;
                        if (typeof spawnDamageNumber === 'function') {
                            spawnDamageNumber(ex, e.y, dmg, 'aoe');
                        }
                        if (e.hp <= 0 && typeof handleEnemyKilled === 'function') {
                            const idx = enemies.indexOf(e);
                            if (idx >= 0) handleEnemyKilled(e, idx);
                        }
                    }
                }
            }
            h.damageInterval = (h.damageInterval || 0) + 1;
        }
    },
    draw() {
        if (this.holes.length === 0) return;
        ctx.save();
        for (const h of this.holes) {
            const x = h.x - camera.x;
            const y = h.y;
            const ageFrac = h.life / h.maxLife;
            // === Outer pull-distortion field (large dim glow) ===
            ctx.globalAlpha = 0.10;
            ctx.fillStyle = h.color;
            ctx.shadowColor = h.color;
            ctx.shadowBlur = 50;
            ctx.beginPath();
            ctx.arc(x, y, h.radius * 0.95, 0, Math.PI * 2);
            ctx.fill();
            // === Accretion disc — bright spinning ring ===
            ctx.shadowBlur = 16;
            for (let i = 0; i < 3; i++) {
                const ringR = 50 + i * 12;
                const wob = Math.sin(h.spin + i) * 2;
                ctx.globalAlpha = 0.6 - i * 0.14;
                ctx.strokeStyle = h.accretionColor;
                ctx.lineWidth = 4 - i;
                ctx.beginPath();
                ctx.arc(x, y, ringR + wob, 0, Math.PI * 2);
                ctx.stroke();
            }
            // === Spinning streaks — particle-style trails on the disc ===
            ctx.globalAlpha = 0.85;
            ctx.strokeStyle = '#ffffff';
            ctx.shadowColor = h.accretionColor;
            ctx.shadowBlur = 14;
            ctx.lineWidth = 2;
            for (let i = 0; i < 6; i++) {
                const ang = h.spin + i * (Math.PI / 3);
                const r1 = 40;
                const r2 = 70;
                ctx.beginPath();
                ctx.moveTo(x + Math.cos(ang) * r1, y + Math.sin(ang) * r1);
                ctx.lineTo(x + Math.cos(ang + 0.3) * r2, y + Math.sin(ang + 0.3) * r2);
                ctx.stroke();
            }
            // === Pure black core ===
            ctx.globalAlpha = 1.0;
            ctx.fillStyle = '#000000';
            ctx.shadowColor = '#000000';
            ctx.shadowBlur = 0;
            ctx.beginPath();
            ctx.arc(x, y, 28 * (0.7 + ageFrac * 0.3), 0, Math.PI * 2);
            ctx.fill();
            // === Event horizon ring (thin glowing outline) ===
            ctx.strokeStyle = h.accretionColor;
            ctx.shadowColor = h.accretionColor;
            ctx.shadowBlur = 24;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(x, y, 28 * (0.7 + ageFrac * 0.3) + 2, 0, Math.PI * 2);
            ctx.stroke();
            // === Inward streaks (matter falling in) ===
            ctx.globalAlpha = 0.65;
            ctx.strokeStyle = h.accretionColor;
            ctx.lineWidth = 1.5;
            for (let i = 0; i < 8; i++) {
                const ang = -h.spin * 1.5 + i * (Math.PI / 4);
                const r1 = 90;
                const r2 = 35;
                ctx.beginPath();
                ctx.moveTo(x + Math.cos(ang) * r1, y + Math.sin(ang) * r1);
                ctx.lineTo(x + Math.cos(ang + 0.6) * r2, y + Math.sin(ang + 0.6) * r2);
                ctx.stroke();
            }
            // === Lifetime indicator ring (subtle, top of hole) ===
            ctx.globalAlpha = 0.5;
            ctx.strokeStyle = '#ffffff';
            ctx.shadowBlur = 8;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(x, y - 50, 8, 0, Math.PI * 2 * ageFrac);
            ctx.stroke();
        }
        ctx.restore();
    }
};

// Hook tick/draw of black holes into SC's main pipeline
const _SC_tick4 = SC.tick.bind(SC);
SC.tick = function() {
    _SC_tick4();
    this.blackHole.tick();
};
const _SC_draw4 = SC.draw.bind(SC);
SC.draw = function() {
    _SC_draw4();
    this.blackHole.draw();
};

// === Re-tune the GRAVITY CANNON to spawn proper singularities ===
// Find the existing weapon entry and replace its gravityPull with a
// blackHole flag that the bullet hit logic reads.
(function rebrandGravity() {
    if (typeof WEAPONS === 'undefined') return;
    for (const w of WEAPONS) {
        if (w.name === 'GRAVITY CANNON') {
            // Rename + visual upgrade
            w.name = 'BLACK HOLE GUN';
            w.color = '#aa44ff';
            w.glow = '#ff44dd';
            w.size = 18;
            w.flavor = '🌌 Short-range singularity. Tap F: bullet stops fast and SUCKS enemies in.';
            // Remove the old gravityPull, replace with blackHole flag.
            delete w.gravityPull;
            // === SHORT RANGE — bullet stops in ~25 frames so the
            // singularity spawns relatively close to the player. The
            // bullet's life is short, the speed is moderate, and the
            // singularity does the heavy lifting via its pull field.
            w.damage = 60;            // small impact damage — pull does the work
            w.speed = 9;              // slower bullet so you SEE the black hole flying
            w.cooldown = 28;
            w.life = 24;              // SHORT range — bullet stops in 24 frames
            w.bullets = 1;
            w.spread = 0;
            w.size = 18;
            w.pierce = false;
            // === Long-lasting massive suck ===
            // The singularity sticks where the bullet lands and holds
            // for 600 frames (~10 seconds) with crushing pull strength.
            // Wide radius (380px) so it dominates a chunk of the screen.
            // Damage tick stays moderate so it's a control tool, not an
            // instant-kill button.
            w.blackHoleRound = {
                radius: 380,
                strength: 28.0,        // crushing attraction
                damage: 60,
                life: 600              // singularity lasts 600 frames (~10s)
            };
            w.altFire = {
                name: 'SUPERMASSIVE',
                heatCost: 90,
                execute(cx, cy, dir) {
                    bullets.push({
                        x: cx, y: cy,
                        vx: dir * 6, vy: -2,
                        life: 30, damage: Math.round(180 * (player.dmgMul || 1)),
                        color: '#ff44dd', glow: '#aa00ff', size: 32,
                        explosive: false,
                        // BIG black hole — wider radius, stronger pull,
                        // longer duration. Pulls bosses too at 30%.
                        blackHoleRound: {
                            radius: 560,
                            strength: 40.0,
                            damage: 110,
                            life: 720          // 12 seconds
                        },
                        pierce: false, hitEnemies: new Set(),
                        altFire: true
                    });
                    if (typeof shopMessage !== 'undefined') {
                        shopMessage = { text: '🌌 SUPERMASSIVE — bosses pulled too', timer: 120, color: '#ff44dd' };
                    }
                    if (typeof screenShake !== 'undefined') screenShake = Math.max(screenShake, 22);
                    if (typeof critFlash !== 'undefined') critFlash = Math.min(1, critFlash + 0.3);
                }
            };
            break;
        }
    }
})();

// Bullet hit hook — when a bullet flagged blackHoleRound hits an enemy
// it spawns a singularity at impact. Also detonates when the bullet
// expires from life=0 or hits a wall.
const _SC_origOnBulletHit = SC.weaponEffects.onBulletHit.bind(SC.weaponEffects);
SC.weaponEffects.onBulletHit = function(b, e, dmg) {
    dmg = _SC_origOnBulletHit(b, e, dmg);
    if (b && b.blackHoleRound && !b._spawnedHole) {
        b._spawnedHole = true;
        SC.blackHole.spawn(b.x, b.y, b.blackHoleRound);
    }
    return dmg;
};

// === Detonate on life expiration ===
// When a black hole bullet reaches the end of its (short) life without
// hitting anything, spawn the singularity wherever it stopped. Hooked
// via SC.weaponEffects.tick which already iterates bullets.
const _SC_origWeaponTick = SC.weaponEffects.tick.bind(SC.weaponEffects);
SC.weaponEffects.tick = function() {
    _SC_origWeaponTick();
    // Find black-hole-round bullets about to expire
    if (typeof bullets === 'undefined') return;
    for (const b of bullets) {
        if (!b.blackHoleRound || b._spawnedHole) continue;
        if (b.life <= 1) {
            // About to expire — detonate now
            b._spawnedHole = true;
            SC.blackHole.spawn(b.x, b.y, b.blackHoleRound);
        }
    }
};

console.log('[SC] Black Hole Gun loaded — gravity cannon is now a singularity launcher.');


// =====================================================================
// === drawPlayer wrapper — hide original body when mech is active =====
// =====================================================================
// When a mech form is active, the player IS the mech. We don't want
// the original character body to render under it (would look like a
// character standing inside a mech costume). We replace drawPlayer
// with a thin wrapper that:
//   • If mech is active → only draw the mech sprite (skip the entire
//     original drawPlayer body, all gun/arm/limb/halo logic)
//   • If no mech → run drawPlayer as normal
// The persistent ability panel is also drawn here so it's always
// visible whenever a mech is active, not just for 4 seconds.
// ---------------------------------------------------------------------

const _SC_origDrawPlayer = drawPlayer;
drawPlayer = function() {
    // No mech active → normal player render
    if (!SC.mechs || !SC.mechs.activeForm) {
        _SC_origDrawPlayer();
        return;
    }
    // Mech active — render ONLY the mech sprite. After-images first.
    const def = SC.mechs.defs[SC.mechs.activeForm];
    if (!def) {
        _SC_origDrawPlayer();
        return;
    }
    // After-images behind the mech body
    if (SC.mechs.afterImages.length > 0) {
        ctx.save();
        for (const a of SC.mechs.afterImages) {
            const alpha = (a.life / 12) * 0.45;
            ctx.globalAlpha = alpha;
            ctx.fillStyle = a.color;
            ctx.shadowColor = a.color;
            ctx.shadowBlur = 12;
            ctx.fillRect(a.x - camera.x, a.y, a.w, a.h);
        }
        ctx.restore();
    }
    // The mech sprite IS the character now
    SC.mechs.renderSprite();
    // === Pacific Rim — bars anchor to the SPRITE top ===
    // Sprite is drawn at def.spriteScale × hitbox size with feet at the
    // hitbox bottom. The HUD bars (timer, energy) need to sit ABOVE
    // the visible mech, not above the small invisible hitbox. So we
    // compute the sprite top each frame.
    const _spriteScale = def.spriteScale || 1.3;
    const _FOOT_LIFT = 6;
    const _spriteW = player.w * _spriteScale;
    const _spriteX = (player.x + player.w / 2) - (_spriteW / 2) - camera.x;
    const _spriteTopY = (player.y + player.h) - (player.h * _spriteScale) - _FOOT_LIFT;
    // Time bar above mech (if time-limited)
    if (def.tempFormDuration || (def.cloak && def.cloakDuration)) {
        const total = def.tempFormDuration || def.cloakDuration;
        const frac = SC.mechs.formTimer / total;
        ctx.save();
        ctx.fillStyle = 'rgba(8, 8, 16, 0.6)';
        ctx.fillRect(_spriteX - 2, _spriteTopY - 22, _spriteW + 4, 6);
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 5;
        ctx.fillRect(_spriteX - 2, _spriteTopY - 22, (_spriteW + 4) * frac, 6);
        ctx.restore();
    }
    // Energy bar (titan / stealth — shows live energy)
    if (SC.mechs.energy !== null && SC.mechs.energyMax) {
        const frac = SC.mechs.energy / SC.mechs.energyMax;
        ctx.save();
        ctx.fillStyle = 'rgba(8, 8, 16, 0.7)';
        ctx.fillRect(_spriteX - 2, _spriteTopY - 22, _spriteW + 4, 6);
        const energyCol = frac > 0.5 ? def.color : (frac > 0.25 ? '#ffaa44' : '#ff4422');
        ctx.fillStyle = energyCol;
        ctx.shadowColor = energyCol;
        ctx.shadowBlur = 5;
        ctx.fillRect(_spriteX - 2, _spriteTopY - 22, (_spriteW + 4) * frac, 6);
        ctx.restore();
    }
    // Berserker heat aura
    if (def.heatPowered) {
        const hp = (typeof SC !== 'undefined' && SC.heat) ? SC.heat.level : 0;
        if (hp > 30) {
            const px = player.x - camera.x;
            ctx.save();
            ctx.globalAlpha = (hp - 30) / 70 * 0.6;
            ctx.strokeStyle = '#ff2244';
            ctx.shadowColor = '#ff8866';
            ctx.shadowBlur = 16;
            ctx.lineWidth = 2 + (hp / 100) * 3;
            ctx.beginPath();
            ctx.arc(px + player.w/2, player.y + player.h/2,
                player.w * 0.7 + Math.sin(Date.now() / 80) * 4,
                0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }
    }
};

// === Persistent ability panel — visible the WHOLE time mech is active ===
// Replaces the 4-second tutorial overlay. Smaller, sits top-center,
// shows all abilities + their keys. Stays up until the mech form ends.
// The activation flash (big banner) still plays on first activate.
SC.mechs.drawAbilityPanel = function() {
    if (!this.activeForm) return;
    const def = this.defs[this.activeForm];
    if (!def || !def.abilities) return;
    const x = canvas.width / 2 - 170;
    const y = 80;
    const w = 340;
    const h = 26 + def.abilities.length * 18 + 8;
    ctx.save();
    // Backdrop
    ctx.fillStyle = 'rgba(8, 8, 18, 0.78)';
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = def.color;
    ctx.shadowColor = def.color;
    ctx.shadowBlur = 8;
    ctx.lineWidth = 1.5;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
    ctx.shadowBlur = 0;
    // Title
    ctx.fillStyle = def.color;
    ctx.shadowColor = def.color;
    ctx.shadowBlur = 6;
    ctx.font = 'bold 13px "Courier New", monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(def.name, x + w / 2, y + 6);
    ctx.shadowBlur = 0;
    // Each ability row
    ctx.font = 'bold 10px "Courier New", monospace';
    ctx.textAlign = 'left';
    let row = 0;
    for (const ab of def.abilities) {
        const ry = y + 26 + row * 18;
        // Key column (glowing colored)
        ctx.fillStyle = def.color;
        ctx.shadowColor = def.color;
        ctx.shadowBlur = 5;
        ctx.fillText(ab.keys, x + 12, ry + 1);
        ctx.shadowBlur = 0;
        // What column (white)
        ctx.fillStyle = '#ddddee';
        ctx.font = '10px "Courier New", monospace';
        ctx.fillText('→ ' + ab.what, x + 120, ry + 1);
        ctx.font = 'bold 10px "Courier New", monospace';
        row++;
    }
    ctx.restore();
};

// Hook the panel into SC.draw so it always renders while mech is active.
const _SC_draw5 = SC.draw.bind(SC);
SC.draw = function() {
    _SC_draw5();
    if (this.mechs && this.mechs.activeForm) {
        this.mechs.drawAbilityPanel();
    }
};

// Also kill the old 4-second tutorial overlay code path inside
// SC.mechs.draw — we want a clean "panel always visible" approach.
// The tutorialTimer is still set at activation but we just never read
// it for the persistent panel; the activation flash banner via
// shopMessage still fires from activate(). Cleanest way to silence
// the old tutorial: stub it out in SC.mechs.draw.
const _SC_origMechsDraw = SC.mechs.draw.bind(SC.mechs);
SC.mechs.draw = function() {
    // Skip the per-mech draw entirely — drawPlayer wrapper now handles
    // sprite + after-images + time bar + heat aura. The persistent
    // ability panel is drawn from SC.draw above.
    // The OLD draw is preserved (in _SC_origMechsDraw) in case I need
    // to rollback, but it's never called in normal flow.
};

// Also re-emit the tagline as a one-shot top banner on activation —
// big, brief, uses the existing shopMessage system so it pulses.
const _SC_origActivate = SC.mechs.activate.bind(SC.mechs);
SC.mechs.activate = function(formId) {
    _SC_origActivate(formId);
    const def = this.defs[formId];
    if (def && typeof shopMessage !== 'undefined') {
        // 3-second activation banner — short and big
        shopMessage = { text: def.tagline, timer: 180, color: def.color };
    }
};

console.log('[SC] Mech persistent ability panel + drawPlayer override loaded.');


// =====================================================================
// === Mech rebalance hooks ============================================
// =====================================================================
// Wire titan kill-energy and stealth first-shot bonus into the existing
// kill / shoot paths via thin wrappers. Removing this block reverts.
// ---------------------------------------------------------------------

// Titan: each kill grants energy → keeps the form alive longer in heavy
// combat. This makes the form feel rewarding for aggressive play and
// punishing for hiding (energy just runs out).
const _SC_origHandleKilled = handleEnemyKilled;
handleEnemyKilled = function(e, j) {
    _SC_origHandleKilled(e, j);
    if (typeof SC !== 'undefined' && SC.mechs) SC.mechs.onEnemyKilled();
};

// Stealth: first shot after activation deals ×3 damage. Wired by
// reading SC.mechs.firstShotPending in the bullet damage path.
const _SC_origOnAttack = SC.onPlayerAttack.bind(SC);
SC.onPlayerAttack = function(kind) {
    _SC_origOnAttack(kind);
    if (this.mechs && this.mechs.activeForm === 'stealth' && this.mechs.firstShotPending) {
        if (typeof shopMessage !== 'undefined') {
            shopMessage = { text: '🌑 BACKSTAB — first shot ×3', timer: 80, color: '#aaaaff' };
        }
    }
};

// Patch the bullet outgoing-damage hook to apply stealth first-shot
// multiplier + spider spiderling spawn + ninja melee bonus.
const _SC_origOutgoing = SC.outgoingDmgMul.bind(SC);
SC.outgoingDmgMul = function() {
    let m = _SC_origOutgoing();
    if (this.mechs && this.mechs.activeForm) {
        const def = this.mechs.defs[this.mechs.activeForm];
        // Stealth first-shot ×3
        if (def && def.firstShotMul && this.mechs.firstShotPending) {
            m *= def.firstShotMul;
            this.mechs.firstShotPending = false;
            // Burn cloak energy on the attack
            if (def.energyOnAttack && this.mechs.energy !== null) {
                this.mechs.energy = Math.max(0, this.mechs.energy + def.energyOnAttack);
            }
        }
        // Spider — spiderlings handled in shoot path; nothing here
    }
    return m;
};

// Spider spiderling spawn — fire a small homing pellet alongside each
// shot. Hooked via SC.onPlayerAttack so we don't have to dig back into
// the shoot path.
const _SC_origAttack2 = SC.onPlayerAttack.bind(SC);
SC.onPlayerAttack = function(kind) {
    _SC_origAttack2(kind);
    if (kind !== 'shoot') return;
    if (!this.mechs || this.mechs.activeForm !== 'spider') return;
    // Add a small homing pellet from the player
    if (typeof bullets === 'undefined' || typeof player === 'undefined') return;
    const cx = player.x + player.w / 2;
    const cy = player.y + player.h / 2;
    const dir = player.facing || 1;
    bullets.push({
        x: cx + dir * 12, y: cy + 6,
        vx: dir * 8 + (Math.random() - 0.5) * 2,
        vy: -2 + Math.random(),
        life: 200,
        damage: Math.max(8, Math.round((player.bulletDamage + 18) * 0.3 * (player.dmgMul || 1))),
        color: '#88ff88', glow: '#44dd44', size: 4,
        pierce: false, hitEnemies: new Set(),
        drone: true,             // reuse drone homing logic
        spider: true
    });
};

// Apply ninja melee bonus to the executeMelee path. We can do this by
// wrapping executeMelee — at top of function we bump player.dmgMul,
// at end we restore. But easier: read the bonus in the existing
// melee dmg multiplier (player.dmgMul is already used). Instead, we
// just bump the snapshot-derived dmgMul slightly during ninja.
// The simpler path: set a per-frame bonus on player that the melee
// path multiplies in. We use player._scNinjaMeleeBonus.
const _SC_mechTick = SC.mechs.tick.bind(SC.mechs);
SC.mechs.tick = function() {
    _SC_mechTick();
    if (!this.activeForm) {
        if (typeof player !== 'undefined') player._scNinjaMeleeBonus = 1;
        return;
    }
    const def = this.defs[this.activeForm];
    if (typeof player !== 'undefined') {
        player._scNinjaMeleeBonus = (def && def.meleeBonus) || 1;
    }
};

console.log('[SC] Mech rebalance hooks loaded.');


// ============================================================================
// ===== WISHLIST FEATURE PACK (Jun 7 2026 v2) =====
// Self-contained module that bolts on the 9 features the kid wanted:
//   1. Leaderboard (per-stage best time / HP)
//   2. Random arena decorations (per-stage props, low risk)
//   3. Mini-boss antechambers (wave breaks between rush rounds)
//   4. Cosmetic skins (alt-color characters, RC-priced)
//   5. New character — PRINCE (Mech King's son)
//   6. Weapon mods (slot 1-2 mods per weapon)
//   7. New mech form — CONVOY TRUCK (Optimus-style transform)
//   8. Death replay slow-mo
//   9. Local co-op (P2 companion with WASD+QE)
//
// Plus 3 new boss transformation FORMS — DRAGON, KAIJU, MONSTER —
// available as alt rush-transformations in NG+ loop 2+.
//
// Wired via wrapping (same pattern as SC.*) so the original game loop
// is unmodified. Each subsystem can be toggled via WL.flags.
// ============================================================================
const WL = (function() {

    // ====== FEATURE FLAGS ======
    const flags = {
        leaderboard: true,
        decor: true,
        miniBoss: true,
        skins: true,
        newChar: true,
        mods: true,
        convoyMech: true,
        deathReplay: true,
        coop: true,
        bossForms: true
    };

    // ============================================================
    // 1. LEADERBOARD — per-stage best time/HP, persisted localStorage
    // ============================================================
    const leaderboard = {
        STORAGE_KEY: 'neonRush.leaderboard.v1',
        // Slots: 0..7 stages, 8 = boss rush, 9 = void god
        bestTimes: new Array(10).fill(null),  // ms or null
        bestHpPct: new Array(10).fill(null),  // 0..1 fraction of maxHp at clear
        runStart: 0,
        currentStageStart: 0,
        bossRushStart: 0,

        init() {
            try {
                const raw = localStorage.getItem(this.STORAGE_KEY);
                if (!raw) return;
                const obj = JSON.parse(raw);
                if (Array.isArray(obj.times)) {
                    for (let i = 0; i < Math.min(10, obj.times.length); i++) {
                        if (typeof obj.times[i] === 'number') this.bestTimes[i] = obj.times[i];
                    }
                }
                if (Array.isArray(obj.hp)) {
                    for (let i = 0; i < Math.min(10, obj.hp.length); i++) {
                        if (typeof obj.hp[i] === 'number') this.bestHpPct[i] = obj.hp[i];
                    }
                }
            } catch (e) {}
        },
        save() {
            try {
                localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
                    times: this.bestTimes,
                    hp: this.bestHpPct
                }));
            } catch (e) {}
        },
        startStage() {
            this.currentStageStart = performance.now();
        },
        onStageClear(stageIdx) {
            if (!WL.flags.leaderboard) return;
            const elapsed = performance.now() - this.currentStageStart;
            const hpPct = (typeof player !== 'undefined' && player.maxHp)
                ? Math.max(0, player.hp) / player.maxHp
                : 1;
            if (this.bestTimes[stageIdx] === null || elapsed < this.bestTimes[stageIdx]) {
                this.bestTimes[stageIdx] = elapsed;
            }
            if (this.bestHpPct[stageIdx] === null || hpPct > this.bestHpPct[stageIdx]) {
                this.bestHpPct[stageIdx] = hpPct;
            }
            this.save();
        },
        startBossRush() {
            this.bossRushStart = performance.now();
        },
        onBossRushClear() {
            if (!WL.flags.leaderboard) return;
            const elapsed = performance.now() - this.bossRushStart;
            const hpPct = (typeof player !== 'undefined' && player.maxHp)
                ? Math.max(0, player.hp) / player.maxHp
                : 1;
            if (this.bestTimes[8] === null || elapsed < this.bestTimes[8]) {
                this.bestTimes[8] = elapsed;
            }
            if (this.bestHpPct[8] === null || hpPct > this.bestHpPct[8]) {
                this.bestHpPct[8] = hpPct;
            }
            this.save();
        },
        formatTime(ms) {
            if (ms === null || ms === undefined) return '—:——';
            const totalSec = ms / 1000;
            const m = Math.floor(totalSec / 60);
            const s = Math.floor(totalSec % 60);
            const cs = Math.floor((totalSec * 100) % 100);
            return `${m}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
        },
        // Draw best-time/HP banner on stage clear screen.
        drawForStage(stageIdx) {
            if (!WL.flags.leaderboard) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            const t = this.bestTimes[stageIdx];
            const h = this.bestHpPct[stageIdx];
            const cx = canvas.width / 2;
            const yBase = canvas.height / 2 + 175;
            ctx.save();
            ctx.fillStyle = '#ffd744';
            ctx.shadowColor = '#ff8800';
            ctx.shadowBlur = 8;
            ctx.font = 'bold 14px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('━━ LEADERBOARD ━━', cx, yBase);
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#aaeeff';
            ctx.font = '12px Courier New';
            ctx.fillText(`BEST TIME: ${this.formatTime(t)}`, cx - 90, yBase + 22);
            ctx.fillText(`BEST HP%: ${h !== null ? Math.floor(h * 100) + '%' : '—'}`, cx + 90, yBase + 22);
            ctx.restore();
        },
        // Full leaderboard panel — drawn on game over screen
        drawFullPanel() {
            if (!WL.flags.leaderboard) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            const cx = canvas.width / 2;
            const yBase = canvas.height / 2 + 140;
            ctx.save();
            ctx.fillStyle = 'rgba(20, 10, 30, 0.85)';
            ctx.fillRect(cx - 240, yBase - 20, 480, 200);
            ctx.strokeStyle = '#ffd744';
            ctx.lineWidth = 2;
            ctx.strokeRect(cx - 240, yBase - 20, 480, 200);
            ctx.fillStyle = '#ffd744';
            ctx.shadowColor = '#ff8800';
            ctx.shadowBlur = 12;
            ctx.font = 'bold 16px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('━━ LEADERBOARD ━━', cx, yBase);
            ctx.shadowBlur = 0;
            const stageNames = [
                'GUARD-1', 'SKYHAMMER', 'INFERNO-X', 'RAVAGER',
                'CRYO-LORD', 'NULLIFIER', 'OMEGA-PRIME', 'TITAN-LORD',
                'BOSS RUSH'
            ];
            ctx.font = '11px Courier New';
            ctx.textAlign = 'left';
            for (let i = 0; i < 9; i++) {
                const t = this.bestTimes[i];
                const h = this.bestHpPct[i];
                const yLine = yBase + 22 + i * 16;
                ctx.fillStyle = (t !== null) ? '#aaeeff' : '#555';
                ctx.fillText(`${(i + 1)}.${stageNames[i].padEnd(13)} ${this.formatTime(t)}  HP:${h !== null ? Math.floor(h * 100) + '%' : '—'}`, cx - 220, yLine);
            }
            ctx.restore();
        }
    };

    // ============================================================
    // 2. RANDOM ARENA DECORATIONS — purely visual props per stage
    // ============================================================
    const decor = {
        items: [],           // { x, y, kind, color, t }
        lastStageBuilt: -1,
        // Each stage gets a different palette of decorative props
        themes: {
            0: { kinds: ['crate', 'pipe', 'panel'],   colors: ['#88ff88', '#44aa44', '#226622'] },
            1: { kinds: ['cloud', 'antenna', 'beacon'], colors: ['#88ccff', '#aaeeff', '#ddeeff'] },
            2: { kinds: ['ember', 'pipe', 'fire-pod'], colors: ['#ff6622', '#ffaa44', '#ffdd66'] },
            3: { kinds: ['crate', 'workbench', 'panel'], colors: ['#22ff44', '#88ff88', '#44dd66'] },
            4: { kinds: ['crystal', 'icicle', 'shard'], colors: ['#88ccff', '#aaeeff', '#ffffff'] },
            5: { kinds: ['rune', 'sigil', 'orb'], colors: ['#aa00ff', '#ff66ff', '#ffaaff'] },
            6: { kinds: ['banner', 'crown', 'orb'], colors: ['#ffaa00', '#ffd744', '#ffffff'] },
            7: { kinds: ['satellite', 'beacon', 'panel'], colors: ['#66ffff', '#aaffff', '#ffffff'] }
        },
        spawn(stageIdx) {
            if (!WL.flags.decor) return;
            this.items = [];
            const theme = this.themes[stageIdx] || this.themes[0];
            const count = 8 + Math.floor(Math.random() * 6);   // 8-13 props
            for (let i = 0; i < count; i++) {
                const x = 200 + Math.random() * 4000;
                const y = 460 + Math.random() * 80;            // ground level
                const kind = theme.kinds[Math.floor(Math.random() * theme.kinds.length)];
                const color = theme.colors[Math.floor(Math.random() * theme.colors.length)];
                this.items.push({
                    x, y, kind, color,
                    seed: Math.random() * Math.PI * 2,
                    size: 20 + Math.random() * 20
                });
            }
            this.lastStageBuilt = stageIdx;
        },
        ensure() {
            // Re-spawn if stage changed since last build
            if (typeof currentStage !== 'undefined' && currentStage !== this.lastStageBuilt) {
                this.spawn(currentStage);
            }
        },
        draw() {
            if (!WL.flags.decor) return;
            if (typeof ctx === 'undefined' || typeof camera === 'undefined') return;
            this.ensure();
            const t = performance.now() * 0.002;
            for (const it of this.items) {
                const sx = it.x - camera.x;
                if (sx < -100 || sx > 1100) continue;
                const sy = it.y - camera.y;
                ctx.save();
                ctx.globalAlpha = 0.85;
                this.drawProp(it, sx, sy, t);
                ctx.restore();
            }
        },
        drawProp(it, sx, sy, t) {
            ctx.fillStyle = it.color;
            ctx.shadowColor = it.color;
            ctx.shadowBlur = 6;
            switch (it.kind) {
                case 'crate':
                    ctx.fillRect(sx - 12, sy + 70 - it.size, 24, it.size);
                    ctx.strokeStyle = '#000'; ctx.lineWidth = 2;
                    ctx.strokeRect(sx - 12, sy + 70 - it.size, 24, it.size);
                    ctx.fillStyle = '#000';
                    ctx.fillRect(sx - 8, sy + 70 - it.size + 6, 16, 4);
                    break;
                case 'pipe':
                    ctx.fillRect(sx - 6, sy + 70 - it.size * 1.4, 12, it.size * 1.4);
                    ctx.fillStyle = '#000';
                    ctx.fillRect(sx - 7, sy + 70 - it.size * 1.4, 14, 4);
                    break;
                case 'panel':
                    ctx.fillRect(sx - 18, sy + 60 - it.size * 0.8, 36, it.size * 0.8);
                    ctx.fillStyle = '#000';
                    ctx.fillRect(sx - 4, sy + 60 - it.size * 0.4, 8, 4);
                    break;
                case 'cloud':
                    ctx.globalAlpha = 0.4;
                    ctx.beginPath();
                    ctx.arc(sx, sy - 80 + Math.sin(t + it.seed) * 6, it.size, 0, Math.PI * 2);
                    ctx.arc(sx + 18, sy - 80, it.size * 0.7, 0, Math.PI * 2);
                    ctx.arc(sx - 18, sy - 80, it.size * 0.7, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                case 'antenna':
                    ctx.fillRect(sx - 1, sy + 70 - it.size * 1.6, 2, it.size * 1.6);
                    ctx.beginPath();
                    ctx.arc(sx, sy + 70 - it.size * 1.6, 4, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                case 'beacon':
                    ctx.fillRect(sx - 4, sy + 70 - it.size, 8, it.size);
                    const pulse = 0.4 + Math.sin(t * 3 + it.seed) * 0.4;
                    ctx.globalAlpha = 0.3 + pulse * 0.4;
                    ctx.beginPath();
                    ctx.arc(sx, sy + 70 - it.size, 12, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                case 'ember':
                    ctx.beginPath();
                    ctx.arc(sx, sy + 60, 6 + Math.sin(t + it.seed) * 2, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#ffaa44';
                    ctx.beginPath();
                    ctx.arc(sx, sy + 60, 3, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                case 'fire-pod':
                    ctx.fillRect(sx - 8, sy + 70 - it.size, 16, it.size);
                    ctx.fillStyle = '#ffaa00';
                    const flame = Math.sin(t * 5 + it.seed);
                    ctx.beginPath();
                    ctx.moveTo(sx - 4, sy + 70 - it.size);
                    ctx.lineTo(sx, sy + 70 - it.size - 14 - flame * 3);
                    ctx.lineTo(sx + 4, sy + 70 - it.size);
                    ctx.fill();
                    break;
                case 'workbench':
                    ctx.fillRect(sx - 16, sy + 60, 32, 14);
                    ctx.fillRect(sx - 14, sy + 60, 4, 14);
                    ctx.fillRect(sx + 10, sy + 60, 4, 14);
                    break;
                case 'crystal':
                    ctx.beginPath();
                    ctx.moveTo(sx, sy + 70 - it.size);
                    ctx.lineTo(sx + 8, sy + 60);
                    ctx.lineTo(sx, sy + 70);
                    ctx.lineTo(sx - 8, sy + 60);
                    ctx.closePath();
                    ctx.fill();
                    break;
                case 'icicle':
                    ctx.beginPath();
                    ctx.moveTo(sx - 6, sy - 100);
                    ctx.lineTo(sx + 6, sy - 100);
                    ctx.lineTo(sx, sy - 100 + it.size);
                    ctx.closePath();
                    ctx.fill();
                    break;
                case 'shard':
                    ctx.save();
                    ctx.translate(sx, sy + 60);
                    ctx.rotate(it.seed);
                    ctx.fillRect(-3, -it.size / 2, 6, it.size);
                    ctx.restore();
                    break;
                case 'rune':
                    ctx.beginPath();
                    ctx.arc(sx, sy + 60, it.size * 0.4, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.font = `${it.size * 0.6}px Courier New`;
                    ctx.fillText('ᚱ', sx - 6, sy + 65);
                    break;
                case 'sigil':
                    ctx.strokeStyle = it.color; ctx.lineWidth = 2;
                    ctx.beginPath();
                    for (let s = 0; s < 5; s++) {
                        const ang = (Math.PI * 2 / 5) * s - Math.PI / 2;
                        const px = sx + Math.cos(ang) * (it.size * 0.4);
                        const py = sy + 50 + Math.sin(ang) * (it.size * 0.4);
                        if (s === 0) ctx.moveTo(px, py);
                        else ctx.lineTo(px, py);
                    }
                    ctx.closePath();
                    ctx.stroke();
                    break;
                case 'orb':
                    const orbPulse = 0.6 + Math.sin(t * 2 + it.seed) * 0.3;
                    ctx.globalAlpha = orbPulse;
                    ctx.beginPath();
                    ctx.arc(sx, sy + 50 + Math.sin(t + it.seed) * 6, it.size * 0.3, 0, Math.PI * 2);
                    ctx.fill();
                    break;
                case 'banner':
                    ctx.fillRect(sx - 1, sy - 100, 2, 100);
                    ctx.fillStyle = it.color;
                    const wave = Math.sin(t * 2 + it.seed) * 2;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy - 100);
                    ctx.lineTo(sx + 24 + wave, sy - 90);
                    ctx.lineTo(sx + 22 + wave, sy - 70);
                    ctx.lineTo(sx, sy - 70);
                    ctx.closePath();
                    ctx.fill();
                    break;
                case 'crown':
                    ctx.fillRect(sx - 10, sy + 64, 20, 6);
                    for (let s = 0; s < 5; s++) {
                        ctx.beginPath();
                        ctx.moveTo(sx - 10 + s * 5, sy + 64);
                        ctx.lineTo(sx - 10 + s * 5 + 2.5, sy + 56);
                        ctx.lineTo(sx - 10 + s * 5 + 5, sy + 64);
                        ctx.fill();
                    }
                    break;
                case 'satellite':
                    ctx.fillRect(sx - 6, sy - 80, 12, 8);
                    ctx.fillRect(sx - 14, sy - 78, 6, 4);
                    ctx.fillRect(sx + 8, sy - 78, 6, 4);
                    break;
            }
            ctx.shadowBlur = 0;
        }
    };

    // ============================================================
    // 3. MINI-BOSS ANTECHAMBERS (rush mode wave breaks)
    // ============================================================
    const miniBoss = {
        active: false,
        waveIdx: 0,
        spawnedThisWave: 0,
        nextRushIdx: 0,
        // Wave compositions for between-rush pacing breaks
        WAVES: [
            { count: 4, type: 'mech', name: 'TURRET WAVE' },
            { count: 5, type: 'sniper', name: 'SNIPER WAVE' },
            { count: 6, type: 'heavy', name: 'HEAVY WAVE' }
        ],
        // Trigger between rush bosses (called from advanceBossRush). Spawns
        // a wave of 4-6 mid-tier enemies to fight before the next boss.
        trigger(nextRushIdx) {
            if (!WL.flags.miniBoss) return false;
            if (this.active) return false;
            // Only trigger every other rush round (idx 1, 3, 5, 7) to keep pacing
            if (nextRushIdx % 2 !== 1) return false;
            this.active = true;
            this.nextRushIdx = nextRushIdx;
            this.waveIdx = Math.floor(Math.random() * this.WAVES.length);
            const wave = this.WAVES[this.waveIdx];
            this.spawnedThisWave = wave.count;
            // Spawn the wave
            for (let i = 0; i < wave.count; i++) {
                const px = 600 + i * 220;
                const py = 380;
                const enemy = this.makeEnemy(wave.type, px, py);
                if (enemy && typeof enemies !== 'undefined') {
                    enemies.push(enemy);
                }
            }
            // Banner
            if (typeof shopMessage !== 'undefined') {
                shopMessage = {
                    text: `⚠ ${wave.name} — clear before the next boss ⚠`,
                    timer: 200,
                    color: '#ffaa44'
                };
            }
            if (typeof screenShake !== 'undefined') screenShake = 12;
            if (typeof audio !== 'undefined' && audio.play) audio.play('warning');
            return true;
        },
        makeEnemy(type, x, y) {
            switch (type) {
                case 'mech':
                    return {
                        type: 'mech', x, y, w: 60, h: 60,
                        hp: 350, maxHp: 350, shootTimer: 90,
                        attackPhase: 0, walkPhase: 0,
                        vx: 0, vy: 0, facing: -1, onGround: false,
                        baseY: y, color: '#ff6644'
                    };
                case 'sniper':
                    return {
                        type: 'sniper', x, y, w: 38, h: 50,
                        hp: 90, maxHp: 90, shootTimer: 120,
                        chargeTimer: 0, charging: false,
                        vx: 0, vy: 0, facing: -1, onGround: false,
                        baseY: y, color: '#aa00ff'
                    };
                case 'heavy':
                    return {
                        type: 'heavy', x, y, w: 50, h: 56,
                        hp: 200, maxHp: 200, shootTimer: 90,
                        vx: 1.5, vy: 0, dir: -1,
                        patrolStart: x - 200, patrolEnd: x + 200,
                        color: '#ff3300', onGround: false, baseY: y
                    };
                default: return null;
            }
        },
        // Called every frame during rush mode to detect wave clear
        update() {
            if (!this.active) return;
            if (typeof enemies === 'undefined') return;
            // Wave is clear when no non-boss enemies remain
            const nonBossLeft = enemies.filter(e => e && e.type !== 'boss' && e.hp > 0).length;
            if (nonBossLeft === 0) {
                // Wave done — advance to next boss
                this.active = false;
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = {
                        text: '✓ WAVE CLEAR — NEXT BOSS INCOMING',
                        timer: 100,
                        color: '#88ff88'
                    };
                }
                if (typeof deferFrames === 'function' && typeof spawnBossRushBoss === 'function') {
                    const idx = this.nextRushIdx;
                    deferFrames(60, () => {
                        if (typeof bossRush !== 'undefined' && bossRush && bossRush.active) {
                            if (typeof startBossRushCutscene === 'function') {
                                startBossRushCutscene(idx);
                            } else {
                                spawnBossRushBoss(idx);
                            }
                        }
                    });
                }
            }
        }
    };

    // ============================================================
    // 4. COSMETIC SKINS — alt-color characters, RC-priced
    // ============================================================
    const skins = {
        STORAGE_KEY: 'neonRush.skins.v1',
        list: [
            { id: 'gold',     name: 'NEON GOLD',    rcCost: 5,  color: '#ffd744', accent: '#ffaa00' },
            { id: 'crimson',  name: 'CRIMSON',      rcCost: 8,  color: '#ff2244', accent: '#ff8866' },
            { id: 'emerald',  name: 'EMERALD',      rcCost: 10, color: '#22ff88', accent: '#88ffaa' },
            { id: 'void',     name: 'VOID PURPLE',  rcCost: 15, color: '#aa00ff', accent: '#ff44ff' },
            { id: 'ghost',    name: 'GHOST WHITE',  rcCost: 20, color: '#ffffff', accent: '#88ddff' },
            { id: 'rainbow',  name: 'RAINBOW',      rcCost: 30, color: '#rainbow', accent: '#rainbow' }
        ],
        unlocked: {},        // { skinId: true }
        selected: null,      // skin id or null = default character color
        menuOpen: false,
        cursorIdx: 0,
        init() {
            try {
                const raw = localStorage.getItem(this.STORAGE_KEY);
                if (!raw) return;
                const obj = JSON.parse(raw);
                if (obj.unlocked) this.unlocked = obj.unlocked;
                if (typeof obj.selected === 'string' || obj.selected === null) {
                    this.selected = obj.selected;
                }
            } catch (e) {}
        },
        save() {
            try {
                localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
                    unlocked: this.unlocked,
                    selected: this.selected
                }));
            } catch (e) {}
        },
        // Return the active skin override, or null if no skin selected
        active() {
            if (!WL.flags.skins || !this.selected) return null;
            const s = this.list.find(x => x.id === this.selected);
            if (!s || !this.unlocked[s.id]) return null;
            return s;
        },
        // Apply skin colors to player (called after applyCharacter)
        apply() {
            const s = this.active();
            if (!s) return;
            if (typeof player === 'undefined') return;
            // Special: rainbow cycles through colors
            if (s.color === '#rainbow') {
                const t = performance.now() * 0.002;
                const hue = (Math.sin(t) * 0.5 + 0.5) * 360;
                player.charColor = `hsl(${hue}, 100%, 60%)`;
                player.charAccent = `hsl(${(hue + 120) % 360}, 100%, 75%)`;
            } else {
                player.charColor = s.color;
                player.charAccent = s.accent;
            }
        },
        toggleMenu() {
            this.menuOpen = !this.menuOpen;
        },
        // Process input for the menu (called from main keydown when menu open)
        handleKey(code) {
            if (!this.menuOpen) return false;
            if (code === 'Escape' || code === 'KeyK') {
                this.menuOpen = false;
                return true;
            }
            if (code === 'ArrowUp' || code === 'KeyW') {
                this.cursorIdx = (this.cursorIdx - 1 + this.list.length + 1) % (this.list.length + 1);
                return true;
            }
            if (code === 'ArrowDown' || code === 'KeyS') {
                this.cursorIdx = (this.cursorIdx + 1) % (this.list.length + 1);
                return true;
            }
            if (code === 'Enter' || code === 'Space' || code === 'KeyE') {
                this.activate();
                return true;
            }
            return false;
        },
        activate() {
            // Cursor 0 = "DEFAULT" (clear skin), 1..N = skins
            if (this.cursorIdx === 0) {
                this.selected = null;
                this.save();
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: 'Skin reset to default', timer: 80, color: '#88ddff' };
                }
                return;
            }
            const skin = this.list[this.cursorIdx - 1];
            if (!skin) return;
            if (!this.unlocked[skin.id]) {
                // Try to buy with RC
                if (typeof player === 'undefined') return;
                if (player.robotCoins < skin.rcCost) {
                    if (typeof shopMessage !== 'undefined') {
                        shopMessage = { text: `Need ${skin.rcCost} RC (have ${player.robotCoins})`, timer: 90, color: '#ff6644' };
                    }
                    return;
                }
                player.robotCoins -= skin.rcCost;
                this.unlocked[skin.id] = true;
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: `★ SKIN UNLOCKED: ${skin.name} ★`, timer: 180, color: skin.color === '#rainbow' ? '#ff44dd' : skin.color };
                }
                if (typeof spawnParticles === 'function' && typeof player !== 'undefined') {
                    spawnParticles(player.x + player.w/2, player.y, skin.color === '#rainbow' ? '#ff44dd' : skin.color, 30, 5);
                }
                if (typeof audio !== 'undefined' && audio.play) audio.play('coin');
            }
            this.selected = skin.id;
            this.save();
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: `★ SKIN EQUIPPED: ${skin.name} ★`, timer: 120, color: skin.color === '#rainbow' ? '#ff44dd' : skin.color };
            }
        },
        draw() {
            if (!this.menuOpen) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            const cw = canvas.width, ch = canvas.height;
            ctx.save();
            // Backdrop
            ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
            ctx.fillRect(0, 0, cw, ch);
            // Panel
            const pw = 480, ph = 380;
            const px = (cw - pw) / 2, py = (ch - ph) / 2;
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(px, py, pw, ph);
            ctx.strokeStyle = '#ff44dd';
            ctx.lineWidth = 3;
            ctx.shadowColor = '#ff44dd';
            ctx.shadowBlur = 16;
            ctx.strokeRect(px, py, pw, ph);
            ctx.shadowBlur = 0;
            // Title
            ctx.fillStyle = '#ffd744';
            ctx.font = 'bold 22px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('★ COSMETIC SKINS ★', cw / 2, py + 30);
            ctx.font = '11px Courier New';
            ctx.fillStyle = '#aaa';
            const rc = (typeof player !== 'undefined' && player.robotCoins) || 0;
            ctx.fillText(`Robot Coins: ${rc}  •  Up/Down: navigate  •  Enter: select  •  K: close`, cw / 2, py + 50);
            // List entries (Default first, then skins)
            ctx.textAlign = 'left';
            const entries = [{ id: null, name: 'DEFAULT (character color)', rcCost: 0, owned: true }]
                .concat(this.list.map(s => ({
                    ...s,
                    owned: !!this.unlocked[s.id]
                })));
            for (let i = 0; i < entries.length; i++) {
                const e = entries[i];
                const yLine = py + 80 + i * 36;
                const isSel = (i === this.cursorIdx);
                const isActive = (e.id === this.selected) || (e.id === null && this.selected === null);
                if (isSel) {
                    ctx.fillStyle = 'rgba(255, 215, 68, 0.15)';
                    ctx.fillRect(px + 16, yLine - 4, pw - 32, 32);
                    ctx.strokeStyle = '#ffd744';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(px + 16, yLine - 4, pw - 32, 32);
                }
                // Color swatch
                if (e.id !== null) {
                    const c = e.color === '#rainbow'
                        ? `hsl(${(performance.now() * 0.2) % 360}, 100%, 60%)`
                        : e.color;
                    ctx.fillStyle = c;
                    ctx.fillRect(px + 24, yLine + 4, 22, 22);
                    ctx.strokeStyle = '#000';
                    ctx.strokeRect(px + 24, yLine + 4, 22, 22);
                }
                // Name + status
                ctx.fillStyle = e.owned ? '#fff' : '#666';
                ctx.font = 'bold 14px Courier New';
                ctx.fillText(e.name, px + 56, yLine + 18);
                ctx.font = '11px Courier New';
                if (isActive) {
                    ctx.fillStyle = '#88ff88';
                    ctx.fillText('[EQUIPPED]', px + pw - 130, yLine + 18);
                } else if (e.owned) {
                    ctx.fillStyle = '#88ddff';
                    ctx.fillText('[OWNED]', px + pw - 130, yLine + 18);
                } else if (e.id !== null) {
                    ctx.fillStyle = (rc >= e.rcCost) ? '#ffd744' : '#ff6644';
                    ctx.fillText(`${e.rcCost} RC`, px + pw - 130, yLine + 18);
                }
            }
            ctx.restore();
        }
    };

    return { flags, leaderboard, decor, miniBoss, skins };
})();


// ============================================================================
// ===== WISHLIST PART 2 — characters, mods, mech, replay, co-op, boss forms ==
// ============================================================================
Object.assign(WL, (function() {

    // ============================================================
    // 5. NEW CHARACTER — PRINCE (Mech King's Son)
    // ============================================================
    const newChar = {
        spec: {
            name: 'PRINCE',
            desc: "Mech King's son. Q: ROYAL DECREE (4 gold drones)",
            speed: 3.6, jumpForce: -10.6, gravity: 0.43,
            maxHp: 280, dashRange: 12, fireRateMul: 0.85, dmgMul: 1.2,
            color: '#ffd744', accent: '#ff2244',
            extraJumps: 1,
            ability: 'royalDecree', abilityCooldown: 540,
            unlocked: false, unlockedBy: 'mechking'
        },
        added: false,
        init() {
            if (this.added) return;
            if (typeof CHARACTERS === 'undefined') return;
            if (CHARACTERS.find(c => c.name === 'PRINCE')) { this.added = true; return; }
            CHARACTERS.push(this.spec);
            this.added = true;
            // If save already records mechking defeated, unlock automatically
            if (typeof save !== 'undefined') {
                const meta = save.getMeta();
                if (meta && meta.bossesDefeated >= 9) {
                    this.spec.unlocked = true;
                }
            }
        },
        // Called when MECH KING dies — unlock PRINCE on first kill
        onMechKingDefeated() {
            if (!this.added) return;
            if (this.spec.unlocked) return;
            this.spec.unlocked = true;
            if (typeof save !== 'undefined') save.markDirty();
            if (typeof shopMessage !== 'undefined') {
                shopMessage = {
                    text: '⚜ NEW CHARACTER UNLOCKED: PRINCE — Mech King\'s son ⚜',
                    timer: 360,
                    color: '#ffd744'
                };
            }
            if (typeof spawnParticles === 'function' && typeof player !== 'undefined') {
                for (let i = 0; i < 50; i++) {
                    const ang = Math.random() * Math.PI * 2;
                    spawnParticles(
                        player.x + player.w / 2 + Math.cos(ang) * 80,
                        player.y + player.h / 2 + Math.sin(ang) * 80,
                        '#ffd744', 3, 6
                    );
                }
            }
        },
        // Royal Decree ability — runs alongside the main ability dispatcher.
        // Spawns 4 gold homing drones that orbit the player and attack.
        royalDecree() {
            if (typeof player === 'undefined') return;
            if (typeof bullets === 'undefined') return;
            const cx = player.x + player.w / 2;
            const cy = player.y + player.h / 2;
            for (let d = 0; d < 4; d++) {
                const ang = (Math.PI * 2 / 4) * d;
                bullets.push({
                    x: cx + Math.cos(ang) * 40,
                    y: cy + Math.sin(ang) * 40,
                    vx: Math.cos(ang) * 6,
                    vy: Math.sin(ang) * 6,
                    life: 360,
                    damage: Math.max(60, Math.round(80 * (player.dmgMul || 1))),
                    color: '#ffd744', glow: '#ffaa00', size: 8,
                    pierce: false, hitEnemies: new Set(),
                    drone: true,
                    royalDrone: true
                });
            }
            if (typeof spawnParticles === 'function') {
                spawnParticles(cx, cy, '#ffd744', 30, 6);
            }
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: '⚜ ROYAL DECREE ⚜', timer: 80, color: '#ffd744' };
            }
            if (typeof audio !== 'undefined' && audio.play) audio.play('shoot');
        }
    };

    // ============================================================
    // 6. WEAPON MODS — slot 1-2 mods per weapon for stacking effects
    // ============================================================
    const mods = {
        STORAGE_KEY: 'neonRush.weaponMods.v1',
        defs: [
            { id: 'cryo',     name: 'CRYO ROUND',    color: '#88ccff', desc: 'Freezes enemy 90f',     scrapCost: 60 },
            { id: 'ricochet', name: 'BOUNCY ROUND',  color: '#ffaa00', desc: 'Bullets ricochet 1x',   scrapCost: 80 },
            { id: 'homing',   name: 'TRACER ROUND',  color: '#ff44dd', desc: 'Bullets gently home',   scrapCost: 100 },
            { id: 'shock',    name: 'SHOCK ROUND',   color: '#aaeeff', desc: 'Chain to nearest enemy',scrapCost: 120 },
            { id: 'poison',   name: 'TOXIC ROUND',   color: '#22ff44', desc: 'DoT 4s @ 8/tick',       scrapCost: 90 },
            { id: 'fire',     name: 'INCENDIARY',    color: '#ff4422', desc: 'Burn 2.5s @ 6/tick',    scrapCost: 70 }
        ],
        slots: {},                  // { weaponTier: [modId1, modId2] }
        unlocked: {},               // { modId: true } — bought from shop
        menuOpen: false,
        cursorRow: 0,               // 0=mod list, 1=apply slot
        cursorIdx: 0,
        applySlot: 0,               // 0 or 1 — which slot to fill
        init() {
            try {
                const raw = localStorage.getItem(this.STORAGE_KEY);
                if (!raw) return;
                const obj = JSON.parse(raw);
                if (obj.slots && typeof obj.slots === 'object') this.slots = obj.slots;
                if (obj.unlocked && typeof obj.unlocked === 'object') this.unlocked = obj.unlocked;
            } catch (e) {}
        },
        save() {
            try {
                localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
                    slots: this.slots,
                    unlocked: this.unlocked
                }));
            } catch (e) {}
        },
        getModsForWeapon(tier) {
            return this.slots[tier] || [];
        },
        // Apply mods to a freshly-fired bullet. Called from a hook below.
        applyToBullet(bullet, weaponTier) {
            if (!WL.flags.mods) return;
            const ml = this.getModsForWeapon(weaponTier);
            if (!ml || ml.length === 0) return;
            bullet._wlMods = ml.slice();
            // Visual: tint trail color from first mod
            const firstDef = this.defs.find(d => d.id === ml[0]);
            if (firstDef) {
                bullet._wlModColor = firstDef.color;
            }
            for (const m of ml) {
                if (m === 'ricochet') {
                    bullet.bouncesLeft = (bullet.bouncesLeft || 0) + 1;
                    bullet._wlBouncy = true;
                } else if (m === 'homing') {
                    bullet._wlHoming = true;
                } else if (m === 'cryo') {
                    bullet._wlCryo = true;
                } else if (m === 'shock') {
                    bullet._wlShock = true;
                } else if (m === 'poison') {
                    bullet._wlPoison = true;
                } else if (m === 'fire') {
                    bullet._wlFire = true;
                }
            }
        },
        // Tick homing/ricochet/glow on bullets each frame
        tickBullets() {
            if (!WL.flags.mods) return;
            if (typeof bullets === 'undefined') return;
            for (const b of bullets) {
                if (!b._wlMods) continue;
                // Homing — gentle pull toward nearest enemy
                if (b._wlHoming && typeof enemies !== 'undefined') {
                    let nearest = null, ndist = 360 * 360;
                    for (const e of enemies) {
                        if (!e || e.hp <= 0) continue;
                        const dx = (e.x + e.w / 2) - b.x;
                        const dy = (e.y + e.h / 2) - b.y;
                        const d = dx * dx + dy * dy;
                        if (d < ndist) { ndist = d; nearest = e; }
                    }
                    if (nearest) {
                        const dx = (nearest.x + nearest.w / 2) - b.x;
                        const dy = (nearest.y + nearest.h / 2) - b.y;
                        const d = Math.sqrt(dx * dx + dy * dy) || 1;
                        const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
                        b.vx += (dx / d) * 0.4;
                        b.vy += (dy / d) * 0.4;
                        // Renormalize so bullet doesn't keep accelerating
                        const newSpeed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
                        if (newSpeed > 0) {
                            b.vx = (b.vx / newSpeed) * speed;
                            b.vy = (b.vy / newSpeed) * speed;
                        }
                    }
                }
                // Glow trail
                if (b._wlModColor) {
                    if (typeof spawnParticles === 'function' && Math.random() < 0.4) {
                        spawnParticles(b.x, b.y, b._wlModColor, 1, 1);
                    }
                }
            }
        },
        // Apply mod-specific effects on enemy hit. Called from hook.
        onBulletHitEnemy(bullet, enemy) {
            if (!WL.flags.mods) return;
            if (!bullet._wlMods) return;
            for (const m of bullet._wlMods) {
                if (m === 'cryo') {
                    enemy._wlFrozen = (enemy._wlFrozen || 0) + 90;
                    if (typeof spawnParticles === 'function') {
                        spawnParticles(enemy.x + enemy.w / 2, enemy.y + enemy.h / 2, '#88ccff', 8, 3);
                    }
                } else if (m === 'shock') {
                    // Find a second enemy near the hit and zap it for 50% damage
                    if (typeof enemies !== 'undefined') {
                        let chainTarget = null, cd = 220 * 220;
                        for (const e of enemies) {
                            if (e === enemy || !e || e.hp <= 0) continue;
                            const dx = (e.x + e.w / 2) - (enemy.x + enemy.w / 2);
                            const dy = (e.y + e.h / 2) - (enemy.y + enemy.h / 2);
                            const d = dx * dx + dy * dy;
                            if (d < cd) { cd = d; chainTarget = e; }
                        }
                        if (chainTarget) {
                            chainTarget.hp -= Math.round((bullet.damage || 30) * 0.5);
                            if (typeof spawnParticles === 'function') {
                                spawnParticles(chainTarget.x + chainTarget.w / 2, chainTarget.y + chainTarget.h / 2, '#aaeeff', 10, 4);
                            }
                            // Zigzag lightning trail (visual only)
                            if (typeof shockwaves !== 'undefined') {
                                shockwaves.push({
                                    x: (enemy.x + chainTarget.x) / 2 + enemy.w / 2,
                                    y: (enemy.y + chainTarget.y) / 2 + enemy.h / 2,
                                    radius: 4, maxRadius: 30, life: 16,
                                    color: '#aaeeff'
                                });
                            }
                        }
                    }
                } else if (m === 'poison') {
                    enemy._wlPoison = { duration: 240, dps: 8, lastTick: 0 };
                } else if (m === 'fire') {
                    enemy._wlBurn = { duration: 150, dps: 6, lastTick: 0 };
                }
            }
        },
        // Per-frame tick on enemies for DoT / freeze
        tickEnemies() {
            if (!WL.flags.mods) return;
            if (typeof enemies === 'undefined') return;
            for (const e of enemies) {
                if (!e || e.hp <= 0) continue;
                if (e._wlFrozen && e._wlFrozen > 0) {
                    e._wlFrozen--;
                    // Slow movement to ~25%
                    if (typeof e.vx === 'number') e.vx *= 0.4;
                }
                if (e._wlPoison && e._wlPoison.duration > 0) {
                    e._wlPoison.duration--;
                    e._wlPoison.lastTick++;
                    if (e._wlPoison.lastTick >= 12) {
                        e._wlPoison.lastTick = 0;
                        e.hp -= e._wlPoison.dps;
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(e.x + e.w / 2, e.y, '#22ff44', 2, 2);
                        }
                    }
                }
                if (e._wlBurn && e._wlBurn.duration > 0) {
                    e._wlBurn.duration--;
                    e._wlBurn.lastTick++;
                    if (e._wlBurn.lastTick >= 8) {
                        e._wlBurn.lastTick = 0;
                        e.hp -= e._wlBurn.dps;
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(e.x + Math.random() * e.w, e.y, '#ff4422', 2, 3);
                        }
                    }
                }
            }
        },
        // === MENU ===
        toggleMenu() {
            this.menuOpen = !this.menuOpen;
            this.cursorIdx = 0;
            this.cursorRow = 0;
        },
        handleKey(code) {
            if (!this.menuOpen) return false;
            if (code === 'Escape' || code === 'KeyO') {
                this.menuOpen = false;
                return true;
            }
            if (code === 'ArrowUp' || code === 'KeyW') {
                this.cursorIdx = Math.max(0, this.cursorIdx - 1);
                return true;
            }
            if (code === 'ArrowDown' || code === 'KeyS') {
                this.cursorIdx = Math.min(this.defs.length - 1, this.cursorIdx + 1);
                return true;
            }
            if (code === 'KeyB' || code === 'BracketLeft') {
                // Buy mod with scrap
                this.buyMod();
                return true;
            }
            if (code === 'Digit1' || code === 'Numpad1') {
                this.applySlot = 0;
                this.assignToCurrentWeapon();
                return true;
            }
            if (code === 'Digit2' || code === 'Numpad2') {
                this.applySlot = 1;
                this.assignToCurrentWeapon();
                return true;
            }
            if (code === 'KeyX' || code === 'Backspace') {
                this.clearCurrentWeaponMods();
                return true;
            }
            return false;
        },
        buyMod() {
            const m = this.defs[this.cursorIdx];
            if (!m) return;
            if (this.unlocked[m.id]) {
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: 'Already unlocked', timer: 60, color: '#aaa' };
                }
                return;
            }
            if (typeof player === 'undefined') return;
            if ((player.scrap || 0) < m.scrapCost) {
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: `Need ${m.scrapCost} scrap`, timer: 90, color: '#ff6644' };
                }
                return;
            }
            player.scrap -= m.scrapCost;
            this.unlocked[m.id] = true;
            this.save();
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: `★ MOD UNLOCKED: ${m.name} ★`, timer: 180, color: m.color };
            }
            if (typeof audio !== 'undefined' && audio.play) audio.play('coin');
        },
        assignToCurrentWeapon() {
            const m = this.defs[this.cursorIdx];
            if (!m || !this.unlocked[m.id]) {
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: 'Buy this mod first (B)', timer: 80, color: '#ff6644' };
                }
                return;
            }
            const tier = (typeof player !== 'undefined') ? player.weaponTier : 0;
            if (!this.slots[tier]) this.slots[tier] = [];
            this.slots[tier][this.applySlot] = m.id;
            this.save();
            if (typeof shopMessage !== 'undefined') {
                shopMessage = {
                    text: `${m.name} → SLOT ${this.applySlot + 1} (weapon tier ${tier})`,
                    timer: 120, color: m.color
                };
            }
        },
        clearCurrentWeaponMods() {
            const tier = (typeof player !== 'undefined') ? player.weaponTier : 0;
            this.slots[tier] = [];
            this.save();
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: 'Mods cleared from current weapon', timer: 90, color: '#aaa' };
            }
        },
        draw() {
            if (!this.menuOpen) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            const cw = canvas.width, ch = canvas.height;
            ctx.save();
            ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
            ctx.fillRect(0, 0, cw, ch);
            const pw = 540, ph = 440;
            const px = (cw - pw) / 2, py = (ch - ph) / 2;
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(px, py, pw, ph);
            ctx.strokeStyle = '#ff8844';
            ctx.lineWidth = 3;
            ctx.shadowColor = '#ff8844';
            ctx.shadowBlur = 16;
            ctx.strokeRect(px, py, pw, ph);
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#ffaa44';
            ctx.font = 'bold 22px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('★ WEAPON MODS ★', cw / 2, py + 30);
            // Current weapon info
            const tier = (typeof player !== 'undefined') ? player.weaponTier : 0;
            const w = (typeof WEAPONS !== 'undefined') ? WEAPONS[tier] : null;
            const wname = w ? w.name : '?';
            const slots = this.getModsForWeapon(tier);
            ctx.fillStyle = '#aaa';
            ctx.font = '11px Courier New';
            ctx.fillText(`Current weapon: ${wname} (tier ${tier})`, cw / 2, py + 50);
            ctx.fillText(`Slot 1: ${slots[0] ? this.defs.find(d => d.id === slots[0])?.name || '—' : 'EMPTY'}   Slot 2: ${slots[1] ? this.defs.find(d => d.id === slots[1])?.name || '—' : 'EMPTY'}`, cw / 2, py + 66);
            const sc = (typeof player !== 'undefined') ? player.scrap : 0;
            ctx.fillText(`Scrap: ${sc}  •  Up/Down: select  •  B: buy  •  1: assign slot 1  •  2: assign slot 2  •  X: clear`, cw / 2, py + 82);
            // Mod list
            ctx.textAlign = 'left';
            for (let i = 0; i < this.defs.length; i++) {
                const m = this.defs[i];
                const yLine = py + 110 + i * 40;
                const isSel = (i === this.cursorIdx);
                if (isSel) {
                    ctx.fillStyle = 'rgba(255, 215, 68, 0.15)';
                    ctx.fillRect(px + 16, yLine - 4, pw - 32, 38);
                    ctx.strokeStyle = '#ffd744';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(px + 16, yLine - 4, pw - 32, 38);
                }
                // Mod swatch
                ctx.fillStyle = m.color;
                ctx.fillRect(px + 24, yLine + 4, 22, 22);
                ctx.strokeStyle = '#000';
                ctx.strokeRect(px + 24, yLine + 4, 22, 22);
                // Name
                const owned = !!this.unlocked[m.id];
                ctx.fillStyle = owned ? '#fff' : '#666';
                ctx.font = 'bold 14px Courier New';
                ctx.fillText(m.name, px + 56, yLine + 14);
                ctx.font = '10px Courier New';
                ctx.fillStyle = '#aaa';
                ctx.fillText(m.desc, px + 56, yLine + 28);
                // Status
                ctx.font = 'bold 11px Courier New';
                if (owned) {
                    ctx.fillStyle = '#88ff88';
                    ctx.fillText('[OWNED]', px + pw - 130, yLine + 18);
                } else {
                    const can = (typeof player !== 'undefined' && (player.scrap || 0) >= m.scrapCost);
                    ctx.fillStyle = can ? '#ffd744' : '#ff6644';
                    ctx.fillText(`${m.scrapCost} scrap`, px + pw - 130, yLine + 18);
                }
                // Slot indicator
                const inSlot = slots.indexOf(m.id);
                if (inSlot !== -1) {
                    ctx.fillStyle = '#ff44dd';
                    ctx.fillText(`S${inSlot + 1}`, px + pw - 60, yLine + 18);
                }
            }
            ctx.restore();
        }
    };

    return { newChar, mods };
})());


// ============================================================================
// ===== WISHLIST PART 3 — convoy mech, death replay, co-op, boss forms =======
// ============================================================================
Object.assign(WL, (function() {

    // ============================================================
    // 7. NEW MECH FORM — CONVOY TRUCK (Optimus-style transformer)
    // ============================================================
    const convoyMech = {
        added: false,
        init() {
            if (this.added) return;
            if (typeof SC === 'undefined' || !SC.mechs || !SC.mechs.defs) return;
            if (SC.mechs.defs.convoy) { this.added = true; return; }
            const self = this;
            SC.mechs.defs.convoy = {
                name: 'CONVOY MECH',
                color: '#ff2244', accent: '#4488ff',
                speedMul: 1.4,
                jumpMul: 0.95,
                gravityMul: 1.0,
                extraJumps: 1,
                dmgMul: 1.5,
                spriteScale: 4.5,
                truckMode: true,
                ramDamage: 80,
                tagline: '🚛 CONVOY — Optimus-style truck transformer.',
                abilities: [
                    { keys: 'X (hold)', what: 'Truck mode: ram for 80 dmg' },
                    { keys: 'F',        what: 'Twin Matrix beams +50% dmg' },
                    { keys: 'WINGS',    what: 'Door-wings glide while falling' },
                    { keys: 'SPACE×3',  what: 'Triple jump' },
                    { keys: 'WEAK',     what: 'Slower jump, big silhouette' }
                ],
                renderSprite: (px, py, scale, t) => self.render(px, py, scale, t)
            };
            this.added = true;
        },
        render(px, py, scale, t) {
            // px, py = top-left of sprite (already scaled by spriteScale)
            // Drawn relative to that origin. Hitbox feet anchor handled by caller.
            if (typeof ctx === 'undefined') return;
            const W = 28 * scale, H = 40 * scale;
            const cx = px + W / 2;
            const cy = py + H / 2;
            ctx.save();
            // Body — red and blue Optimus colors
            // Torso
            ctx.fillStyle = '#aa1133';
            ctx.shadowColor = '#ff2244';
            ctx.shadowBlur = 12;
            ctx.fillRect(px + W * 0.18, py + H * 0.28, W * 0.64, H * 0.42);
            ctx.shadowBlur = 0;
            // Blue chest plate
            ctx.fillStyle = '#3366cc';
            ctx.fillRect(px + W * 0.32, py + H * 0.30, W * 0.36, H * 0.20);
            // Yellow window strip across chest (Optimus signature)
            ctx.fillStyle = '#ffd744';
            ctx.fillRect(px + W * 0.32, py + H * 0.36, W * 0.36, 4);
            // Head — blue helmet, red face
            ctx.fillStyle = '#3366cc';
            ctx.fillRect(px + W * 0.34, py + H * 0.04, W * 0.32, H * 0.18);
            // Ear pieces
            ctx.fillRect(px + W * 0.30, py + H * 0.10, W * 0.06, H * 0.10);
            ctx.fillRect(px + W * 0.64, py + H * 0.10, W * 0.06, H * 0.10);
            // Visor + face — silver mouth-plate
            ctx.fillStyle = '#ddddee';
            ctx.fillRect(px + W * 0.36, py + H * 0.16, W * 0.28, H * 0.05);
            // Glowing eyes
            ctx.fillStyle = '#88ddff';
            ctx.shadowColor = '#88ddff';
            ctx.shadowBlur = 8;
            ctx.fillRect(px + W * 0.38, py + H * 0.10, W * 0.08, H * 0.04);
            ctx.fillRect(px + W * 0.54, py + H * 0.10, W * 0.08, H * 0.04);
            ctx.shadowBlur = 0;
            // Shoulders — red pads with smokestacks (truck-like)
            ctx.fillStyle = '#882233';
            ctx.fillRect(px + W * 0.04, py + H * 0.22, W * 0.18, H * 0.18);
            ctx.fillRect(px + W * 0.78, py + H * 0.22, W * 0.18, H * 0.18);
            // Smokestack pipes
            ctx.fillStyle = '#888888';
            ctx.fillRect(px + W * 0.06, py + H * 0.16, W * 0.05, H * 0.10);
            ctx.fillRect(px + W * 0.89, py + H * 0.16, W * 0.05, H * 0.10);
            // Door-wings folded back when falling — small extension behind shoulders
            const wingFlap = Math.sin(t * 0.005) * 4;
            ctx.fillStyle = '#cc2244';
            ctx.beginPath();
            ctx.moveTo(px + W * 0.04, py + H * 0.30);
            ctx.lineTo(px - W * 0.06, py + H * 0.34 + wingFlap);
            ctx.lineTo(px + W * 0.04, py + H * 0.46);
            ctx.closePath();
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(px + W * 0.96, py + H * 0.30);
            ctx.lineTo(px + W * 1.06, py + H * 0.34 - wingFlap);
            ctx.lineTo(px + W * 0.96, py + H * 0.46);
            ctx.closePath();
            ctx.fill();
            // Arms
            ctx.fillStyle = '#3366cc';
            ctx.fillRect(px + W * 0.04, py + H * 0.40, W * 0.16, H * 0.24);
            ctx.fillRect(px + W * 0.80, py + H * 0.40, W * 0.16, H * 0.24);
            // Fists
            ctx.fillStyle = '#ddddee';
            ctx.fillRect(px + W * 0.02, py + H * 0.62, W * 0.18, H * 0.10);
            ctx.fillRect(px + W * 0.80, py + H * 0.62, W * 0.18, H * 0.10);
            // Pelvis/legs — blue
            ctx.fillStyle = '#3366cc';
            ctx.fillRect(px + W * 0.22, py + H * 0.70, W * 0.56, H * 0.20);
            // Boot toes — red
            ctx.fillStyle = '#aa1133';
            ctx.fillRect(px + W * 0.20, py + H * 0.88, W * 0.26, H * 0.10);
            ctx.fillRect(px + W * 0.54, py + H * 0.88, W * 0.26, H * 0.10);
            // Energon pulse on chest core
            const pulse = 0.6 + Math.sin(t * 0.005) * 0.4;
            ctx.fillStyle = '#88ffaa';
            ctx.shadowColor = '#88ffaa';
            ctx.shadowBlur = 10 * pulse;
            ctx.beginPath();
            ctx.arc(cx, py + H * 0.45, 4 + pulse * 2, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            ctx.restore();
        }
    };

    // ============================================================
    // 8. DEATH REPLAY SLOW-MO — auto-trigger on player death
    // ============================================================
    const deathReplay = {
        active: false,
        timer: 0,
        maxTimer: 90,
        deathPos: null,
        bannerTimer: 0,
        // Called once when gameState transitions to 'dead'
        trigger() {
            if (!WL.flags.deathReplay) return;
            if (this.active) return;
            this.active = true;
            this.timer = this.maxTimer;
            if (typeof player !== 'undefined') {
                this.deathPos = {
                    x: player.x + player.w / 2,
                    y: player.y + player.h / 2
                };
            }
            this.bannerTimer = 60;
            if (typeof screenShake !== 'undefined') screenShake = 18;
        },
        // Returns slow-mo factor — 0..1, where 1 = normal speed
        // Used by main loop / particle systems if they want to scale dt.
        slowFactor() {
            if (!this.active) return 1;
            const t = this.timer / this.maxTimer;     // 1..0
            // Slowest at start, ease back to 1 by end
            return 0.18 + (1 - t) * 0.82;
        },
        update() {
            if (!this.active) return;
            this.timer -= 1;
            if (this.timer <= 0) {
                this.active = false;
                this.deathPos = null;
                this.bannerTimer = 0;
            }
            if (this.bannerTimer > 0) this.bannerTimer--;
        },
        // Draw the SLOW-MO banner + red vignette while active
        draw() {
            if (!this.active) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            // Red vignette
            const t = this.timer / this.maxTimer;
            const grd = ctx.createRadialGradient(
                canvas.width / 2, canvas.height / 2, 0,
                canvas.width / 2, canvas.height / 2, canvas.width * 0.7
            );
            grd.addColorStop(0, 'rgba(255, 0, 0, 0)');
            grd.addColorStop(0.6, `rgba(255, 0, 0, ${0.1 * t})`);
            grd.addColorStop(1, `rgba(255, 0, 0, ${0.5 * t})`);
            ctx.fillStyle = grd;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            // Slow-mo banner
            if (this.bannerTimer > 0) {
                const a = Math.min(1, this.bannerTimer / 30);
                ctx.save();
                ctx.globalAlpha = a;
                ctx.fillStyle = '#ff3333';
                ctx.shadowColor = '#ff0000';
                ctx.shadowBlur = 18;
                ctx.font = 'bold 36px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText('▼ SLOW-MO ▼', canvas.width / 2, 80);
                ctx.shadowBlur = 0;
                ctx.restore();
            }
        }
    };

    // ============================================================
    // 9. LOCAL CO-OP — P2 companion bot with WASD+QE input
    //    Pragmatic version: P2 is a tethered ally that fires/melees
    //    in the main camera view. Activate with P key.
    // ============================================================
    const coop = {
        enabled: false,
        p2: null,
        // Per-frame input state for P2
        keys2: {
            left: false, right: false, jump: false,
            shoot: false, melee: false, dash: false
        },
        spawn() {
            if (!WL.flags.coop) return;
            if (this.enabled) {
                // Already on — toggle off
                this.disable();
                return;
            }
            if (typeof player === 'undefined') return;
            this.p2 = {
                x: player.x - 60, y: player.y, w: 28, h: 40,
                vx: 0, vy: 0,
                onGround: false,
                hp: 200, maxHp: 200,
                shootCooldown: 0,
                meleeCooldown: 0,
                dashCooldown: 0, dashing: false, dashTimer: 0,
                facing: 1,
                color: '#ff44dd', accent: '#ffaa00',
                jumps: 0, maxJumps: 2,
                invincible: 60,
                respawnTimer: 0
            };
            this.enabled = true;
            if (typeof shopMessage !== 'undefined') {
                shopMessage = {
                    text: '⚔ CO-OP ON — P2: WASD move, Q shoot, E melee, T jump',
                    timer: 240, color: '#ff44dd'
                };
            }
            if (typeof spawnParticles === 'function') {
                spawnParticles(this.p2.x + 14, this.p2.y, '#ff44dd', 30, 5);
            }
        },
        disable() {
            this.enabled = false;
            this.p2 = null;
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: 'Co-op disabled', timer: 90, color: '#aaa' };
            }
        },
        // Read current input state — uses WASD/Q/E/T for P2
        readInput() {
            if (typeof keys === 'undefined') return;
            // P2 movement: W=jump, A=left, D=right, S=dash, Q=shoot, E=melee, T=alt-jump
            // (W/A/S/D conflict with P1; but P1 uses arrows or A/D too)
            // To avoid conflict, P2 uses TGFH or similar. Let's use:
            //   T = jump, F = left, H = right, G = melee (P1's melee...)
            // Actually safer: use keypad-style — Numpad keys if avail,
            // otherwise the IJKL block.
            // I = up/jump, J = left, L = right, K = down/dash
            // U = shoot, O = melee
            this.keys2.left  = !!(keys['KeyJ']);
            this.keys2.right = !!(keys['KeyL']);
            this.keys2.jump  = !!(keys['KeyI']);
            this.keys2.shoot = !!(keys['KeyU']);
            this.keys2.melee = !!(keys['KeyP']);   // P doubles as melee for P2
            this.keys2.dash  = !!(keys['KeyK']);
        },
        update() {
            if (!this.enabled || !this.p2) return;
            this.readInput();
            const p2 = this.p2;
            // Respawn after death
            if (p2.respawnTimer > 0) {
                p2.respawnTimer--;
                if (p2.respawnTimer === 0) {
                    p2.hp = p2.maxHp;
                    p2.x = (typeof player !== 'undefined') ? player.x - 60 : 100;
                    p2.y = (typeof player !== 'undefined') ? player.y : 400;
                    p2.invincible = 90;
                    if (typeof shopMessage !== 'undefined') {
                        shopMessage = { text: 'P2 RESPAWN', timer: 60, color: '#ff44dd' };
                    }
                }
                return;
            }
            // Move
            if (this.keys2.left) { p2.vx = -3.6; p2.facing = -1; }
            else if (this.keys2.right) { p2.vx = 3.6; p2.facing = 1; }
            else { p2.vx *= 0.85; }
            // Jump
            if (this.keys2.jump && !p2.jumpHeld && p2.jumps < p2.maxJumps) {
                p2.vy = -10.5;
                p2.jumps++;
                p2.jumpHeld = true;
                if (typeof audio !== 'undefined' && audio.play) audio.play('jump');
            }
            if (!this.keys2.jump) p2.jumpHeld = false;
            // Dash (briefly faster + invincible)
            if (this.keys2.dash && !p2.dashHeld && p2.dashCooldown <= 0) {
                p2.dashing = true;
                p2.dashTimer = 8;
                p2.dashCooldown = 60;
                p2.invincible = 12;
                p2.dashHeld = true;
                if (typeof audio !== 'undefined' && audio.play) audio.play('dash');
            }
            if (!this.keys2.dash) p2.dashHeld = false;
            if (p2.dashCooldown > 0) p2.dashCooldown--;
            if (p2.dashing) {
                p2.dashTimer--;
                p2.vx = p2.facing * 8;
                if (p2.dashTimer <= 0) p2.dashing = false;
            }
            // Gravity
            p2.vy += 0.45;
            if (p2.vy > 12) p2.vy = 12;
            p2.x += p2.vx;
            p2.y += p2.vy;
            // Platform collision (simple — ground at y=600 + platforms array)
            p2.onGround = false;
            if (typeof platforms !== 'undefined') {
                for (const plat of platforms) {
                    if (p2.x + p2.w > plat.x && p2.x < plat.x + plat.w &&
                        p2.y + p2.h > plat.y && p2.y + p2.h < plat.y + plat.h + 14 &&
                        p2.vy >= 0) {
                        p2.y = plat.y - p2.h;
                        p2.vy = 0;
                        p2.onGround = true;
                        p2.jumps = 0;
                    }
                }
            }
            // Fallback ground at y=600
            if (p2.y + p2.h > 600) {
                p2.y = 600 - p2.h;
                p2.vy = 0;
                p2.onGround = true;
                p2.jumps = 0;
            }
            // Tether — keep P2 within 800px of P1 to prevent off-screen drift
            if (typeof player !== 'undefined') {
                const dx = p2.x - player.x;
                if (Math.abs(dx) > 800) {
                    p2.x = player.x + Math.sign(dx) * 800;
                    p2.vx = 0;
                }
            }
            // Shoot
            if (p2.shootCooldown > 0) p2.shootCooldown--;
            if (this.keys2.shoot && p2.shootCooldown <= 0) {
                this.shoot();
                p2.shootCooldown = 16;
            }
            // Melee
            if (p2.meleeCooldown > 0) p2.meleeCooldown--;
            if (this.keys2.melee && p2.meleeCooldown <= 0) {
                this.melee();
                p2.meleeCooldown = 30;
            }
            // i-frames
            if (p2.invincible > 0) p2.invincible--;
            // Take damage from enemy bullets
            if (p2.invincible <= 0 && typeof enemyBullets !== 'undefined') {
                for (let i = enemyBullets.length - 1; i >= 0; i--) {
                    const b = enemyBullets[i];
                    if (!b) continue;
                    if (b.x > p2.x && b.x < p2.x + p2.w && b.y > p2.y && b.y < p2.y + p2.h) {
                        p2.hp -= b.damage || 10;
                        p2.invincible = 30;
                        enemyBullets.splice(i, 1);
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(p2.x + p2.w/2, p2.y + p2.h/2, '#ff4444', 6, 3);
                        }
                        if (p2.hp <= 0) {
                            p2.respawnTimer = 240;
                            if (typeof shopMessage !== 'undefined') {
                                shopMessage = { text: 'P2 DOWN — respawn in 4s', timer: 90, color: '#ff4444' };
                            }
                            if (typeof spawnExplosion === 'function') {
                                spawnExplosion(p2.x + p2.w/2, p2.y + p2.h/2);
                            }
                        }
                        break;
                    }
                }
            }
        },
        shoot() {
            if (!this.p2) return;
            if (typeof bullets === 'undefined') return;
            const cx = this.p2.x + this.p2.w / 2;
            const cy = this.p2.y + this.p2.h / 2;
            bullets.push({
                x: cx + this.p2.facing * 18, y: cy,
                vx: this.p2.facing * 12, vy: 0,
                life: 80,
                damage: 35,
                color: '#ff44dd', glow: '#ffaa00', size: 6,
                pierce: false, hitEnemies: new Set(),
                fromP2: true
            });
            if (typeof audio !== 'undefined' && audio.play) audio.play('shoot');
        },
        melee() {
            if (!this.p2) return;
            if (typeof enemies === 'undefined') return;
            const reach = 60;
            const dmg = 60;
            const cx = this.p2.x + this.p2.w / 2;
            const cy = this.p2.y + this.p2.h / 2;
            const ax = cx + this.p2.facing * (reach / 2);
            for (const e of enemies) {
                if (!e || e.hp <= 0) continue;
                const ex = e.x + e.w / 2;
                const ey = e.y + e.h / 2;
                if (Math.abs(ex - ax) < (reach + e.w / 2) && Math.abs(ey - cy) < 50) {
                    e.hp -= dmg;
                    if (typeof spawnParticles === 'function') {
                        spawnParticles(ex, ey, '#ff44dd', 6, 4);
                    }
                }
            }
            if (typeof audio !== 'undefined' && audio.play) audio.play('melee');
        },
        draw() {
            if (!this.enabled || !this.p2) return;
            if (typeof ctx === 'undefined' || typeof camera === 'undefined') return;
            const p2 = this.p2;
            if (p2.respawnTimer > 0) return;   // hidden during respawn
            const sx = p2.x - camera.x;
            const sy = p2.y - camera.y;
            ctx.save();
            // Body
            const flicker = (p2.invincible > 0 && (p2.invincible % 6) < 3);
            if (flicker) ctx.globalAlpha = 0.4;
            ctx.fillStyle = p2.color;
            ctx.shadowColor = p2.color;
            ctx.shadowBlur = 12;
            ctx.fillRect(sx, sy, p2.w, p2.h);
            ctx.shadowBlur = 0;
            // Accent stripe
            ctx.fillStyle = p2.accent;
            ctx.fillRect(sx + 4, sy + 8, p2.w - 8, 4);
            // Eye
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(sx + (p2.facing > 0 ? p2.w - 10 : 4), sy + 14, 6, 4);
            // Name tag
            ctx.fillStyle = '#ff44dd';
            ctx.font = 'bold 9px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('P2', sx + p2.w / 2, sy - 4);
            // HP bar
            const hpFrac = Math.max(0, p2.hp / p2.maxHp);
            ctx.fillStyle = '#330011';
            ctx.fillRect(sx - 4, sy - 14, p2.w + 8, 4);
            ctx.fillStyle = hpFrac > 0.5 ? '#88ff88' : (hpFrac > 0.25 ? '#ffd744' : '#ff4444');
            ctx.fillRect(sx - 4, sy - 14, (p2.w + 8) * hpFrac, 4);
            ctx.restore();
        },
        // Tether-pull bullets fired by P2 hit a boss → counts toward kill
        // (handled implicitly because b.fromP2 doesn't change normal flow)
        toggle() { this.spawn(); }
    };

    // ============================================================
    // BOSS TRANSFORMATION FORMS — DRAGON, KAIJU, MONSTER
    // Add as alt rush-transformations on NG+ loop 2+ (or at random in
    // loop 1 with low odds). They REPLACE the standard rush-form for
    // a randomly-picked subset of bosses each loop.
    // ============================================================
    const bossForms = {
        // Three new monstrous forms with custom render layers + abilities
        forms: {
            dragon: {
                name: 'BLOOD DRAGON', color: '#ff2244', accent: '#ffd744',
                drawOverlay: (e, ex, ey) => {
                    if (typeof ctx === 'undefined') return;
                    const t = performance.now() * 0.003;
                    const cx = ex + e.w / 2;
                    const cy = ey + e.h / 2;
                    ctx.save();
                    ctx.shadowColor = '#ff2244';
                    ctx.shadowBlur = 14;
                    // Dragon wings — leathery, segmented
                    for (const side of [-1, 1]) {
                        ctx.fillStyle = 'rgba(170, 30, 30, 0.85)';
                        ctx.beginPath();
                        ctx.moveTo(cx, cy - 10);
                        const wingFlap = Math.sin(t * 4) * 0.3;
                        for (let s = 1; s <= 3; s++) {
                            const ang = side * (Math.PI / 6) * s + wingFlap * side;
                            const ext = 50 + s * 20;
                            const wx = cx + Math.cos(Math.PI + ang) * ext;
                            const wy = cy - 30 + Math.sin(Math.PI + ang) * ext * 0.6;
                            ctx.lineTo(wx, wy);
                        }
                        ctx.lineTo(cx + side * 30, cy + 30);
                        ctx.closePath();
                        ctx.fill();
                    }
                    // Dragon horns rising from head
                    ctx.fillStyle = '#ffd744';
                    for (let h = -1; h <= 1; h += 2) {
                        ctx.beginPath();
                        ctx.moveTo(cx + h * 24, ey - 4);
                        ctx.lineTo(cx + h * 30, ey - 26);
                        ctx.lineTo(cx + h * 18, ey - 10);
                        ctx.closePath();
                        ctx.fill();
                    }
                    // Tail — wavy red trail behind boss
                    ctx.strokeStyle = '#ff2244';
                    ctx.lineWidth = 8;
                    ctx.beginPath();
                    ctx.moveTo(cx, cy + e.h * 0.4);
                    for (let s = 1; s <= 8; s++) {
                        const tx = cx - 30 * s * Math.cos(t + s * 0.4);
                        const ty = cy + e.h * 0.4 + 4 * s + Math.sin(t * 2 + s) * 12;
                        ctx.lineTo(tx, ty);
                    }
                    ctx.stroke();
                    ctx.lineWidth = 1;
                    ctx.shadowBlur = 0;
                    ctx.restore();
                },
                ability: (e) => {
                    // Fire breath — cone of fire bullets toward player
                    if (typeof player === 'undefined' || typeof enemyBullets === 'undefined') return;
                    if (!e._dragonTimer) e._dragonTimer = 0;
                    e._dragonTimer--;
                    if (e._dragonTimer <= 0) {
                        e._dragonTimer = 60;
                        const baseAng = Math.atan2(
                            (player.y + player.h / 2) - (e.y + e.h / 2),
                            (player.x + player.w / 2) - (e.x + e.w / 2)
                        );
                        for (let b = -3; b <= 3; b++) {
                            const ang = baseAng + b * 0.10;
                            enemyBullets.push({
                                x: e.x + e.w / 2,
                                y: e.y + e.h / 2,
                                vx: Math.cos(ang) * 8,
                                vy: Math.sin(ang) * 8,
                                life: 120,
                                color: '#ff4422', glow: '#ffaa00',
                                damage: 14, big: false, fire: true
                            });
                        }
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(e.x + e.w / 2, e.y + e.h / 2, '#ffaa00', 8, 5);
                        }
                    }
                }
            },
            kaiju: {
                name: 'KAIJU LORD', color: '#22ff44', accent: '#ffd744',
                drawOverlay: (e, ex, ey) => {
                    if (typeof ctx === 'undefined') return;
                    const t = performance.now() * 0.003;
                    const cx = ex + e.w / 2;
                    const cy = ey + e.h / 2;
                    ctx.save();
                    ctx.shadowColor = '#22ff44';
                    ctx.shadowBlur = 18;
                    // Spiked back row
                    for (let s = 0; s < 6; s++) {
                        const sx = cx - e.w * 0.3 + s * (e.w * 0.6 / 5);
                        const sy = ey - 4 - Math.abs(Math.sin(s * 0.8 + t)) * 6;
                        const sh = 14 + Math.sin(s) * 6;
                        ctx.fillStyle = '#118822';
                        ctx.beginPath();
                        ctx.moveTo(sx - 5, sy);
                        ctx.lineTo(sx, sy - sh);
                        ctx.lineTo(sx + 5, sy);
                        ctx.closePath();
                        ctx.fill();
                    }
                    // Glowing radioactive eyes
                    ctx.fillStyle = '#22ff44';
                    ctx.shadowBlur = 12;
                    for (let h = -1; h <= 1; h += 2) {
                        ctx.beginPath();
                        ctx.arc(cx + h * 20, ey + 16, 6 + Math.sin(t * 3) * 1.5, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    // Tail — chunky and wavy
                    ctx.strokeStyle = '#118822';
                    ctx.lineWidth = 14;
                    ctx.beginPath();
                    ctx.moveTo(cx, cy + e.h * 0.4);
                    for (let s = 1; s <= 5; s++) {
                        const tx = cx - 50 - 30 * s;
                        const ty = cy + e.h * 0.4 + Math.sin(t * 2 + s * 0.5) * 18;
                        ctx.lineTo(tx, ty);
                    }
                    ctx.stroke();
                    ctx.lineWidth = 1;
                    ctx.shadowBlur = 0;
                    ctx.restore();
                },
                ability: (e) => {
                    // Kaiju roar — periodic shockwave that knocks player back
                    if (typeof player === 'undefined') return;
                    if (!e._kaijuTimer) e._kaijuTimer = 0;
                    e._kaijuTimer--;
                    if (e._kaijuTimer <= 0) {
                        e._kaijuTimer = 200;
                        const dx = (player.x + player.w / 2) - (e.x + e.w / 2);
                        const dy = (player.y + player.h / 2) - (e.y + e.h / 2);
                        const d = Math.sqrt(dx * dx + dy * dy) || 1;
                        if (d < 600) {
                            // Knockback
                            player.vx = (dx / d) * 18;
                            player.vy = -8;
                            if (typeof screenShake !== 'undefined') screenShake = 24;
                        }
                        // Shockwave visual
                        if (typeof shockwaves !== 'undefined') {
                            shockwaves.push({
                                x: e.x + e.w / 2, y: e.y + e.h / 2,
                                radius: 30, maxRadius: 600, life: 30,
                                color: '#22ff44'
                            });
                        }
                        if (typeof shopMessage !== 'undefined') {
                            shopMessage = { text: '☠ KAIJU ROAR ☠', timer: 60, color: '#22ff44' };
                        }
                    }
                }
            },
            monster: {
                name: 'NIGHTMARE BEAST', color: '#aa00ff', accent: '#ffffff',
                drawOverlay: (e, ex, ey) => {
                    if (typeof ctx === 'undefined') return;
                    const t = performance.now() * 0.003;
                    const cx = ex + e.w / 2;
                    const cy = ey + e.h / 2;
                    ctx.save();
                    ctx.shadowColor = '#aa00ff';
                    ctx.shadowBlur = 20;
                    // Multiple eyes — 6 randomly placed glowing purple pupils
                    ctx.fillStyle = '#ff44ff';
                    for (let i = 0; i < 6; i++) {
                        const ang = (Math.PI * 2 / 6) * i + t * 0.3;
                        const r = 14 + Math.sin(t * 2 + i) * 4;
                        const px = cx + Math.cos(ang) * 22;
                        const py = ey + 18 + Math.sin(ang) * 12;
                        ctx.beginPath();
                        ctx.arc(px, py, 4 + Math.sin(t * 4 + i) * 1.5, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    // Tendrils — 4 wavy purple tendrils whipping around
                    ctx.strokeStyle = 'rgba(170, 0, 255, 0.7)';
                    ctx.lineWidth = 6;
                    for (let tt = 0; tt < 4; tt++) {
                        ctx.beginPath();
                        ctx.moveTo(cx, cy);
                        for (let s = 1; s <= 6; s++) {
                            const phase = t + tt * 1.5 + s * 0.4;
                            const ext = 14 * s;
                            const ang = (Math.PI * 2 / 4) * tt + Math.sin(phase) * 0.4;
                            const px = cx + Math.cos(ang) * ext;
                            const py = cy + Math.sin(ang) * ext * 0.7 + Math.cos(phase) * 6;
                            ctx.lineTo(px, py);
                        }
                        ctx.stroke();
                    }
                    ctx.lineWidth = 1;
                    // Floating skull halo — 3 small skulls orbiting
                    ctx.fillStyle = '#ffffff';
                    for (let s = 0; s < 3; s++) {
                        const ang = t + (Math.PI * 2 / 3) * s;
                        const sx = cx + Math.cos(ang) * 60;
                        const sy = cy - 20 + Math.sin(ang) * 30;
                        ctx.beginPath();
                        ctx.arc(sx, sy, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.fillStyle = '#000';
                        ctx.fillRect(sx - 3, sy - 1, 2, 2);
                        ctx.fillRect(sx + 1, sy - 1, 2, 2);
                        ctx.fillStyle = '#ffffff';
                    }
                    ctx.shadowBlur = 0;
                    ctx.restore();
                },
                ability: (e) => {
                    // Spawn dark void rifts that pull the player toward boss
                    if (typeof player === 'undefined') return;
                    if (!e._monsterTimer) e._monsterTimer = 0;
                    e._monsterTimer--;
                    if (e._monsterTimer <= 0) {
                        e._monsterTimer = 180;
                        const dx = (e.x + e.w / 2) - (player.x + player.w / 2);
                        const dy = (e.y + e.h / 2) - (player.y + player.h / 2);
                        const d = Math.sqrt(dx * dx + dy * dy) || 1;
                        if (d < 500) {
                            player.vx += (dx / d) * 6;
                            player.vy += (dy / d) * 4;
                        }
                        // Spawn 4 dark void bullets
                        if (typeof enemyBullets !== 'undefined') {
                            for (let i = 0; i < 4; i++) {
                                const ang = (Math.PI * 2 / 4) * i + Math.random() * 0.3;
                                enemyBullets.push({
                                    x: e.x + e.w / 2,
                                    y: e.y + e.h / 2,
                                    vx: Math.cos(ang) * 5,
                                    vy: Math.sin(ang) * 5,
                                    life: 200,
                                    color: '#aa00ff', glow: '#ff44ff',
                                    damage: 18, big: true
                                });
                            }
                        }
                        if (typeof shopMessage !== 'undefined') {
                            shopMessage = { text: '☠ NIGHTMARE PULL ☠', timer: 60, color: '#aa00ff' };
                        }
                    }
                }
            }
        },
        // Pick a form for a given boss based on rush loop + boss subtype
        pickForm(e) {
            if (!WL.flags.bossForms) return null;
            // === FINAL BOSS ONLY === (Jun 7 v3) — the kid asked for the
            // dragon/kaiju/monster transformations to fire ONLY on the
            // FINAL BOSS PHASE, not on every gauntlet boss. So we now
            // gate strictly on subtype = mechking or voidgod. The 8
            // regular gauntlet bosses use the existing per-subtype rush
            // forms (RIOT KING, BOMBER PRIME, etc.) without the monster
            // overlay.
            const subtype = e.subtype || 'mech';
            if (subtype !== 'mechking' && subtype !== 'voidgod') return null;
            // Always pick a form for finals — no random gating, since
            // this IS the climactic moment. Loop number deterministically
            // rotates through DRAGON / KAIJU / MONSTER each NG+ run.
            if (typeof bossRush === 'undefined' || !bossRush) return null;
            const loop = bossRush.loop || 0;
            const formIds = Object.keys(this.forms);
            let h = 0;
            for (const c of subtype) h = (h * 31 + c.charCodeAt(0)) & 0xffff;
            const idx = (h + loop) % formIds.length;
            return formIds[idx];
        },
        // Apply form to a boss when it transforms (called from hook below)
        applyForm(e) {
            if (!WL.flags.bossForms) return;
            if (e._wlBossForm) return;   // already applied
            const formId = this.pickForm(e);
            if (!formId) return;
            const form = this.forms[formId];
            if (!form) return;
            e._wlBossForm = formId;
            e._wlBossFormName = form.name;
            // Override rush form name + color so the cinematic banner uses it
            e._rushFormName = form.name;
            e._rushTransformColor = form.color;
            e._rushFormAccent = form.accent;
            // Tag the boss for HP boost (these forms are tougher)
            e.maxHp = Math.round(e.maxHp * 1.25);
            e.hp = Math.min(e.hp + Math.round(e.hp * 0.25), e.maxHp);
            if (typeof shopMessage !== 'undefined') {
                shopMessage = { text: `☠ TRANSFORMS INTO ${form.name} ☠`, timer: 240, color: form.color };
            }
            if (typeof spawnParticles === 'function') {
                for (let i = 0; i < 40; i++) {
                    const ang = Math.random() * Math.PI * 2;
                    spawnParticles(
                        e.x + e.w / 2 + Math.cos(ang) * 60,
                        e.y + e.h / 2 + Math.sin(ang) * 60,
                        form.color, 3, 6
                    );
                }
            }
        },
        // Per-frame tick: run form ability + draw overlay
        tickAndDraw(e, ex, ey) {
            if (!WL.flags.bossForms) return;
            if (!e._wlBossForm) return;
            const form = this.forms[e._wlBossForm];
            if (!form) return;
            // Run ability
            if (form.ability) form.ability(e);
            // Draw overlay
            if (form.drawOverlay) form.drawOverlay(e, ex, ey);
        }
    };

    return { convoyMech, deathReplay, coop, bossForms };
})());


// ============================================================================
// ===== WISHLIST WIRE-UP — hooks into existing game systems =================
// Every wrapper runs the original FIRST, then catches any WL-side error so
// a bug in this module can NEVER freeze the original game loop.
// ============================================================================
(function() {

    // Safety helper — runs `fn` and swallows + logs any thrown error so the
    // original game's frame loop never gets broken by a WL-side bug. Errors
    // are reported via console.warn with a label so they're easy to spot.
    function safe(label, fn) {
        try { return fn(); }
        catch (e) {
            // Throttle log spam — print each label at most once per second
            const now = Date.now();
            if (!safe._last) safe._last = {};
            if (!safe._last[label] || now - safe._last[label] > 1000) {
                safe._last[label] = now;
                console.warn('[WL safe] ' + label + ' error:', e && e.message ? e.message : e);
            }
        }
    }

    // ---- INIT ----
    safe('init', () => {
        if (WL.leaderboard) WL.leaderboard.init();
        if (WL.skins) WL.skins.init();
        if (WL.mods) WL.mods.init();
        if (WL.newChar) WL.newChar.init();
        if (WL.convoyMech) WL.convoyMech.init();
    });

    // ---- APPLY CHARACTER → APPLY SKIN ----
    if (typeof applyCharacter === 'function') {
        const _origApplyChar = applyCharacter;
        applyCharacter = function(idx) {
            _origApplyChar.apply(this, arguments);
            safe('applyCharacter:skins', () => { if (WL.skins) WL.skins.apply(); });
        };
    }

    // ---- BUILD LEVEL → SPAWN DECOR + RECORD STAGE START ----
    if (typeof buildLevel === 'function') {
        const _origBuild = buildLevel;
        let _wlLastBuiltStage = -1;
        buildLevel = function() {
            _origBuild.apply(this, arguments);
            safe('buildLevel:decor', () => {
                const cs = (typeof currentStage !== 'undefined') ? currentStage : 0;
                if (WL.decor) WL.decor.spawn(cs);
                if (WL.leaderboard && cs !== _wlLastBuiltStage) {
                    WL.leaderboard.startStage();
                    _wlLastBuiltStage = cs;
                }
            });
        };
    }

    // ---- DRAW BACKGROUND → APPEND DECORATIONS ----
    if (typeof drawBackground === 'function') {
        const _origDrawBg = drawBackground;
        drawBackground = function() {
            _origDrawBg.apply(this, arguments);
            safe('drawBackground:decor', () => { if (WL.decor) WL.decor.draw(); });
        };
    }

    // ---- DRAW HUD → APPEND MENUS, REPLAY, COOP HELP, BOSS ARROW ----
    // Single wrap (was two — the boss arrow was a separate wrap; merging
    // makes the chain shallower and the per-frame code easier to reason
    // about).
    if (typeof drawHUD === 'function') {
        const _origDrawHud = drawHUD;
        drawHUD = function() {
            _origDrawHud.apply(this, arguments);
            // Skin / mod menus, death replay overlay
            safe('drawHUD:menus', () => {
                if (WL.skins) WL.skins.draw();
                if (WL.mods) WL.mods.draw();
                if (WL.deathReplay) WL.deathReplay.draw();
            });
            // Co-op help banner
            safe('drawHUD:coopBanner', () => {
                if (!(WL.coop && WL.coop.enabled)) return;
                ctx.save();
                ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
                ctx.fillRect(8, canvas.height - 56, 280, 48);
                ctx.fillStyle = '#ff44dd';
                ctx.font = 'bold 11px Courier New';
                ctx.textAlign = 'left';
                ctx.fillText('CO-OP — P2 CONTROLS', 18, canvas.height - 38);
                ctx.fillStyle = '#aaa';
                ctx.font = '9px Courier New';
                ctx.fillText('I=jump  J=left  L=right  K=dash  U=shoot  P=melee', 18, canvas.height - 22);
                ctx.fillText('[Shift+P toggle co-op]', 18, canvas.height - 10);
                ctx.restore();
            });
            // Boss off-screen indicator
            safe('drawHUD:bossArrow', () => {
                if (typeof gameState !== 'undefined' && gameState !== 'playing') return;
                if (typeof enemies === 'undefined' || typeof camera === 'undefined') return;
                const boss = enemies.find(e => e && e.type === 'boss' && e.hp > 0);
                if (!boss) return;
                const bx = boss.x + boss.w / 2;
                const by = boss.y + boss.h / 2;
                const sx = bx - camera.x;
                const sy = by - camera.y;
                const cw = canvas.width, ch = canvas.height;
                const margin = 60;
                if (sx >= -margin && sx <= cw + margin && sy >= -margin && sy <= ch + margin) return;
                const ax = Math.max(40, Math.min(cw - 40, sx));
                const ay = Math.max(80, Math.min(ch - 60, sy));
                const dx = sx - cw / 2;
                const dy = sy - ch / 2;
                const ang = Math.atan2(dy, dx);
                ctx.save();
                ctx.translate(ax, ay);
                ctx.rotate(ang);
                const pulse = 0.7 + Math.sin(performance.now() * 0.01) * 0.3;
                ctx.fillStyle = boss.color || '#ff4422';
                ctx.shadowColor = boss.color || '#ff4422';
                ctx.shadowBlur = 16 * pulse;
                ctx.beginPath();
                ctx.moveTo(20, 0);
                ctx.lineTo(-12, -10);
                ctx.lineTo(-6, 0);
                ctx.lineTo(-12, 10);
                ctx.closePath();
                ctx.fill();
                ctx.shadowBlur = 0;
                ctx.restore();
                ctx.save();
                const dist = Math.round(Math.sqrt(dx * dx + dy * dy));
                ctx.fillStyle = '#ffffff';
                ctx.font = 'bold 11px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText(`BOSS ${dist}px`, ax, ay + 24);
                ctx.restore();
            });
        };
    }

    // ---- DRAW PLAYER → DRAW P2 ----
    if (typeof drawPlayer === 'function') {
        const _origDrawPlayer = drawPlayer;
        drawPlayer = function() {
            _origDrawPlayer.apply(this, arguments);
            safe('drawPlayer:coop', () => { if (WL.coop) WL.coop.draw(); });
        };
    }

    // ---- HANDLE ENEMY KILLED → MECH KING UNLOCK + LEADERBOARD ----
    if (typeof handleEnemyKilled === 'function') {
        const _origHandleKill = handleEnemyKilled;
        handleEnemyKilled = function(e, j) {
            _origHandleKill.apply(this, arguments);
            safe('handleEnemyKilled:wl', () => {
                if (e && e.type === 'boss' && e.subtype === 'mechking' && WL.newChar) {
                    WL.newChar.onMechKingDefeated();
                }
                if (e && e.type === 'boss' && WL.leaderboard) {
                    const inRush = (typeof bossRush !== 'undefined' && bossRush && bossRush.active);
                    if (!inRush && typeof currentStage !== 'undefined') {
                        WL.leaderboard.onStageClear(currentStage);
                    }
                }
                if (e && e.type === 'boss' && e.subtype === 'voidgod' && WL.leaderboard) {
                    WL.leaderboard.onBossRushClear();
                }
            });
        };
    }

    // ---- TRIGGER BOSS RUSH TRANSFORM → APPLY DRAGON/KAIJU/MONSTER FORM ----
    if (typeof triggerBossRushTransform === 'function') {
        const _origTrigger = triggerBossRushTransform;
        triggerBossRushTransform = function(e) {
            _origTrigger.apply(this, arguments);
            safe('triggerBossRushTransform:form', () => {
                if (WL.bossForms) WL.bossForms.applyForm(e);
            });
        };
    }

    // ---- DRAW BOSS BODY → ADD FORM OVERLAY ----
    if (typeof drawBossBody === 'function') {
        const _origDrawBoss = drawBossBody;
        drawBossBody = function(ex, ey, e) {
            _origDrawBoss.apply(this, arguments);
            safe('drawBossBody:form', () => {
                if (WL.bossForms) WL.bossForms.tickAndDraw(e, ex, ey);
            });
        };
    }

    // ---- ADVANCE BOSS RUSH → CHECK FOR MINI-BOSS ANTECHAMBER ----
    if (typeof advanceBossRush === 'function') {
        const _origAdvance = advanceBossRush;
        advanceBossRush = function() {
            const intercepted = safe('advanceBossRush:miniBoss', () => {
                if (typeof bossRush !== 'undefined' && bossRush && bossRush.active) {
                    const nextIdx = bossRush.index;
                    if (nextIdx >= 1 && nextIdx <= 7 && WL.miniBoss) {
                        return WL.miniBoss.trigger(nextIdx);
                    }
                }
                return false;
            });
            if (intercepted) return;   // wave deferred boss spawn
            _origAdvance.apply(this, arguments);
        };
    }

    // ---- START BOSS RUSH → RECORD LEADERBOARD START ----
    if (typeof startBossRush === 'function') {
        const _origStartRush = startBossRush;
        startBossRush = function() {
            _origStartRush.apply(this, arguments);
            safe('startBossRush:lb', () => {
                if (WL.leaderboard) WL.leaderboard.startBossRush();
            });
        };
    }

    // ---- SHOOT BULLET → APPLY WEAPON MODS ----
    if (typeof shootBullet === 'function') {
        const _origShoot = shootBullet;
        shootBullet = function() {
            const before = (typeof bullets !== 'undefined') ? bullets.length : 0;
            _origShoot.apply(this, arguments);
            safe('shootBullet:mods', () => {
                if (!WL.mods || typeof bullets === 'undefined' || typeof player === 'undefined') return;
                const after = bullets.length;
                for (let i = before; i < after; i++) {
                    WL.mods.applyToBullet(bullets[i], player.weaponTier);
                }
            });
        };
    }

    // ---- DRAW GAME OVER → APPEND LEADERBOARD PANEL ----
    if (typeof drawGameOver === 'function') {
        const _origDrawGameOver = drawGameOver;
        drawGameOver = function() {
            _origDrawGameOver.apply(this, arguments);
            safe('drawGameOver:lb', () => {
                if (WL.leaderboard) WL.leaderboard.drawFullPanel();
            });
        };
    }

    // ---- DRAW STAGE COMPLETE → APPEND LEADERBOARD ROW ----
    if (typeof drawStageComplete === 'function') {
        const _origDrawSc = drawStageComplete;
        drawStageComplete = function() {
            _origDrawSc.apply(this, arguments);
            safe('drawStageComplete:lb', () => {
                if (WL.leaderboard && typeof currentStage !== 'undefined') {
                    WL.leaderboard.drawForStage(currentStage);
                }
            });
        };
    }

    // ---- KEYBOARD HOOKS — K, O, Shift+P toggle menus / co-op ----
    if (typeof document !== 'undefined') {
        document.addEventListener('keydown', e => {
            safe('keydown', () => {
                if (typeof shopOpen !== 'undefined' && shopOpen) return;
                const np = document.getElementById('name-prompt');
                if (np && np.style.display !== 'none') return;
                if (WL.mods && WL.mods.menuOpen) {
                    if (WL.mods.handleKey(e.code)) {
                        e.preventDefault();
                        return;
                    }
                }
                if (WL.skins && WL.skins.menuOpen) {
                    if (WL.skins.handleKey(e.code)) {
                        e.preventDefault();
                        return;
                    }
                }
                if (e.code === 'KeyK' && WL.skins) {
                    if (typeof gameState !== 'undefined' && (gameState === 'cutscene' || gameState === 'intro')) return;
                    if (WL.mods && WL.mods.menuOpen) return;
                    WL.skins.toggleMenu();
                    e.preventDefault();
                } else if (e.code === 'KeyO' && WL.mods) {
                    if (typeof gameState !== 'undefined' && (gameState === 'cutscene' || gameState === 'intro')) return;
                    if (WL.skins && WL.skins.menuOpen) return;
                    WL.mods.toggleMenu();
                    e.preventDefault();
                } else if (e.code === 'KeyP' && WL.coop) {
                    if (typeof gameState !== 'undefined' && (gameState === 'cutscene' || gameState === 'intro' || gameState === 'charSelect')) return;
                    if (WL.skins && WL.skins.menuOpen) return;
                    if (WL.mods && WL.mods.menuOpen) return;
                    if (e.shiftKey) {
                        WL.coop.toggle();
                        e.preventDefault();
                    }
                }
            });
        }, true);
    }

    // ---- PER-FRAME UPDATE / DRAW HOOK via requestAnimationFrame ----
    // CRITICAL: the original gameLoop schedules requestAnimationFrame for
    // the next frame. If the original throws, the rAF chain breaks. We
    // can't safely catch errors INSIDE the original. But MY tick code is
    // safe-wrapped so a WL bug can never freeze the game.
    if (typeof gameLoop === 'function') {
        const _origLoop = gameLoop;
        let _wlPrevState = null;
        gameLoop = function(ts) {
            _origLoop.apply(this, arguments);
            safe('gameLoop:tick', () => {
                if (typeof gameState !== 'undefined') {
                    if (gameState !== _wlPrevState) {
                        if (gameState === 'dead' && WL.deathReplay) {
                            WL.deathReplay.trigger();
                        }
                        _wlPrevState = gameState;
                    }
                }
                if (typeof gameState !== 'undefined' && gameState === 'playing') {
                    if (WL.mods) {
                        WL.mods.tickBullets();
                        WL.mods.tickEnemies();
                    }
                    if (WL.coop) WL.coop.update();
                    if (WL.miniBoss) WL.miniBoss.update();
                    if (WL.skins && WL.skins.selected === 'rainbow') WL.skins.apply();
                }
                if (WL.deathReplay) WL.deathReplay.update();
            });
        };
    }

    console.log('[WL] Wishlist features loaded — leaderboard, decor, miniBoss, skins, PRINCE, mods, CONVOY mech, death replay, co-op, boss forms.');
})();


// ============================================================================
// ===== WISHLIST PART 4 — OBSTACLES (lasers, acid bombs, spikes, saws...) ====
// New obstacle types that spawn per-stage, scaling with stage difficulty.
// All obstacles live in a single array `obstacles[]` per spawn cycle, ticked
// every frame, drawn in world space, and check player collision for damage.
// ============================================================================
Object.assign(WL, (function() {

    const obstacles = {
        items: [],                      // { kind, x, y, w, h, ... }
        lastBuiltStage: -1,
        // Per-stage spawn budget — higher stages get more obstacles
        // [stage] = { laser, acid, spike, saw, pendulum, mine }
        spawnBudgets: [
            { laser: 0, acid: 0, spike: 1, saw: 0, pendulum: 0, mine: 0 },   // 1
            { laser: 1, acid: 0, spike: 2, saw: 0, pendulum: 0, mine: 0 },   // 2
            { laser: 1, acid: 1, spike: 2, saw: 1, pendulum: 0, mine: 1 },   // 3
            { laser: 2, acid: 1, spike: 2, saw: 1, pendulum: 1, mine: 1 },   // 4
            { laser: 2, acid: 2, spike: 3, saw: 1, pendulum: 1, mine: 2 },   // 5
            { laser: 3, acid: 2, spike: 3, saw: 2, pendulum: 1, mine: 2 },   // 6
            { laser: 3, acid: 3, spike: 4, saw: 2, pendulum: 2, mine: 3 },   // 7
            { laser: 4, acid: 3, spike: 4, saw: 3, pendulum: 2, mine: 3 }    // 8
        ],

        // ---- spawn ----
        spawn(stageIdx) {
            if (!WL.flags.obstacles) return;
            this.items = [];
            const budget = this.spawnBudgets[stageIdx] || this.spawnBudgets[0];
            // Skip stage 8 fortress where the layout is crammed already
            // (still spawn some, just fewer)
            for (let i = 0; i < budget.laser; i++)    this.items.push(this.makeLaser(stageIdx, i));
            for (let i = 0; i < budget.acid; i++)     this.items.push(this.makeAcid(stageIdx, i));
            for (let i = 0; i < budget.spike; i++)    this.items.push(this.makeSpike(stageIdx, i));
            for (let i = 0; i < budget.saw; i++)      this.items.push(this.makeSaw(stageIdx, i));
            for (let i = 0; i < budget.pendulum; i++) this.items.push(this.makePendulum(stageIdx, i));
            for (let i = 0; i < budget.mine; i++)     this.items.push(this.makeMine(stageIdx, i));
            this.lastBuiltStage = stageIdx;
        },

        // ---- factory functions ----
        // Each obstacle has its own update() + draw() shape. To keep things
        // simple all functions are top-level and the kind switch happens in
        // tick() / draw().

        // LASER SWEEP — vertical beam that moves horizontally across an area
        makeLaser(stageIdx, i) {
            const x = 700 + i * 800 + Math.random() * 200;
            return {
                kind: 'laser',
                x, y: 80,                       // top of beam
                length: 480,                    // beam height
                w: 8,                           // beam thickness
                vx: (Math.random() < 0.5 ? -1 : 1) * (1.6 + stageIdx * 0.15),
                rangeStart: x - 250,
                rangeEnd: x + 250,
                damage: 12 + stageIdx * 2,
                phase: 0,                       // for pulsing
                color: '#ff2244',
                glow: '#ff8866'
            };
        },

        // ACID BOMB DROP — periodically lobs an acid bomb that lands and
        // creates a green puddle. Player takes contact damage from puddle.
        makeAcid(stageIdx, i) {
            const x = 900 + i * 700 + Math.random() * 200;
            return {
                kind: 'acid',
                x, y: 200,                      // emitter position
                w: 22, h: 22,
                cooldown: 0,
                cooldownMax: 200 - stageIdx * 8,
                puddles: [],                    // active acid puddles
                damage: 8 + stageIdx,
                color: '#22ff44',
                glow: '#88ff88'
            };
        },

        // SPIKE TRAP — pops up from the ground for 60f, then retracts for
        // 90f. Player standing on it takes massive damage.
        makeSpike(stageIdx, i) {
            const x = 600 + i * 600 + Math.random() * 200;
            return {
                kind: 'spike',
                x, y: 552,                      // ground level
                w: 60, h: 24,
                phase: i * 30 + Math.random() * 60,    // staggered
                period: 150,
                upDuration: 60,
                damage: 30 + stageIdx * 3,
                color: '#aa8866',
                glow: '#ff8800'
            };
        },

        // BUZZSAW — spinning circular blade that patrols horizontally
        makeSaw(stageIdx, i) {
            const x = 850 + i * 900 + Math.random() * 200;
            const y = 450;
            return {
                kind: 'saw',
                x, y, w: 60, h: 60,
                radius: 30,
                vx: (Math.random() < 0.5 ? -1 : 1) * (2 + stageIdx * 0.2),
                rangeStart: x - 200,
                rangeEnd: x + 200,
                damage: 25 + stageIdx * 2,
                rotation: 0,
                color: '#aaccdd',
                glow: '#ffffff'
            };
        },

        // PENDULUM HAMMER — swings from ceiling, big AOE on ground impact
        makePendulum(stageIdx, i) {
            const x = 1100 + i * 1100 + Math.random() * 300;
            return {
                kind: 'pendulum',
                pivotX: x, pivotY: 60,
                length: 280,
                angle: 0,                       // current angle
                amplitude: Math.PI / 3,         // swing ±60°
                period: 90 - stageIdx * 4,      // frames per half-swing
                phase: i * 25,
                hammerW: 70, hammerH: 50,
                damage: 35 + stageIdx * 3,
                color: '#444466',
                accent: '#ff2244'
            };
        },

        // PROXIMITY MINE — sits on the ground, beeps when player within
        // 120px, then explodes (200px AOE)
        makeMine(stageIdx, i) {
            const x = 750 + i * 800 + Math.random() * 250;
            return {
                kind: 'mine',
                x, y: 580, w: 20, h: 12,
                triggerDist: 120,
                triggered: false,
                triggerTimer: 0,
                triggerDuration: 60,            // frames until detonation
                aoeRadius: 200,
                damage: 50 + stageIdx * 4,
                exploded: false,
                cooldown: 0,
                respawnAfter: 360,              // re-arm after 6s
                color: '#ff2244',
                glow: '#ffaa00'
            };
        },

        // ---- update ----
        tick() {
            if (!WL.flags.obstacles) return;
            if (typeof gameState !== 'undefined' && gameState !== 'playing') return;
            for (const o of this.items) {
                switch (o.kind) {
                    case 'laser':    this.tickLaser(o); break;
                    case 'acid':     this.tickAcid(o); break;
                    case 'spike':    this.tickSpike(o); break;
                    case 'saw':      this.tickSaw(o); break;
                    case 'pendulum': this.tickPendulum(o); break;
                    case 'mine':     this.tickMine(o); break;
                }
            }
        },

        tickLaser(o) {
            o.x += o.vx;
            if (o.x < o.rangeStart) { o.x = o.rangeStart; o.vx = -o.vx; }
            if (o.x > o.rangeEnd)   { o.x = o.rangeEnd;   o.vx = -o.vx; }
            o.phase = (o.phase + 0.15) % (Math.PI * 2);
            // Player collision — beam is a vertical strip
            if (typeof player !== 'undefined' && player.invincible <= 0) {
                if (player.x + player.w > o.x - o.w / 2 &&
                    player.x < o.x + o.w / 2 &&
                    player.y + player.h > o.y &&
                    player.y < o.y + o.length) {
                    this.hurtPlayer(o.damage, o.color);
                }
            }
        },

        tickAcid(o) {
            o.cooldown--;
            if (o.cooldown <= 0) {
                o.cooldown = o.cooldownMax + Math.floor(Math.random() * 60);
                // Drop a bomb at o.x + random offset ±60
                const dropX = o.x + (Math.random() - 0.5) * 120;
                o.puddles.push({
                    x: dropX, y: o.y,                  // start at emitter
                    vy: 4,
                    landed: false,
                    landX: dropX,
                    landY: 0,
                    radius: 0,
                    maxRadius: 36,
                    life: 360
                });
            }
            // Tick falling bombs + puddles
            for (let i = o.puddles.length - 1; i >= 0; i--) {
                const p = o.puddles[i];
                if (!p.landed) {
                    p.y += p.vy;
                    p.vy += 0.45;
                    if (p.y > 560) {
                        p.landed = true;
                        p.landY = 580;
                        p.landX = p.x;
                        if (typeof spawnParticles === 'function') {
                            spawnParticles(p.x, p.landY, '#22ff44', 12, 5);
                        }
                        if (typeof screenShake !== 'undefined') screenShake = Math.max(screenShake, 4);
                    }
                } else {
                    // Grow puddle, then fade
                    if (p.radius < p.maxRadius) p.radius += 1;
                    p.life--;
                    if (p.life <= 0) {
                        o.puddles.splice(i, 1);
                        continue;
                    }
                    // Damage player on contact
                    if (typeof player !== 'undefined' && player.invincible <= 0) {
                        const dx = (player.x + player.w / 2) - p.landX;
                        const dy = (player.y + player.h) - p.landY;
                        if (Math.abs(dx) < p.radius && dy > -8 && dy < 16) {
                            this.hurtPlayer(o.damage, o.color);
                        }
                    }
                }
            }
        },

        tickSpike(o) {
            o.phase++;
            const cycle = o.phase % o.period;
            const isUp = cycle < o.upDuration;
            if (isUp && typeof player !== 'undefined' && player.invincible <= 0) {
                if (player.x + player.w > o.x &&
                    player.x < o.x + o.w &&
                    player.y + player.h > o.y - 20) {
                    this.hurtPlayer(o.damage, o.glow);
                }
            }
            o._isUp = isUp;       // cache for draw
        },

        tickSaw(o) {
            o.x += o.vx;
            if (o.x < o.rangeStart) { o.x = o.rangeStart; o.vx = -o.vx; }
            if (o.x > o.rangeEnd)   { o.x = o.rangeEnd;   o.vx = -o.vx; }
            o.rotation += 0.4;
            // Circular collision with player
            if (typeof player !== 'undefined' && player.invincible <= 0) {
                const dx = (player.x + player.w / 2) - o.x;
                const dy = (player.y + player.h / 2) - o.y;
                if (dx * dx + dy * dy < (o.radius + 14) * (o.radius + 14)) {
                    this.hurtPlayer(o.damage, o.color);
                }
            }
        },

        tickPendulum(o) {
            o.phase++;
            // Sin wave swing
            o.angle = Math.sin(o.phase / o.period) * o.amplitude;
            // Hammer position
            const hx = o.pivotX + Math.sin(o.angle) * o.length;
            const hy = o.pivotY + Math.cos(o.angle) * o.length;
            o._hx = hx; o._hy = hy;
            // Box collision with hammer
            if (typeof player !== 'undefined' && player.invincible <= 0) {
                if (player.x + player.w > hx - o.hammerW / 2 &&
                    player.x < hx + o.hammerW / 2 &&
                    player.y + player.h > hy - o.hammerH / 2 &&
                    player.y < hy + o.hammerH / 2) {
                    this.hurtPlayer(o.damage, o.accent);
                    // Knockback
                    if (typeof player !== 'undefined') {
                        player.vx = (player.x < hx ? -1 : 1) * 12;
                        player.vy = -8;
                    }
                }
            }
        },

        tickMine(o) {
            if (o.exploded) {
                o.cooldown--;
                if (o.cooldown <= 0) {
                    // Re-arm
                    o.exploded = false;
                    o.triggered = false;
                    o.triggerTimer = 0;
                }
                return;
            }
            if (typeof player === 'undefined') return;
            const dx = (player.x + player.w / 2) - (o.x + o.w / 2);
            const dy = (player.y + player.h / 2) - (o.y + o.h / 2);
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (!o.triggered && dist < o.triggerDist) {
                o.triggered = true;
                o.triggerTimer = o.triggerDuration;
                if (typeof shopMessage !== 'undefined') {
                    shopMessage = { text: '⚠ MINE ARMED ⚠', timer: 60, color: '#ff8800' };
                }
                if (typeof audio !== 'undefined' && audio.play) audio.play('warning');
            }
            if (o.triggered) {
                o.triggerTimer--;
                if (o.triggerTimer <= 0) {
                    // BOOM
                    o.exploded = true;
                    o.cooldown = o.respawnAfter;
                    if (typeof spawnExplosion === 'function') {
                        spawnExplosion(o.x + o.w / 2, o.y + o.h / 2);
                    }
                    if (typeof spawnParticles === 'function') {
                        for (let i = 0; i < 30; i++) {
                            const ang = Math.random() * Math.PI * 2;
                            spawnParticles(
                                o.x + o.w / 2 + Math.cos(ang) * 30,
                                o.y + o.h / 2 + Math.sin(ang) * 30,
                                ['#ff2244', '#ffaa00', '#ffd744'][i % 3],
                                3, 8
                            );
                        }
                    }
                    if (typeof screenShake !== 'undefined') screenShake = 18;
                    // AOE damage
                    if (player.invincible <= 0 && dist < o.aoeRadius) {
                        const falloff = 1 - (dist / o.aoeRadius);
                        this.hurtPlayer(Math.round(o.damage * falloff), o.color);
                        // Knockback
                        if (dist > 0.1) {
                            player.vx = (dx / dist) * 14;
                            player.vy = -10;
                        }
                    }
                    // Damage nearby enemies too (mines are equal-opportunity)
                    if (typeof enemies !== 'undefined') {
                        for (const e of enemies) {
                            if (!e || e.hp <= 0) continue;
                            const edx = (e.x + e.w / 2) - (o.x + o.w / 2);
                            const edy = (e.y + e.h / 2) - (o.y + o.h / 2);
                            const ed = Math.sqrt(edx * edx + edy * edy);
                            if (ed < o.aoeRadius) {
                                const falloff = 1 - (ed / o.aoeRadius);
                                e.hp -= Math.round(o.damage * falloff);
                            }
                        }
                    }
                }
            }
        },

        // ---- damage helper ----
        hurtPlayer(amount, color) {
            if (typeof player === 'undefined') return;
            // Respect god mode if available
            if (typeof godMode !== 'undefined' && godMode) return;
            player.hp -= amount;
            player.invincible = 30;
            if (typeof spawnParticles === 'function') {
                spawnParticles(player.x + player.w / 2, player.y + player.h / 2, color || '#ff4444', 6, 3);
            }
            if (typeof screenShake !== 'undefined') screenShake = Math.max(screenShake || 0, 6);
            if (typeof audio !== 'undefined' && audio.play) audio.play('hit');
            if (player.hp <= 0 && typeof gameState !== 'undefined') {
                gameState = 'dead';
                if (typeof spawnExplosion === 'function') {
                    spawnExplosion(player.x + player.w / 2, player.y + player.h / 2);
                }
            }
        },

        // ---- draw ----
        draw() {
            if (!WL.flags.obstacles) return;
            if (typeof gameState !== 'undefined' && gameState !== 'playing') return;
            if (typeof ctx === 'undefined' || typeof camera === 'undefined') return;
            for (const o of this.items) {
                const sx = (o.x !== undefined ? o.x : (o.pivotX || 0)) - camera.x;
                if (sx < -300 || sx > canvas.width + 300) continue;
                ctx.save();
                switch (o.kind) {
                    case 'laser':    this.drawLaser(o); break;
                    case 'acid':     this.drawAcid(o); break;
                    case 'spike':    this.drawSpike(o); break;
                    case 'saw':      this.drawSaw(o); break;
                    case 'pendulum': this.drawPendulum(o); break;
                    case 'mine':     this.drawMine(o); break;
                }
                ctx.restore();
            }
        },

        drawLaser(o) {
            const sx = o.x - camera.x;
            // Emitter on ceiling
            ctx.fillStyle = '#660011';
            ctx.fillRect(sx - 16, o.y - 14, 32, 14);
            ctx.fillStyle = o.color;
            ctx.shadowColor = o.glow;
            ctx.shadowBlur = 14;
            ctx.fillRect(sx - 18, o.y - 12, 36, 8);
            // Beam
            const flicker = 0.7 + Math.sin(o.phase * 4) * 0.3;
            ctx.globalAlpha = flicker;
            ctx.fillStyle = o.color;
            ctx.fillRect(sx - o.w / 2, o.y, o.w, o.length);
            // Core hot strip
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(sx - 1, o.y, 2, o.length);
            ctx.shadowBlur = 0;
            ctx.globalAlpha = 1;
            // Floor splash where beam hits
            ctx.fillStyle = o.glow;
            ctx.globalAlpha = 0.3;
            ctx.beginPath();
            ctx.arc(sx, o.y + o.length, 18, 0, Math.PI);
            ctx.fill();
            ctx.globalAlpha = 1;
        },

        drawAcid(o) {
            const sx = o.x - camera.x;
            // Emitter — sci-fi nozzle hanging from ceiling
            ctx.fillStyle = '#226633';
            ctx.fillRect(sx - 12, o.y - 18, 24, 18);
            ctx.fillStyle = o.color;
            ctx.shadowColor = o.glow;
            ctx.shadowBlur = 8;
            ctx.fillRect(sx - 8, o.y - 4, 16, 8);
            ctx.shadowBlur = 0;
            // Falling bombs
            for (const p of o.puddles) {
                const psx = p.x - camera.x;
                if (!p.landed) {
                    // Falling drop — green with trail
                    ctx.fillStyle = o.glow;
                    ctx.shadowColor = o.color;
                    ctx.shadowBlur = 10;
                    ctx.beginPath();
                    ctx.arc(psx, p.y, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                    // Trail
                    ctx.globalAlpha = 0.4;
                    ctx.fillStyle = o.color;
                    for (let t = 1; t < 6; t++) {
                        ctx.beginPath();
                        ctx.arc(psx, p.y - t * 6, 8 - t, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    ctx.globalAlpha = 1;
                } else {
                    // Acid puddle on ground
                    ctx.fillStyle = o.color;
                    ctx.shadowColor = o.glow;
                    ctx.shadowBlur = 12;
                    ctx.globalAlpha = 0.7;
                    ctx.beginPath();
                    ctx.ellipse(psx, p.landY, p.radius, 8, 0, 0, Math.PI * 2);
                    ctx.fill();
                    // Bubbles
                    ctx.fillStyle = o.glow;
                    for (let b = 0; b < 4; b++) {
                        const bx = psx + (b - 1.5) * (p.radius / 2);
                        const by = p.landY - 2 - Math.sin(p.life * 0.1 + b) * 2;
                        ctx.beginPath();
                        ctx.arc(bx, by, 2 + Math.sin(p.life * 0.15 + b) * 1, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    ctx.globalAlpha = 1;
                    ctx.shadowBlur = 0;
                }
            }
        },

        drawSpike(o) {
            const sx = o.x - camera.x;
            const yBase = o.y;
            if (o._isUp) {
                // Extended spikes — sharp triangles
                ctx.fillStyle = o.color;
                ctx.shadowColor = o.glow;
                ctx.shadowBlur = 6;
                for (let s = 0; s < 5; s++) {
                    const tx = sx + s * (o.w / 5) + 6;
                    ctx.beginPath();
                    ctx.moveTo(tx - 5, yBase);
                    ctx.lineTo(tx, yBase - 20);
                    ctx.lineTo(tx + 5, yBase);
                    ctx.closePath();
                    ctx.fill();
                }
                ctx.shadowBlur = 0;
                // Base plate
                ctx.fillStyle = '#553322';
                ctx.fillRect(sx, yBase, o.w, 4);
            } else {
                // Retracted — just the slit in the floor
                ctx.fillStyle = '#222';
                ctx.fillRect(sx, yBase - 2, o.w, 4);
                ctx.fillStyle = '#553322';
                for (let s = 0; s < 5; s++) {
                    const tx = sx + s * (o.w / 5) + 6;
                    ctx.fillRect(tx - 1, yBase - 1, 2, 2);
                }
            }
        },

        drawSaw(o) {
            const sx = o.x - camera.x;
            const sy = o.y;
            ctx.translate(sx, sy);
            ctx.rotate(o.rotation);
            // Outer toothed disc
            ctx.fillStyle = o.color;
            ctx.shadowColor = o.glow;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            for (let s = 0; s < 12; s++) {
                const ang = (Math.PI * 2 / 12) * s;
                const r1 = o.radius;
                const r2 = o.radius - 8;
                ctx.lineTo(Math.cos(ang) * r1, Math.sin(ang) * r1);
                ctx.lineTo(Math.cos(ang + Math.PI / 12) * r2, Math.sin(ang + Math.PI / 12) * r2);
            }
            ctx.closePath();
            ctx.fill();
            ctx.shadowBlur = 0;
            // Center hub
            ctx.fillStyle = '#222';
            ctx.beginPath();
            ctx.arc(0, 0, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = o.glow;
            ctx.beginPath();
            ctx.arc(0, 0, 4, 0, Math.PI * 2);
            ctx.fill();
            // Spokes
            ctx.strokeStyle = '#888';
            ctx.lineWidth = 2;
            for (let s = 0; s < 4; s++) {
                const ang = (Math.PI / 2) * s;
                ctx.beginPath();
                ctx.moveTo(0, 0);
                ctx.lineTo(Math.cos(ang) * (o.radius - 10), Math.sin(ang) * (o.radius - 10));
                ctx.stroke();
            }
            ctx.lineWidth = 1;
        },

        drawPendulum(o) {
            const px = o.pivotX - camera.x;
            const py = o.pivotY;
            // Mount on ceiling
            ctx.fillStyle = '#222';
            ctx.fillRect(px - 12, py - 14, 24, 20);
            ctx.fillStyle = '#888';
            ctx.beginPath();
            ctx.arc(px, py, 5, 0, Math.PI * 2);
            ctx.fill();
            // Rope/chain
            const hx = px + Math.sin(o.angle) * o.length;
            const hy = py + Math.cos(o.angle) * o.length;
            ctx.strokeStyle = '#666';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(px, py);
            ctx.lineTo(hx, hy);
            ctx.stroke();
            ctx.lineWidth = 1;
            // Hammer
            ctx.fillStyle = o.color;
            ctx.shadowColor = o.accent;
            ctx.shadowBlur = 12;
            ctx.fillRect(hx - o.hammerW / 2, hy - o.hammerH / 2, o.hammerW, o.hammerH);
            ctx.shadowBlur = 0;
            // Spike on hammer
            ctx.fillStyle = o.accent;
            ctx.beginPath();
            ctx.moveTo(hx, hy + o.hammerH / 2);
            ctx.lineTo(hx - 8, hy + o.hammerH / 2 + 14);
            ctx.lineTo(hx + 8, hy + o.hammerH / 2 + 14);
            ctx.closePath();
            ctx.fill();
            // Glowing eye on hammer
            ctx.fillStyle = '#ffff44';
            ctx.shadowColor = '#ffaa00';
            ctx.shadowBlur = 8;
            ctx.beginPath();
            ctx.arc(hx, hy, 4, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
        },

        drawMine(o) {
            const sx = o.x - camera.x;
            const sy = o.y;
            if (o.exploded) {
                // Empty crater
                ctx.fillStyle = '#222';
                ctx.fillRect(sx - 4, sy + 4, o.w + 8, 8);
                return;
            }
            // Mine body — black circle with red blink
            ctx.fillStyle = '#222';
            ctx.beginPath();
            ctx.arc(sx + o.w / 2, sy + o.h / 2, o.w / 2 + 2, 0, Math.PI * 2);
            ctx.fill();
            // Blinking light — fast when triggered
            const blinkRate = o.triggered ? 0.4 : 0.05;
            const lit = Math.sin(performance.now() * blinkRate * 0.01) > 0;
            ctx.fillStyle = (lit || o.triggered) ? o.color : '#444';
            ctx.shadowColor = o.color;
            ctx.shadowBlur = (o.triggered) ? 14 : 6;
            ctx.beginPath();
            ctx.arc(sx + o.w / 2, sy + o.h / 2, 4, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            // Triggered count-down ring
            if (o.triggered) {
                const frac = o.triggerTimer / o.triggerDuration;
                ctx.strokeStyle = o.color;
                ctx.shadowColor = o.glow;
                ctx.shadowBlur = 10;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(sx + o.w / 2, sy + o.h / 2, 16, 0, Math.PI * 2 * frac);
                ctx.stroke();
                ctx.shadowBlur = 0;
                ctx.lineWidth = 1;
            }
        }
    };

    // Add the obstacle flag to WL.flags so it can be toggled
    if (WL.flags) WL.flags.obstacles = true;

    return { obstacles };
})());

// Wire obstacles in via the same safe-wrapper pattern. These hooks
// piggyback on existing wraps (buildLevel, drawBackground, gameLoop).
(function() {
    if (!WL || !WL.obstacles) return;
    function safe(label, fn) {
        try { return fn(); }
        catch (e) {
            const now = Date.now();
            if (!safe._last) safe._last = {};
            if (!safe._last[label] || now - safe._last[label] > 1000) {
                safe._last[label] = now;
                console.warn('[WL safe] ' + label + ' error:', e && e.message ? e.message : e);
            }
        }
    }

    // Spawn on buildLevel (only when stage actually changes)
    if (typeof buildLevel === 'function') {
        const _origBuild2 = buildLevel;
        let _wlLastObstStage = -1;
        buildLevel = function() {
            _origBuild2.apply(this, arguments);
            safe('buildLevel:obstacles', () => {
                const cs = (typeof currentStage !== 'undefined') ? currentStage : 0;
                if (cs !== _wlLastObstStage) {
                    WL.obstacles.spawn(cs);
                    _wlLastObstStage = cs;
                }
            });
        };
    }

    // Tick from gameLoop wrapper
    if (typeof gameLoop === 'function') {
        const _origLoop2 = gameLoop;
        gameLoop = function(ts) {
            _origLoop2.apply(this, arguments);
            safe('gameLoop:obstacles', () => {
                if (WL.obstacles) WL.obstacles.tick();
            });
        };
    }

    // Draw from drawBackground wrapper (between bg and entities)
    if (typeof drawBackground === 'function') {
        const _origDrawBg2 = drawBackground;
        drawBackground = function() {
            _origDrawBg2.apply(this, arguments);
            safe('drawBackground:obstacles', () => {
                if (WL.obstacles) WL.obstacles.draw();
            });
        };
    }

    console.log('[WL] Obstacles loaded — laser sweep, acid bombs, spike traps, buzzsaws, pendulum hammers, proximity mines.');
})();


// ============================================================================
// ===== WISHLIST PART 5 — ANIME FINAL BOSS ENTRANCE ===========================
// Multi-stage cinematic overlay that fires when MECH KING or VOID GOD spawn.
// Phases:
//   0  (0-60f)    BLACKOUT — full-screen darkness with white energy crackle
//   1  (60-150f)  SILHOUETTE — boss outline visible through fog, slow zoom-in
//   2  (150-240f) NAME REVEAL — giant katakana-style title with red glow
//   3  (240-330f) DIALOGUE — three quick lines from the boss
//   4  (330-380f) FINAL FLASH — blinding white pulse, hand-off to gameplay
// During phases 0-3 the game is paused (boss can't attack, player input
// muted to non-movement keys). Phase 4 fades and resumes normal play.
// ============================================================================
Object.assign(WL, (function() {

    const animeEntrance = {
        active: false,
        boss: null,                  // reference to the boss entity
        phase: 0,
        phaseTimer: 0,
        phaseDurations: [60, 90, 90, 90, 50],   // total 380 frames ~ 6.3s
        lightning: [],               // dramatic lightning bolts
        sparks: [],                  // shower particles
        dialogueLines: [],
        currentLine: 0,
        // Per-boss dramatic dialogue
        BOSS_DIALOGUES: {
            mechking: [
                { text: 'YOU\'VE COME FAR, INTRUDER...', color: '#ff2244' },
                { text: 'BUT THIS THRONE WILL BE YOUR GRAVE.', color: '#ffd744' },
                { text: '⚜  R I S E ,  M E C H   K I N G  ⚜', color: '#ff8800' }
            ],
            voidgod: [
                { text: 'I HAVE WAITED AT THE EDGE OF EVERYTHING...', color: '#aa00ff' },
                { text: 'I WHISPERED TO MECH KING. AND OMEGA. AND BEFORE.', color: '#ff44ff' },
                { text: '☠  W I T N E S S   T H E   E N D  ☠', color: '#ff00ff' }
            ]
        },
        BOSS_TITLES: {
            mechking: { text: 'M E C H   K I N G', subtitle: 'THE THRONE DESCENDS', color: '#ff2244', glow: '#ffd744' },
            voidgod:  { text: 'V O I D   G O D',   subtitle: 'THE COSMIC TRUTH',   color: '#aa00ff', glow: '#ff44ff' }
        },

        trigger(boss) {
            if (!WL.flags.animeEntrance) return;
            if (this.active) return;
            const subtype = boss && boss.subtype;
            if (subtype !== 'mechking' && subtype !== 'voidgod') return;
            this.active = true;
            this.boss = boss;
            this.phase = 0;
            this.phaseTimer = this.phaseDurations[0];
            this.lightning = [];
            this.sparks = [];
            this.dialogueLines = this.BOSS_DIALOGUES[subtype] || [];
            this.currentLine = 0;
            // Freeze the boss so its attacks don't fire mid-cinematic
            boss._animeFrozen = true;
            // Big initial shake + sound
            if (typeof screenShake !== 'undefined') screenShake = 36;
            if (typeof audio !== 'undefined' && audio.play) {
                audio.play('bossIntro');
                audio.play('explosion', { throttle: 60 });
            }
        },

        update() {
            if (!this.active) return;
            this.phaseTimer--;
            // Spawn ambient lightning + sparks during cinematic
            if (Math.random() < 0.12) this.spawnLightning();
            if (Math.random() < 0.4) this.spawnSpark();
            for (let i = this.lightning.length - 1; i >= 0; i--) {
                const l = this.lightning[i];
                l.life--;
                if (l.life <= 0) this.lightning.splice(i, 1);
            }
            for (let i = this.sparks.length - 1; i >= 0; i--) {
                const s = this.sparks[i];
                s.x += s.vx;
                s.y += s.vy;
                s.vy += 0.15;
                s.life--;
                if (s.life <= 0) this.sparks.splice(i, 1);
            }
            // Phase advance
            if (this.phaseTimer <= 0) {
                this.phase++;
                if (this.phase >= this.phaseDurations.length) {
                    // End cinematic
                    this.active = false;
                    if (this.boss) {
                        this.boss._animeFrozen = false;
                        this.boss._animeEntrance = false;
                    }
                    // Big payload — final flash already happened in phase 4
                    if (typeof shopMessage !== 'undefined' && this.boss) {
                        const title = this.BOSS_TITLES[this.boss.subtype];
                        if (title) {
                            shopMessage = {
                                text: `⚔ ${title.text} — FIGHT! ⚔`,
                                timer: 180,
                                color: title.color
                            };
                        }
                    }
                    return;
                }
                this.phaseTimer = this.phaseDurations[this.phase];
                this.onPhaseEnter(this.phase);
            }
            // Per-phase tick
            if (this.phase === 3) {
                // Cycle dialogue lines — one line per ~30 frames
                const totalDur = this.phaseDurations[3];
                const elapsed = totalDur - this.phaseTimer;
                const linesPerLine = totalDur / Math.max(1, this.dialogueLines.length);
                this.currentLine = Math.min(this.dialogueLines.length - 1, Math.floor(elapsed / linesPerLine));
            }
        },

        onPhaseEnter(phase) {
            switch (phase) {
                case 1:
                    // Silhouette begin — burst of sparks
                    for (let i = 0; i < 30; i++) this.spawnSpark();
                    if (typeof screenShake !== 'undefined') screenShake = 18;
                    break;
                case 2:
                    // Name reveal — heavy shake + lightning
                    for (let i = 0; i < 8; i++) this.spawnLightning();
                    if (typeof screenShake !== 'undefined') screenShake = 26;
                    if (typeof audio !== 'undefined' && audio.play) audio.play('explosion');
                    break;
                case 3:
                    // Dialogue start
                    if (typeof audio !== 'undefined' && audio.play) audio.play('warning');
                    break;
                case 4:
                    // Final flash — biggest shake
                    if (typeof screenShake !== 'undefined') screenShake = 40;
                    if (typeof audio !== 'undefined' && audio.play) audio.play('explosion');
                    for (let i = 0; i < 60; i++) this.spawnSpark();
                    break;
            }
        },

        spawnLightning() {
            if (typeof canvas === 'undefined') return;
            const cx = canvas.width / 2 + (Math.random() - 0.5) * 200;
            this.lightning.push({
                x: cx,
                segments: this.makeLightningSegments(cx, 40, cx + (Math.random() - 0.5) * 400, canvas.height - 60),
                life: 14,
                color: this.boss && this.boss.subtype === 'voidgod' ? '#ff44ff' : '#ffd744'
            });
        },

        makeLightningSegments(x1, y1, x2, y2) {
            const segs = [];
            const steps = 8;
            let lx = x1, ly = y1;
            for (let i = 1; i <= steps; i++) {
                const t = i / steps;
                const ix = x1 + (x2 - x1) * t + (Math.random() - 0.5) * 40;
                const iy = y1 + (y2 - y1) * t + (Math.random() - 0.5) * 20;
                segs.push({ x1: lx, y1: ly, x2: ix, y2: iy });
                lx = ix; ly = iy;
            }
            return segs;
        },

        spawnSpark() {
            if (typeof canvas === 'undefined') return;
            this.sparks.push({
                x: Math.random() * canvas.width,
                y: 100 + Math.random() * 400,
                vx: (Math.random() - 0.5) * 4,
                vy: -2 - Math.random() * 4,
                life: 30 + Math.floor(Math.random() * 30),
                color: this.boss && this.boss.subtype === 'voidgod'
                    ? ['#aa00ff', '#ff44ff', '#ffffff'][Math.floor(Math.random() * 3)]
                    : ['#ff2244', '#ffd744', '#ffffff'][Math.floor(Math.random() * 3)]
            });
        },

        draw() {
            if (!this.active) return;
            if (typeof ctx === 'undefined' || typeof canvas === 'undefined') return;
            const cw = canvas.width, ch = canvas.height;
            const subtype = this.boss && this.boss.subtype;
            const title = this.BOSS_TITLES[subtype] || this.BOSS_TITLES.mechking;
            const phaseDur = this.phaseDurations[this.phase] || 1;
            const phaseProgress = 1 - (this.phaseTimer / phaseDur);

            ctx.save();
            // Black backdrop for ALL phases
            const bgAlpha =
                this.phase === 0 ? 0.95 :
                this.phase === 1 ? 0.92 :
                this.phase === 2 ? 0.85 :
                this.phase === 3 ? 0.78 :
                /* phase 4 */     Math.max(0, 0.78 - phaseProgress * 0.78);
            ctx.fillStyle = `rgba(0, 0, 0, ${bgAlpha})`;
            ctx.fillRect(0, 0, cw, ch);

            // Phase 0 — black with crackling white energy lines
            if (this.phase === 0) {
                ctx.strokeStyle = `rgba(255, 255, 255, ${0.5 + Math.random() * 0.5})`;
                ctx.lineWidth = 1;
                for (let i = 0; i < 6; i++) {
                    ctx.beginPath();
                    ctx.moveTo(Math.random() * cw, Math.random() * ch);
                    ctx.lineTo(Math.random() * cw, Math.random() * ch);
                    ctx.stroke();
                }
                // "FINAL BOSS" label fading in
                const a = Math.min(1, phaseProgress * 2);
                ctx.globalAlpha = a;
                ctx.fillStyle = title.color;
                ctx.shadowColor = title.glow;
                ctx.shadowBlur = 24;
                ctx.font = 'bold 36px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText('▼ FINAL BOSS ▼', cw / 2, ch / 2);
                ctx.shadowBlur = 0;
                ctx.globalAlpha = 1;
            }

            // Phase 1 — silhouette zoom-in (use a darker overlay with light
            // fog particles and a faint outline of the boss)
            if (this.phase === 1) {
                // Spotlight gradient
                const grd = ctx.createRadialGradient(
                    cw / 2, ch / 2, 50,
                    cw / 2, ch / 2, cw * 0.6
                );
                grd.addColorStop(0, `rgba(${title.color === '#ff2244' ? '255,30,50' : '170,0,255'}, ${0.18 + phaseProgress * 0.2})`);
                grd.addColorStop(1, 'rgba(0, 0, 0, 0)');
                ctx.fillStyle = grd;
                ctx.fillRect(0, 0, cw, ch);
                // Boss silhouette — drawn at center, growing
                if (this.boss) {
                    const scale = 0.4 + phaseProgress * 0.6;
                    const bw = this.boss.w * scale;
                    const bh = this.boss.h * scale;
                    const bx = cw / 2 - bw / 2;
                    const by = ch / 2 - bh / 2;
                    ctx.fillStyle = `rgba(0, 0, 0, 0.85)`;
                    ctx.fillRect(bx, by, bw, bh);
                    // Glowing eyes
                    ctx.fillStyle = title.color;
                    ctx.shadowColor = title.glow;
                    ctx.shadowBlur = 18;
                    ctx.beginPath();
                    ctx.arc(bx + bw * 0.30, by + bh * 0.25, 4 + phaseProgress * 4, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.arc(bx + bw * 0.70, by + bh * 0.25, 4 + phaseProgress * 4, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }
                // "APPROACHING..." label
                ctx.fillStyle = '#ff8866';
                ctx.shadowColor = '#ff2244';
                ctx.shadowBlur = 12;
                ctx.font = 'bold 18px Courier New';
                ctx.textAlign = 'center';
                ctx.fillText(subtype === 'voidgod' ? '▼ THE COSMOS BREAKS ▼' : '▼ THE THRONE DESCENDS ▼', cw / 2, 90);
                ctx.shadowBlur = 0;
            }

            // Phase 2 — NAME REVEAL — giant title with red lightning aura
            if (this.phase === 2) {
                // Title scales up + glows brighter as phase progresses
                const titleScale = 0.3 + phaseProgress * 0.7;
                ctx.save();
                ctx.translate(cw / 2, ch / 2);
                ctx.scale(titleScale, titleScale);
                ctx.fillStyle = title.color;
                ctx.shadowColor = title.glow;
                ctx.shadowBlur = 32 * phaseProgress;
                ctx.font = 'bold 72px Courier New';
                ctx.textAlign = 'center';
                // Draw stroke first for outline effect
                ctx.strokeStyle = '#000000';
                ctx.lineWidth = 6;
                ctx.strokeText(title.text, 0, 0);
                ctx.fillText(title.text, 0, 0);
                // Subtitle
                ctx.fillStyle = title.glow;
                ctx.font = 'bold 22px Courier New';
                ctx.fillText(title.subtitle, 0, 50);
                ctx.shadowBlur = 0;
                ctx.restore();
                // Lightning bolts crackle through
                ctx.strokeStyle = title.color;
                ctx.shadowColor = title.glow;
                ctx.shadowBlur = 14;
                ctx.lineWidth = 2;
                for (const l of this.lightning) {
                    ctx.globalAlpha = l.life / 14;
                    for (const seg of l.segments) {
                        ctx.beginPath();
                        ctx.moveTo(seg.x1, seg.y1);
                        ctx.lineTo(seg.x2, seg.y2);
                        ctx.stroke();
                    }
                }
                ctx.globalAlpha = 1;
                ctx.lineWidth = 1;
                ctx.shadowBlur = 0;
            }

            // Phase 3 — DIALOGUE — three quick lines, anime style
            if (this.phase === 3) {
                // Boss silhouette stays in upper-right
                if (this.boss) {
                    const bw = this.boss.w * 0.8;
                    const bh = this.boss.h * 0.8;
                    const bx = cw - bw - 60;
                    const by = 60;
                    // Subtle silhouette
                    ctx.fillStyle = `rgba(0, 0, 0, 0.85)`;
                    ctx.fillRect(bx, by, bw, bh);
                    ctx.strokeStyle = title.color;
                    ctx.shadowColor = title.glow;
                    ctx.shadowBlur = 14;
                    ctx.lineWidth = 3;
                    ctx.strokeRect(bx, by, bw, bh);
                    ctx.shadowBlur = 0;
                    ctx.lineWidth = 1;
                    // Eyes
                    ctx.fillStyle = title.color;
                    ctx.shadowColor = title.glow;
                    ctx.shadowBlur = 12;
                    ctx.beginPath();
                    ctx.arc(bx + bw * 0.30, by + bh * 0.25, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.arc(bx + bw * 0.70, by + bh * 0.25, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }
                // Dialogue panel — black box with thick gold border (anime style)
                const panelX = 40, panelY = ch - 200, panelW = cw - 80, panelH = 120;
                ctx.fillStyle = 'rgba(10, 0, 14, 0.96)';
                ctx.fillRect(panelX, panelY, panelW, panelH);
                ctx.strokeStyle = title.glow;
                ctx.shadowColor = title.color;
                ctx.shadowBlur = 18;
                ctx.lineWidth = 4;
                ctx.strokeRect(panelX, panelY, panelW, panelH);
                ctx.shadowBlur = 0;
                ctx.lineWidth = 1;
                // Speaker
                ctx.fillStyle = title.color;
                ctx.font = 'bold 22px Courier New';
                ctx.textAlign = 'left';
                ctx.fillText(title.text, panelX + 24, panelY + 32);
                // Current dialogue line
                const line = this.dialogueLines[this.currentLine];
                if (line) {
                    ctx.fillStyle = line.color;
                    ctx.shadowColor = line.color;
                    ctx.shadowBlur = 6;
                    ctx.font = 'bold 26px Courier New';
                    ctx.textAlign = 'center';
                    ctx.fillText(line.text, cw / 2, panelY + 78);
                    ctx.shadowBlur = 0;
                }
                // Dialogue progress dots
                ctx.fillStyle = '#888';
                ctx.font = '14px Courier New';
                ctx.textAlign = 'right';
                for (let i = 0; i < this.dialogueLines.length; i++) {
                    const dotX = panelX + panelW - 20 - (this.dialogueLines.length - 1 - i) * 16;
                    ctx.fillStyle = i === this.currentLine ? title.glow : '#444';
                    ctx.beginPath();
                    ctx.arc(dotX, panelY + 96, 5, 0, Math.PI * 2);
                    ctx.fill();
                }
            }

            // Phase 4 — final flash
            if (this.phase === 4) {
                // White-out flash that fades to clear
                const a = 1 - phaseProgress;
                ctx.fillStyle = `rgba(255, 255, 255, ${a})`;
                ctx.fillRect(0, 0, cw, ch);
            }

            // Sparks — drawn over everything in phases 0-3
            if (this.phase < 4) {
                for (const s of this.sparks) {
                    ctx.fillStyle = s.color;
                    ctx.shadowColor = s.color;
                    ctx.shadowBlur = 6;
                    ctx.beginPath();
                    ctx.arc(s.x, s.y, 2 + (s.life / 60) * 2, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.shadowBlur = 0;
            }

            ctx.restore();
        }
    };

    // Add the flag
    if (WL.flags) WL.flags.animeEntrance = true;

    return { animeEntrance };
})());

// ============================================================================
// ===== ANIME ENTRANCE WIRE-UP ===============================================
// ============================================================================
(function() {
    if (!WL || !WL.animeEntrance) return;
    function safe(label, fn) {
        try { return fn(); }
        catch (e) {
            const now = Date.now();
            if (!safe._last) safe._last = {};
            if (!safe._last[label] || now - safe._last[label] > 1000) {
                safe._last[label] = now;
                console.warn('[WL safe] ' + label + ' error:', e && e.message ? e.message : e);
            }
        }
    }

    // Detect anime-entrance triggers via gameLoop tick — every frame check
    // for newly-spawned mechking/voidgod with the _animeEntrance flag.
    // (Cleaner than wrapping spawnBossRushBoss + spawnSecretBoss separately.)
    if (typeof gameLoop === 'function') {
        const _origLoop3 = gameLoop;
        gameLoop = function(ts) {
            _origLoop3.apply(this, arguments);
            safe('gameLoop:animeEntrance', () => {
                // Look for a boss flagged for anime entrance
                if (typeof gameState === 'undefined' || gameState !== 'playing') return;
                if (typeof enemies === 'undefined') return;
                if (!WL.animeEntrance.active) {
                    for (const e of enemies) {
                        if (e && e._animeEntrance && (e.subtype === 'mechking' || e.subtype === 'voidgod')) {
                            WL.animeEntrance.trigger(e);
                            break;
                        }
                    }
                }
                WL.animeEntrance.update();
            });
        };
    }

    // Draw on top of HUD via the existing drawHUD wrap
    if (typeof drawHUD === 'function') {
        const _origDrawHud3 = drawHUD;
        drawHUD = function() {
            _origDrawHud3.apply(this, arguments);
            safe('drawHUD:animeEntrance', () => {
                if (WL.animeEntrance) WL.animeEntrance.draw();
            });
        };
    }

    // Freeze the boss's attacks while anime entrance is active. This
    // works by pre-empting updateEnemies for the affected boss. We hook
    // via wrapping the gameLoop again — when entrance is active, zero
    // out player invincibility-relevant flags and pause boss timers.
    // Simpler approach: just wrap updateEnemies to skip the flagged boss.
    if (typeof updateEnemies === 'function') {
        const _origUpdateEnemies = updateEnemies;
        updateEnemies = function() {
            // If anime entrance is active, freeze the boss for the duration.
            if (WL.animeEntrance && WL.animeEntrance.active) {
                // Buff the boss's i-frames so it can't take damage during entrance
                if (WL.animeEntrance.boss) {
                    WL.animeEntrance.boss.invincible = 60;
                }
                // Skip the entire update — boss/enemies wait for cinematic end.
                // Other enemies are paused too which is fine since the rush
                // arena only has the boss.
                return;
            }
            _origUpdateEnemies.apply(this, arguments);
        };
    }

    console.log('[WL] Anime final-boss entrance loaded — MECH KING / VOID GOD spawn cinematic.');
})();
